/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20241011-4","meetingId":"r06-c-settlement","date":"2024年10月11日","dateIso":"2024-10-11","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ４時４９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を181件整理しています。","topics":[{"id":"topic-01","title":"９時３０分開会 ◯新妻委員長 おはようございます。ただいまより、決算特別委員会を開きます。 それでは、令和５年度品川区一般会計歳入歳出決算","agenda":"９時３０分開会 ◯新妻委員長 おはようございます。ただいまより、決算特別委員会を開きます。 それでは、令和５年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"本日も１日、どうぞよろしくお願いいたします。私からは、４０１ページ、就学時健康診断、３７９ページ、区教員経費、３９９ページ、給食運営費についてお伺いします。","respondent":"柏木学務課長","answer":"就学時健診ですが、こちらは１年生になる前に、その子の健康状態を確認するために実施しておるものになります。こちらのほうは学校保健安全法に定められておりまして、教育委員会は実施をしなければいけないものになってあります。","id":"exchange-001"},{"speaker":"えのした委員","kind":"質問","question":"学校保健安全法の規定により、実施されていると理解をしております。昨年度はいつ頃実施されたのか、また、診断をされた人数等をお伺いいたします。","respondent":"柏木学務課長","answer":"実施につきましては、例年１０月から１１月の上旬にかけて実施をしているものになります。対象者は大体３,０００名となっています。","id":"exchange-002"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。就学時健康診断の中で、歯科健康診査も同じ人数ということでよろしいか尋ねました。","respondent":"柏木学務課長","answer":"就学時健診につきましては、その健診の中で、内科、歯科、耳鼻科、眼科の健診を行っておりますので、同じ人数です。","id":"exchange-003"},{"speaker":"えのした委員","kind":"質問","question":"この他区の現状は把握されておりましたでしょうか。そして、区の手当金額は何年度から規定されているのかお知らせください。","respondent":"柏木学務課長","answer":"他区の状況ですが、教育委員会のほうでも把握はしています。現在の健診の謝礼ですが、大体平成１３年度から今の金額のままとなっています。","id":"exchange-004"},{"speaker":"えのした委員","kind":"質問・要望","question":"平成１３年度からと確認が取れました。区のご見解をお伺いします。","respondent":"柏木学務課長","answer":"コロナ禍以降、就学時健診を生まれ月で分けてやるなどということで、以前よりも健診に関わる時間が延びてあります。そのようなことから、現在、謝礼の改定については検討をしています。","id":"exchange-005"},{"speaker":"えのした委員","kind":"質問・要望","question":"次に、教育経費についてお伺いします。そこでお伺いします。","respondent":"中谷指導課長","answer":"教員の配置についてですが、例年、初任者の教員の採用が増えているというような状況があります。１０名弱ぐらいというところなのですが、今年度の現時点においては、欠員の状況が２０名というような状況になっております。","id":"exchange-006"},{"speaker":"えのした委員","kind":"質問","question":"地域の学校にも話を伺いましたが、やはり、ご説明あったとおり、年度途中での産休・育休、また、病欠も非常に多いと聞いております。欠員の補充には大変苦労しているとの声もありますが、区のご見解をお伺いします。","respondent":"中谷指導課長","answer":"東京都が紹介する人材リスト、１つの学校でニーズがあったときにはスピーディーにアクセスできるというようなシステムを整えているところです。大学のほうには、１６大学に近隣のところでアクセスさせていただきまして…","id":"exchange-007"},{"speaker":"えのした委員","kind":"質問","question":"やはり産休・育休、区でも増加しているということで、文教委員会でも話が出たようですが、こちら最短で１か月で免許を出せる臨時免許状制度、このようなものがあるとお伺いしていますけれども、こちらについてお知らせください。","respondent":"中谷指導課長","answer":"およそ１か月程度で臨時免許状を発行できるというようなシステムになっておりまして、特に昨年度と今年度で、この免許状を活用して教員を配置するというような学校が増えているところです。","id":"exchange-008"},{"speaker":"えのした委員","kind":"質問","question":"続いて、品川区の固有教員についてお伺いします。現状の教員数と配置されている学校数を説明を求めました。","respondent":"中谷指導課長","answer":"申し上げます。教員数については２８名となっており、それぞれの配置校で活躍いただいているというようなところになっております。","id":"exchange-009"},{"speaker":"えのした委員","kind":"質問","question":"２８名。品川区のことをよく分かっている固有教員を、各学校に最低で１人でも配置できることが望ましいと考えますが、区のご見解をお伺いいたします。","respondent":"中谷指導課長","answer":"これまで３０名配置というところを目標としておりましたが、若手教員への指導に力を入れる学校経営の体制を取る学校が増えてきております。品川区の教育の牽引役がますます必要であると考えており、段階的な増員によって、将来的には各校に配置するなどの検討をしています。","id":"exchange-010"},{"speaker":"えのした委員","kind":"質問","question":"続きまして、給食運営費についてお伺いします。こちらの補助金交付の申請をされているとは思いますが、お伺いします。","respondent":"柏木学務課長","answer":"東京都の補助の件ですが、こちらのほう、品川区でも申請をしています。申請した金額につきましては、約６億３,７００万円です。","id":"exchange-011"},{"speaker":"えのした委員","kind":"質問","question":"大関校長にもお伺いしたところ、夏休み明けの９月には、給食は子どもたちの心のよりどころでもあるのではないでしょうか。国としてやるべき、給食費無償化の実施に一歩踏み出した森澤区長に改めて感謝するとともに、その熱い思いを一言いただけないか尋ねました。","respondent":"森澤区長","answer":"子どもの食の支援、非常に重要だと思っています。給食は必ず食べるものでありますので、しっかりとこれからも子どもの食の支援を行ってまいりたいと思っています。","id":"exchange-012"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、３８３ページの市民科・各教科充実経費に関連して、防災教育についてお伺いしていきたいと思います。中学生への防災教育の充実に努めていきたいとありましたが、学校現場ではどのようにこの教材を活用されていくのか、お聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"現在防災課のほうで中学生向けの教材を作成しております。次年度、各校においては、年間避難訓練を年１１回位置づけておりますが、そうした避難訓練の実施に合わせて教材を活用することを想定しています。","id":"exchange-013"},{"speaker":"ゆきた委員","kind":"質問","question":"教材を使用した生徒対象のアンケート調査では、４,４５０件のアンケートで、約７割が防災について興味を持つことができたとなっています。所管は防災課ですけれども、教育委員会はどのように関わって連携を取られているのか、お聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"現在教材の構成のほうに入っておりまして、教育委員会、教育総合支援センターのほうにも情報提供いただきながら、紙面の内容などといったところは、こちらのほうでも確認をさせていただいているところです。","id":"exchange-014"},{"speaker":"ゆきた委員","kind":"確認","question":"令和４年からタブレットで閲覧できるようになった防災ノートも充実した内容ですが、このはまっ子のプロジェクトのほうも確認させていただきました。現在品川区内の小中学校で行われているトイレ問題を意識啓発するような取組、訓練、現状をもし把握されていれば教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"委員ご案内のとおり、小・中学生の１人１台端末から防災ノートへのリンクが貼られておりまして、子どもたちはデジタル版を閲覧することができます。能登半島でかなりクローズアップされましたので、そうした事例も踏まえながら…","id":"exchange-015"},{"speaker":"ゆきた委員","kind":"質問","question":"今月の１０月１日に「災害用トイレガイド２０２４」が作成され、熊本地震、阪神・淡路大震災での劣悪なトイレ環境の一部が画像で紹介されています。災害教育として、こういったところをさらに伝えていく必要があると思いますけれども、ここについての認識についてお伺いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"そういったものを画像や映像を通して子どもたちが見て、実感を持って、危機感を持って準備を行うということは非常に有効な手だてだと考えています。ですから、小学生、中学生、発達段階に応じて、そういった効果的な教材の活用ができればとも考えております。","id":"exchange-016"},{"speaker":"ゆきた委員","kind":"質問","question":"今防災ノートの件でお伺いしましたけれども、感銘を受けるところがあると思いますが、今後この部分について進めてほしいと求めました。品川区でも、来年の２月に納入するトイレトラックのフェーズフリー利用として、改めて区の認識をお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"各学校におきましては、例えば消防車を呼んだり、透明なごみ収集車を呼んだり、そういった取組を今行っているところです。機会がありましたら、各学校の授業で、出前授業を進めていければと考えております。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問","question":"３８１ページのいじめ防止対策費、３８７ページの発達障害教育支援員配置、学校地域連携推進経費について伺います。いじめ防止対策について伺います。","respondent":"丸谷教育総合支援センター長","answer":"１月から区長部局に相談窓口が設置をされまして、１月からは、まずは開設をするということで、４月から本格運用が始まっております。４月から月１回のペースで定例会議を行い、第三者性ということで、求める保護者には非常に有効な窓口となっていると捉えています。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"しかし、最近体制が整ったとのことを伺っております。現在の相談体制と、その運用状況についてお教えいただけますか尋ねました。","respondent":"石井コンプライアンス推進担当課長","answer":"今年８月より、弁護士資格を持つ会計年度任用職員のコンプライアンス支援指導員を配置いたしました。いじめ相談員とともに連携してチームを組んで、被害児童・生徒の保護者の相談にも乗ってあります。","id":"exchange-019"},{"speaker":"山本委員","kind":"質問","question":"効果についてはいかがでしょうか。お教えください。","respondent":"丸谷教育総合支援センター長","answer":"令和５年度のいじめの重大事態は１４件でしたが、令和６年度は現在１件となっております。今後、後半から不登校が増えてくる傾向がありますので、効果についてはもう少し様子を見ていきたいと思います。","id":"exchange-020"},{"speaker":"山本委員","kind":"質問","question":"これらのソフトはどこの企業がやっているのでしょうか。どのような経緯でこれを導入に至ったのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"昨年度、未然防止の取組の強化を検討していたところ、ＮＨＫスペシャルで大阪府吹田市のいじめ予防プログラムは取り上げられておりました。同様の取組を本区にも取り入れたいと考え、プロポーザルを実施、事業者を決定いたしました。","id":"exchange-021"},{"speaker":"山本委員","kind":"質問・要望","question":"ＰＴＡや保護者の皆様からご要望をいただいておりますので、私からも迅速なご対応を要望し、次の質問に参ります。ご意見を伺います。","respondent":"中谷指導課長","answer":"実績につきましては、次回のコーディネーター連絡会で、各校の優良事例の共有を目的とした報告のお時間を設定して行う予定です。本成果を受け止めてくださり、ご自身の学校でできる形を再構築していただくなどして、広がっていくことを期待しております。","id":"exchange-022"},{"speaker":"山本委員","kind":"質問・要望","question":"これらは要望といたします。現在課題はありますでしょうか、お考えを説明を求めました。","respondent":"中谷指導課長","answer":"コーディネーターにつきましては、全校でそれぞれご尽力いただいております。将来的に、今やっていらっしゃる方の後継ぎとなる人材を輩出できるようにしていくことが課題です。","id":"exchange-023"},{"speaker":"山本委員","kind":"意見","question":"先日、９月２６日に開催された品川コミュニティ・スクール、学校支援ボランティア養成講座に参加をいたしました。講座内容、参加者人数、実施後の感想を説明を求めました。","respondent":"中谷指導課長","answer":"学校支援ボランティア養成講座についてですが、昨年度から企画、実施をしている講座になっております。９月２６日、対面による実施とオンラインによる実施をしておりまして、参加者人数は５７人となっております。","id":"exchange-024"},{"speaker":"山本委員","kind":"質問","question":"次に、発達障害教育支援員について伺います。人数を含め、前年の同様制度と比較して状況をお教えください。","respondent":"唐澤特別支援教育担当課長","answer":"令和６年度より小学校前期課程全校への配置となり、これまで配置してきた学習支援員を生活支援も行う発達障害教育支援員に転換したところです。介助員については、名称を学校生活支援員として、今年度も継続しているところです。","id":"exchange-025"},{"speaker":"山本委員","kind":"質問","question":"先日、ある小学校の学校公開に２日間伺いました。個々の学校の状況によるとは思いますが、学校の要求に応えるための支援体制の拡充が必要ではないかと考えますけれども、いかがか尋ねました。","respondent":"唐澤特別支援教育担当課長","answer":"配慮を要するお子さんへの対応など、各学校や教職員の特別支援教育の理解・啓発、支援員の研修の充実など。学校との連絡体制や研修体制を充実していく中で、支援員の質の向上にも努めてまいりたいと考えております。","id":"exchange-026"},{"speaker":"山本委員","kind":"質問","question":"次に、修学旅行費について伺います。地域の祭りに伺った際、ある区民の方から、つらい話、悲しい話を聞きました。","respondent":"柏木学務課長","answer":"区立学校の修学旅行ですが、９年生で実施し、令和６年度は全校とも２泊３日で奈良、京都に行っております。なお、参加率につきましては、教育委員会では把握はしてございません。","id":"exchange-027"},{"speaker":"山本委員","kind":"質問","question":"教材費の無償化は進めていただいておりますが、さらに前に進め、修学旅行費の無償化を進めるということはいかがでしょうか。お考えを説明を求めました。","respondent":"柏木学務課長","answer":"子育て家庭の負担を軽減して子育てしやすい環境を整備することは、今後も必要なことと考えています。本来は国が実施するものと考えておりますが、今後の予算編成作業等の中で、考え方を整理していきたいと考えています。","id":"exchange-028"},{"speaker":"山本委員","kind":"提案","question":"これまでもご質問していますが、地域の皆様や部活動の保護者の方々からご意見を伺う中で、幾つかご提案がありますので申し上げます。当会派の大倉議員からも先日の一般質問等でご要望がありましたが、出欠などの連絡が担当教師や関係者の負担になっていると聞いていますとの意見を述べました。","respondent":"中谷指導課長","answer":"指導者の確保につきましては、民間委託、部活動指導員、どちらの形態であったとしても、品川の地元に根差した方が子どもたちへの指導に関わっていただくことで、持続可能な活動が担保できると考えております。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"共産党としては、義務教育が無償であるべきというのであれば、やはり対象を私立学校に通う児童・生徒にも拡大するようと求めてまいりました。改めて伺いたいことは、給食無償化を区立や特別支援学校以外に通う小・中学生へも拡大するときではないかと思いますけれども、いかがか尋ねました。","respondent":"柏木学務課長","answer":"学校の設置者は、その設置する学校を管理し、法令に特別の定めのある場合を除いてはその学校の経費を負担すると定められてあります。学校設置者が検討するものと考えておりまして、品川区が設置者ではない学校については、現時点では拡大は考えてございません。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"紹介しましたけれども、朝鮮学校はもともと給食費には補助がなく、給食はほぼオモニ給食という名前で、自助、共助で提供している状況だと伺いました。せめて、この支援の必要性が高い朝鮮学校をはじめ、各種学校には急いで給食費無償化の対象を広げるべきではないでしょうか、伺いたいと思います。","respondent":"柏木学務課長","answer":"各種学校への給食費の拡大ですが、まず繰り返しになりますけれども、学校に係る経費については学校設置者が検討するものと考えています。決して朝鮮学校等を差別しているものではございません。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"先ほど言ったのですけれども、やっているではないですか、特別支援学校には。朝鮮学校に出さない理由を言うことは分かるのですけれども、全くもう質問に答えていないということで困ってしまうのですが、もう一度お願いします。","respondent":"柏木学務課長","answer":"そして特別支援学校につきましては、学校に補助をしているわけではございません。区の学校で就学が困難なことから特別支援学校に通っていると、そのようなお子さんの家庭に補助をしているというものになります。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ援助の支援の必要性が高いと思っていますので、できるところからでも始めていただきたいということで、重ねてお願いしたいと思います。令和２年度、令和３年度、令和４年度のいじめ重大事態の件数も説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"いじめの重大事態の認定の年度についてのお問合せです。令和４年度の扱いで３件ということで、認定時期としては令和４年ということで、令和４年に３件という形でホームページでも公表しています。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと伺いたいのですけれども、保護者の意向は最優先されるべきものですが、議会は議論を深めることができません。そうでないと品川区の教育はよくなりません、いじめを防ぐことはできませんと思うのですけれども、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"いじめの重大事態の調査が終了した６件について、非公表ということでは報告を差し上げているところです。ガイドラインに沿って可能な限り公表するということは我々も考えておりまして、保護者等にご了承いただければ公表する考えではあります。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと伺いますけれども、３,８９４万円、これもうやめるべきなのではないでしょうか。どうか尋ねました。","respondent":"中谷指導課長","answer":"教育委員会としましても、各学校につきましては、この調査を経年で把握するということも１つ大事なことだと考えています。１人の教員が、これをまさに授業改善に活かしていただくためにやっているというところになります。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういった現場のこともありますし、あと学校と子どもと教師を点数の獲得競争で輪切りにして競わせるという、このような重大問題もありますので、ぜひ中止してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"３８３ページ、３７２ページ、関連してＡＩシンギュラリティーと教育について質問をします。見られない状態になっているのですけれども、これは一体どのようなことなのか、ご説明ください。","respondent":"河内品川図書館長","answer":"図書館本文も、全体も含めまして、すぐに確認、対応いたします。貴重なご指摘ありがとうございました。","id":"exchange-037"},{"speaker":"筒井委員","kind":"質問・要望","question":"ということは、この品川人物伝というページはもう存在しないというということなのでしょうか。その辺り説明を求めました。","respondent":"河内品川図書館長","answer":"ちょっと所管が違う部署のホームページですが、現在は閉鎖してないというように認識しています。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ品川人物伝というページをこれからもう１回つくり直すのかどうかはさておき、関心、ブランディングに活用していただきたいと考えています。その他の地域資料と併せて、ぜひこの活用と展開を図書館のほうでも展開していっていただきたいのですけれども、その辺りのお考えを説明を求めました。","respondent":"河内品川図書館長","answer":"品川区立図書館ですが、やはり品川区、地域に関する資料など、非常に貴重な資料なども所蔵しています。来館など、こういったところから区民の皆様の知識、あるいは愛着を深めていくところを今後とも進めてまいりたいと考えているところです。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"今現在品川区の学校ではプログラミング学習をやっておられるかと思いますが、その成果と、また課題などありますでしょうか。その辺りお知らせください。","respondent":"丸谷教育総合支援センター長","answer":"６年生理科の電気の性質の単元をはじめ、市民科でもプログラミング教育を行っているところです。課題といたしましては、現在、始めたばかりですので、教員がどのように指導していいか分からない、そのようなところは課題として捉えております。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"土木費でも述べましたが、それもやはり、例えばマインクラフトの活用で防災体験などを学校の授業で取り入れていってはいかがでしょうか。これも１つ、今後重要になってくるかなと思っているのですけれども、その辺りいかがお考えか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"防災教育の１つとしてマインクラフト等を活用するといったことですけれども、現在様々な教材が出されているかと思います。子どもたちの実態に応じて、有効な教材を活用できればと考えております。","id":"exchange-041"},{"speaker":"筒井委員","kind":"質問・要望","question":"ですから、今までの１０年とこれからの１０年、かなり違ってくるかと思います。５年後などになってしまうのですけれども、現在中学１年生のお子さんがこれから社会に出ていくときどうなっていくのか、どのようにお考えなのか。","respondent":"中谷指導課長","answer":"特にＡＩなどの新しい技術ですけれども、想像力を働かせて考えたり、使う側のしっかりした自覚や責任感を持つことも大切となってくると思います。そのためには、自分で未来を切り拓いていくことができるように展開していきたいと思います。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"予測困難な時代ですけれども、教育もそれに合わせて、ぜひ取り組んでいってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"せらく委員","kind":"質問","question":"コミュニティ・スクール、学校全体として令和５年度は何回ほど授業をやられたかお聞きします。新しいテーマは、令和５年度に何テーマほど取り入れたか説明を求めました。","respondent":"中谷指導課長","answer":"学習支援、子どもたちが地域に出ていくようなところでの支援ということで、環境整備に関わるところでの活動もしていただいています。先ほど申し上げたとおり、こういった力を活用しながら、引き続きやってまいりたいと考えています。","id":"exchange-044"},{"speaker":"せらく委員","kind":"質問","question":"こちらは具体的な数字、何校で何回というところは教えていただけますでしょうか。それはいつ頃、何年前ぐらいに何年生で行われていたか、お分かりであれば説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"コロナ以前に複数の学校で実施したということは把握しているのですが、ただ、令和４年度に小学校１校で実施しているということが分かりました。学年についてですけれども、学校によって、これが６年生を対象に行ったという実績がございました。","id":"exchange-045"},{"speaker":"せらく委員","kind":"質問・要望","question":"ぜひ今後もまたそういった安全教育を行っていただきたいと思うのですけれども、地域のコーディネーターにも共有をしてほしいと求めました。品川区の子どもたちが安全にアクティビティーを楽しめる知識の普及をぜひお願いしたいと思うのですけれども、今後いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"今後の見通しについてですけれども、次年度以降、こうしたライフジャケットの体験を取り入れてみたいという学校も複数出てきておりまして、外部講師との連携ということで、学校地域コーディネーターの活躍も見込めるかなというように捉えております。","id":"exchange-046"},{"speaker":"せらく委員","kind":"質問","question":"そのうち、児童センターで過ごしている人数を把握していますでしょうか。もしいらっしゃいましたら、児童センターで過ごす不登校の子どもたちにはどのようなフォローやサポートをしているか伺います。","respondent":"丸谷教育総合支援センター長","answer":"今年度入ってからの実績になりますが、小・中学生合わせて８名、児童センターを利用しているということが分かっております。具体的な支援についてですけれども、学校と家庭と児童センターが連携をすることで、子どもの安全な居場所ということの確保に努めているところです。","id":"exchange-047"},{"speaker":"せらく委員","kind":"確認","question":"北区では、私立に通う子どもも含めて、不登校の児童・生徒を児童センターの一角で受入れを開設したということを確認いたしました。今年度の品川区の支援の拡大についてのご所感と、児童センターで支援を始めた北区の取組についてご見解を伺います。","respondent":"丸谷教育総合支援センター長","answer":"その結果、マイスクールの利用者が例年に比べると抑えられている現状があり、支援につながっているものと考えているところです。児童センターということでまた所管が変わってしまうのですけれども、こうした取組も不登校支援の１つだというように捉えております。","id":"exchange-048"},{"speaker":"せらく委員","kind":"確認","question":"教員の働き方改革に品川区は取り組んでいると思うのですけれども、こちらは勤務時間外の電話委託をしているというように確認しました。勤務時間外の電話対応はどのくらいありましたか尋ねました。","respondent":"中谷指導課長","answer":"代理で会話をさせていただきまして、その後、そのいただいたお話の要件を教職員のほうにフィードバックするというものになっております。回数に関しては、かなり、各学校によっても違うところあるかと思いますが、基本的には毎日使われているというところになります。","id":"exchange-049"},{"speaker":"せらく委員","kind":"提案","question":"毎日使われているということでした。ちょっとこの後テレワークの取組状況をお聞きしたいなと思ったのですけれども、まだ具体的な提案も私もないところですので、終わりたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"横山委員","kind":"質問・要望","question":"品川区においても、これらの課題を早急に対応していただきたいと要望いたしますが、区教育委員会の検討状況をお伺いいたします。小・中学校における現状と課題を確認させてください。","respondent":"丸谷教育総合支援センター長","answer":"学校支援チームＨＥＡＲＴＳの中で勤務をしており、人材の拡充、ＳＳＷの資質向上のための研修の実施等に努めております。品川区児童相談所が開設されましたので、今後一層連携を緊密にして、課題の洗い出しや課題解決に向けた協議を進めてまいります。","id":"exchange-051"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目なのですけれども、いじめ防止対策費についてお伺いいたします。情報モラル教育の強化へとつなげていただきたいのですが、いじめの根本解決について区教育委員会側のご見解を説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"１３歳、中学生年齢になりますと９割を超えてくるといった状況でございまして、本区においても同様の傾向があるというように認識しております。各学校では、ＧＩＧＡワークブックとうきょうを活用したり、外部講師を呼んだセーフティ教室を実施して…","id":"exchange-052"},{"speaker":"横山委員","kind":"質問・要望","question":"３点目にクラブ・部活動等経費、特別支援教育費についてお伺いいたします。外部指導員の方々にも、本音が伝えられないなどの子どもたちを受け止めていただきたいと思っていますが、区教育委員会のお考えを説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"例年年度当初に部活動指導者研修を実施し、児童・生徒への励まし、承認等の必要性などについても学んでおります。民間委託事業者も含めて、こうした研修を行っているところです。","id":"exchange-053"},{"speaker":"横山委員","kind":"質問・要望","question":"時間がなくなってしまいましたが、子どもたちに関わる様々な方々に対して、先生方と同じ研修を受講していただくことは難しいかと思うのですけれども、職務内容に合わせて研修をさらに充実させていただきたいと要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"西村委員","kind":"質問","question":"令和５年度の不登校児童・生徒数は、先ほどせらく委員の質問で伺いました。お伺いいたします。","respondent":"丸谷教育総合支援センター長","answer":"マイスクールやフリースクール等の外部機関につながっていない児童・生徒数、昨年度ですけれども、小学生で８５人、中学生で１３０人おりました。","id":"exchange-055"},{"speaker":"西村委員","kind":"質問","question":"中学生で約３割、小学生で約４.４割がつながっていないことになります。そこで、今年度から始まったものでありますが、都の進めるメタバースの現状と参加人数、他区の導入状況を伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"メタバース空間を活用した支援事業ですけれども、９月末現在で５０名の登録があります。今年度、品川区も含めて２８自治体で導入しているというように把握しています。","id":"exchange-056"},{"speaker":"西村委員","kind":"質問","question":"私は度々このテーマを取り上げさせていただいているのですが、家にとどまる子にも居場所をというものが私の本当に強い思いであります。このメタバースの中で、どのような授業が繰り広げられているのか伺います。","respondent":"丸谷教育総合支援センター長","answer":"こちらは３Ｄ空間を用いまして、そこで児童・生徒同士の交流や、支援員との交流ができるような仕組みになってあります。オンラインスクールを実施しておりまして、週に３日程度、そうした学習活動も行っているところです。","id":"exchange-057"},{"speaker":"西村委員","kind":"質問","question":"１点伺いたいのですが、中に入れば、そういったオンラインスクールや品川区独自の取組がある程度できるという認識でよろしいのでしょうか。センター長がご覧になって、参加者が増えない理由やメタバースの実感があれば説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"バーチャル空間にログインするところに１つハードルがあるのではないかというような認識でおります。新たな取組も今計画しており、ログインが何とかできるような仕組みをつくっていきたいと考えております。","id":"exchange-058"},{"speaker":"西村委員","kind":"質問・要望","question":"この戸田市が２年前から始めるオンライン学習は、グループワークを中心に子どもたちが元気よく発表する声が行き交っていると伺っておりました。そこで１点要望させていただきたいのですが、このオンラインの中で教育相談ができないかなと考えています。","respondent":"丸谷教育総合支援センター長","answer":"不登校児童・生徒がオンライン上で相談できるような、このバーチャル空間で相談できるような仕組みということで、マイスクールにいる心理士やＨＥＡＲＴＳの心理士等もログインすることが可能ですので、支援の充実につなげていきたいと考えております。","id":"exchange-059"},{"speaker":"西村委員","kind":"質問・要望","question":"要望ばかりで申し訳ありませんが、もう１点、アクションプランを策定している大田区の学びの多様化学校、不登校特例校に視察に伺いました。この不登校生徒・児童への取組に際しまして、行動計画、また不登校対策アクションプランを今後策定する予定はあるかを伺います。","respondent":"丸谷教育総合支援センター長","answer":"現在、品川区の教育振興基本計画を策定しています。そうした基本計画に基づきまして、不登校支援の計画についても進めていきたいと考えております。","id":"exchange-060"},{"speaker":"西村委員","kind":"質問・要望","question":"ぜひこの不登校支援の強化は必須であると思いますので、早期にお願いをしたいと思います。品川区子ども読書活動推進計画の進捗と主な取組、その中で目玉といいますか、新たな特色があればお聞かせをほしいと求めました。","respondent":"河内品川図書館長","answer":"第２法則は「いずれの読者にもすべて、第３法則では「いずれの図書にもすべて、その読者を」というものがあります。こういったものを受けまして、誰にでも、誰でもという点が、特に重要と、特色と考えているところです。","id":"exchange-061"},{"speaker":"西村委員","kind":"意見","question":"例えば児童センターにティーンズ館があるように、図書館のティーンズ館やティーンズコーナーの強化をお願いしたいと思います。１日勉学に励む生徒が軽食を取れるようなスペースなどもいいなと考えていますが、区のお考えを説明を求めました。","respondent":"河内品川図書館長","answer":"利用者は静かにという認識の下、主に成人以上の方につきましては、その度合いが少しハードルが高いというように認識しています。やはり学生、２人以上の方でご利用の方も多く、やはりそういった静寂度の認識のレベル差も感じているところです。","id":"exchange-062"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、３７７ページ、プール指導員経費、３８１ページ、学級風土調査、この２点からお伺いしたいと思います。行政から教員と校長先生に弁償を求めるというような、管理の在り方を見直して、負担軽減策を検討するようにしているということをお聞きしております。","respondent":"柏木学務課長、中谷指導課長","answer":"委員からご紹介がありましたとおり、今年の７月に「学校における働き方改革に配慮した学校プールの管理の在り方」ということが通知されております。教育委員会といたしましても、学校のプールの管理については課題と捉えておりますので… 上司が若手教員にケア的な視点を持って声をかけていくというようなことが必要となる時代かなと考えています。メンター制度というものもありまして、新規採用教員に対して、先輩のアドバイスができる環境というものも整えております。","id":"exchange-063"},{"speaker":"こんの委員","kind":"質問・要望","question":"こうしたことも求められていると思いますが、その辺についてはどのようにお考えなのか、いま一度お聞きしたいと思います。折り合いをつけていくといったところはどのようにされているのか、その辺をお伺いしたいと思います。","respondent":"柏木学務課長、中谷指導課長","answer":"民間委託の考え方や自動で水を止めるなどという、どちらにするとか、ほかの方法にするかはまだ決まっていないところです。自動に水を止める装置につきましては、まだ全校ではございませんが、順次各校に導入をしています。 校長先生から示された学校経営方針に基づいて、こういったことを積極的に考え、そして校長先生に直接言える場となっています。自分自身がやりたい経営方針と合っているかどうか、または…","id":"exchange-064"},{"speaker":"おぎの委員","kind":"質問","question":"本日は、３８７ページ、教科書採択事務についてお伺いいたします。どこかに公開されて私たちも見ることができるのか、併せて説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"展示会場表示が１階にしかなく、２階入り口の右のものは小さく目立たないといった、そのようなご意見がございました。いただいたアンケートの公表についてですけれども、公表を目的にアンケートを取っておりませんので、公表はしていないところです。","id":"exchange-065"},{"speaker":"おぎの委員","kind":"意見","question":"内容については公開を目的にしていないということで、こちらのほうは了承いたしました。教育委員会での採択が行われたと思いますが、今年の調査検討委員会と採択に関する教育委員会の開催期間と会議の回数をそれぞれお答えくださいとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"教科用図書の調査検討委員会の日程です。調査検討委員会は、第１回が５月３０日に開催されまして、全部で６回、７月２２日の第６回までございました。","id":"exchange-066"},{"speaker":"おぎの委員","kind":"意見","question":"回数を重ねてしっかりと審議されたことだと思います。先ほどのアンケートによる区民からの意見を取り入れることができないなと思いますが、区民からの意見はどの程度反映されているのか説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"教科書展示の、まず目的ですが、保護者等、広く都民に教科書を公開することでございまして、採択に直接活かす目的とはなっておりません。採択権者の判断と責任について文部科学省からも通知があり、教育委員が責任を持って採択事務を行っているところです。","id":"exchange-067"},{"speaker":"おぎの委員","kind":"質問","question":"令和７年度使用教科書図書展示におけるアンケートとして、展示されている教科用図書についてご意見があればお書きくださいとなっておりました。設置する意味がないと思いますけれども、このアンケートの発行については、どう思いますか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"いただいた意見につきましては、採択事務が終わりました９月に入ってから、教育委員会会議の中で意見の共有をしています。アンケートの趣旨、目的につきまして、区民の方に分かりやすいような表示に次回以降気をつけていきたいと考えております。","id":"exchange-068"},{"speaker":"おぎの委員","kind":"確認","question":"続いて、今回質問が多かったという中学校の歴史教科書についてお聞きします。各ページの下の欄外に問いが掲載されており、生徒が今何を学習しているのかを確認できる、学ぶ内容ではないのだなといった印象を受けます。","respondent":"丸谷教育総合支援センター長","answer":"教科書の採択理由につきまして、ホームページに公表しているとおりです。委員にご紹介いただいた３点記載していますけれども、そういった内容の審議というものもしっかりとされて、採択を行っているものです。","id":"exchange-069"},{"speaker":"おぎの委員","kind":"質問","question":"これは毎回変わるのでしょうか。調査項目自体も時代背景に合わせて変えていくべきではと思いますが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"学習指導要領が変わるときにこうした基準についても見直して、変更しているものです。紙幣に載っている３人についてですけれども、それ以外のことで判断して採択しています。","id":"exchange-070"},{"speaker":"ひがし委員","kind":"質問・要望","question":"教職員の病気で休職される方の数、令和元年１８人から令和５年では３６人と、年々増加していると議事録で確認をさせていただきました。メンタルサポートの充実の観点から、同会派吉田ゆみこ議員の一般質問では、相談窓口の拡充、また周知強化の要望がありました。","respondent":"中谷指導課長","answer":"副校長補佐については、全校の配置の予算をつけておりまして、現在１校を除いて４５校に配置になっています。エデュケーションアシスタントについては、副担任相当で小学校の低学年や３年生についていただく役割ですが、試行実施として２校配置をしております。","id":"exchange-071"},{"speaker":"ひがし委員","kind":"質問・要望","question":"この点についていかがでしょうかということが１点です。エデュケーションアシスタント、２校から開始をしてくださっているということで、現場の方に意見をお伺いしました。","respondent":"中谷指導課長","answer":"これは１年生から３年生まで配置できるものですが、できれば各学年につくことができるとかなり学校が変わっていくのかなとも思っております。そのようなことも検討していきたいと考えています。","id":"exchange-072"},{"speaker":"ひがし委員","kind":"質問・要望","question":"まさに要望したいような内容だったのですけれども、東京都の予算の活用では、今ご説明いただきましたように。その２学年分だったり、こちらについては重ねての要望とさせていただきまして、次の質問へと移行します。","respondent":"河内品川図書館長","answer":"５年生が１０.０％、８年生が３１.２％です。ちなみに不読率ですが、定義といたしましては、調査直近１か月の間に全く本を読んでいない割合です。","id":"exchange-073"},{"speaker":"ひがし委員","kind":"確認","question":"このティーンズ世代への取組というところがすごく重要になってくるのだなと、先ほど西村委員の質疑の中からも確認をさせていただきました。この静かにするものが図書館だという考えも、少し改めて考え直す必要があるのかなと思いますが、その点についていかがか尋ねました。","respondent":"河内品川図書館長","answer":"現在の１１館のつくり込みですが、やはり従来のつくり込みの中で、静かに選書、あるいは読書を行うというようなところで推移してまいりました。こういった意識があまりにも定着し過ぎた結果というように認識はしておりますが、それから構造…","id":"exchange-074"},{"speaker":"ひがし委員","kind":"意見","question":"デジタルが日常の中に非常に現在浸透しております。図書という時間について、さらに拡大できるようにお願いしたいと思いますが、そのデジタルの点についてもお考えを説明を求めました。","respondent":"河内品川図書館長","answer":"障害をお持ちの方への対応力はデジタルが有用というところがありますが、一方で、デジタルの進展がますます加速している状況です。組み合わせていきながら、デジタルとの親和性を図り、読書推進に図ってまいりたいと考えているところです。","id":"exchange-075"},{"speaker":"ひがし委員","kind":"質問・要望","question":"様々課題もあると思うので、適宜策定委員会等も資料を毎回拝見していますが、その中でもぜひ検討を進めていただきたいと要望します。こちらについては、学びの多様化学校の設置について、まず区としてどのようなお考えがあるのかというところを率直に１点説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"学びの多様化学校、いわゆる不登校特例校ですけれども、令和６年度は全国で３５校、うち東京都には私立も含めて１０校あるというような認識です。本区においてはまだ設置はありませんけれども、国の動向や他区の状況を踏まえながら、検討というか…","id":"exchange-076"},{"speaker":"ひがし委員","kind":"質問・要望","question":"こちらは要望とします。今力を入れてくださっていると思いますけれども、こちらについて要望とさせていただきまして、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"中塚委員","kind":"提案","question":"中学３年生の修学旅行、小学５年生の林間学校、改めて無償化を求めたいと思います。教育委員会事務局が教育委員会定例会に予算案を提案する際に、この修学旅行などの無償化を提案する予定だということでよいのか伺いたいと思いますとの意見を述べました。","respondent":"柏木学務課長","answer":"予算案に修学旅行の無償化を盛り込むかですけれども、修学旅行に限らず、今様々なものを検討していますので、予算編成の中でそこを整理していきたいと考えているところです。","id":"exchange-078"},{"speaker":"中塚委員","kind":"提案","question":"９月１１日、修学旅行への無償化の質問があり、義務教育は無償化との観点から検討していきたいと説明がありました。修学旅行などの無償化が実現するという段階なのか、改めて教育委員会定例会にその提案をする考えなのか、方向性をしっかり示してくださいとの意見を述べました。","respondent":"柏木学務課長","answer":"現時点で、すぐ修学旅行の予算を出すかどうかということは、現時点では決まっていないです。あくまでも、その考え方を今後整理するです。","id":"exchange-079"},{"speaker":"中塚委員","kind":"質問・要望","question":"卒業遠足、鎌倉遠足、無償化を強く要望しておきたいと思います。教育の独立性に関わって伺いますが、これは教育委員会の各教育委員や各校長先生は了解していることなのか、誰が了解しているのか伺いたいと思います。","respondent":"舩木庶務課長","answer":"今のご質問の件ですが、誰が承認したかということではございません。こういった繰り返し、それぞれの情報を正しく知識を得るための補完的なものの刊行物として、各校の各校長にも取り扱われているものと捉えております。","id":"exchange-080"},{"speaker":"中塚委員","kind":"質問","question":"つまり、教育委員や各校長先生は了解はしていないということでよいのか、もう１回伺いたいと思います。こうした解放新聞の一方的な送付、送りつけは、教育への不当な介入に当たるのではないかと思いますが、その点どのようにお考えか尋ねました。","respondent":"舩木庶務課長","answer":"こういった職員として正しく身につけておかなければならない知識ということで、このような取扱いがされているです。特に学校教育の中身に何かこういった、区長部局のほうというご指摘ですけれども、そのような部分での取扱いとして捉えております。","id":"exchange-081"},{"speaker":"中塚委員","kind":"質問","question":"今いみじくも課長が、教育に取り入れているわけではないとおっしゃいました。一方的に区が送りつけている、受け取ったほうも教育に取り入れているわけではない、これはただ無駄遣いではないか尋ねました。","respondent":"舩木庶務課長","answer":"繰り返しになりますけれども、身につけておかなければならない知識と。このような対応を取っているというように認識しておりますので、過去の事例のみならず、そのように取り扱われているものとして認識しております。","id":"exchange-082"},{"speaker":"中塚委員","kind":"質問","question":"ですから、先ほど課長が、学校教育に取り入れているわけではないとお話がありました。では、どこに必要性があるのか尋ねました。","respondent":"舩木庶務課長","answer":"区の職員であれば、正しい知識、正しい理解を身につけておかなければならないということかと思います。繰り返しになりますけれども、理解を継続して、しっかりと意識を持っていくというためのものとして取り扱われていると認識しております。","id":"exchange-083"},{"speaker":"中塚委員","kind":"質問・要望","question":"配付を教育委員会事務局が実態として了解しているというのであれば、それはそれで大問題だと思いますし、直ちに配付は断るべきだと私は思います。直ちにやめるよう求めたいと思いますし、教育委員会に対しては配付を断るべきだと思いますけれども、最後にいかがか尋ねました。","respondent":"舩木庶務課長","answer":"このことが委員ご指摘のことには当たらないとは考えておりますが、取扱いにつきましては、必要に応じて関係所管課とも確認を取りながら、引き続き適切に対応してまいりたいと考えます。","id":"exchange-084"},{"speaker":"こしば委員","kind":"質問","question":"私からは、３８３ページ特色ある教育活動に関連をしまして、偉人教育についてお伺いをいたします。生きる上でのたくさんの気づきがあったと思いますが、この学校教育から偉人教育がなくなってしまった理由について教えてほしいと求めました。","respondent":"中谷指導課長","answer":"その方の生き方など、子どもたちの豊かな心を育てる活動になることを配慮して、取り扱わしています。","id":"exchange-085"},{"speaker":"こしば委員","kind":"質問・要望","question":"この二宮金次郎像、学校ではどのように捉えておられるのでしょうか。子どもたちにこの二宮金次郎像をどのように教えておられるのか、説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"６、７年生の教科書に偉人や先人から学ぶ偉人伝という単元がございまして、その中で二宮金次郎についても取上げがあります。こうした市民科の授業の中で、二宮金次郎についての先人の生き方というか、そういうところで学ぶということで取上げがあろうかと考えています。","id":"exchange-086"},{"speaker":"こしば委員","kind":"質問","question":"５年生から７年生にかけて、この二宮金次郎像を様々な場面で教えておられるということ認識いたしました。伊藤博文公も歴史上の偉人の一人に数えられると思いますが、学校教育の中でこの伊藤博文公をどのように捉え、子どもたちに教えていますか尋ねました。","respondent":"中谷指導課長","answer":"今お話のありました伊藤博文、板垣退助のお墓を拝見するための訪問ということで、小学校３年生の社会科見学の取組として今年度行っております。浜川中学校では、坂本龍馬にゆかりのある高知県の学習に関連して、高知野菜についての食育の授業などを行っているところです。","id":"exchange-087"},{"speaker":"こしば委員","kind":"質問・要望","question":"偉人ですから、必ずしもこの品川区と縁のない偉人もたくさんいらっしゃいます。子どもたちに偉人教育を通じて人の生き方、また人生の志を考える機会をぜひお与えいただきたいと考えておりますが、見解をお伺いいたします。","respondent":"中谷指導課長","answer":"お話しいただいたことに関連して、東京都のほうで道徳教育教材集というものがありまして、その中に偉人の格言などを掲載しているところがあります。津田梅子など、それぞれの現段階で載っているもので総計しましても、１０人の偉人が紹介されているものを活用しています。","id":"exchange-088"},{"speaker":"こしば委員","kind":"質問・要望","question":"そういったものも含めて、恐らく大多数がその市民科の中で扱われることが多いと思いますが、偉人は当然歴史、社会の分野ですので、またその辺りもぜひ幅広く展開をしていただきたいとお願いをしまして、終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"提案","question":"私自身も前回の予算特別委員会において、修学旅行費の無償化を提案させていただいておりました。その点を踏まえて質問なのですけれども、修学旅行の保護者の負担というのは、現在どのように推移していますか尋ねました。","respondent":"柏木学務課長","answer":"修学旅行費の保護者の負担ですが、経年をちょっと追っているわけではないのですが、令和４年度と令和５年度で比較すると５,０００円ほど上がってあります。","id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"これは要望になります。その修学旅行費に関連してお伺いしたいのですけれども、これは何名まで公費負担が出るのか、お教えください。","respondent":"中谷指導課長","answer":"修学旅行の教職員の下見ですけれども、旅行者は原則として１人としています。状況によっては１人ではなく、複数で行くように校長が判断する場合もあります。","id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"できればやはり複数名で行かれたほうがいいと思いますし、その場合、全額公費で出してほしいと求めました。その点はいかがか尋ねました。","respondent":"中谷指導課長","answer":"先ほど申し上げたとおり、原則１人というところですけれども、場合によっては複数で行くこともあります。東京都の条例のほうに従って進めているものになるのですが、出ていく宿泊費の支払い費用は１万１,０００円となっております。","id":"exchange-092"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"今、管理職というところでお話があったので、校長先生に関してお伺いします。校長の修学旅行の下見というのは、公費負担の線引きというのはどのようになっていますか尋ねました。","respondent":"中谷指導課長","answer":"先ほどの答弁の、教員に対して出す１万１,０００円というのは１夜というところでご認識いただければと思っています。ただ、今申し上げたのは行き先が決まっておりまして、例えばよく修学旅行の行き先で選ばれる京都市を１例に挙げたものになっております。","id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"確認","question":"では下見に実際校長先生が行ってみて、子どもにとって学習に非常にいいかどうか判断しようと思ったときに、ちょっとそこを今確認させてください。いかがか尋ねました。","respondent":"中谷指導課長","answer":"ただ、指定先がまだ決まっていなくて検討している段階においては、原則お支払いをすることができないということになっています。宿泊場所内の動線を確認したりして、予定するスケジュールで遂行できるかというシミュレーションを行う作業になっておりますので。","id":"exchange-094"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"非常に人気があるとお伺いしておりまして、目標は全校に１人配置ということで、優秀な人材を確保するということが必要かと考えています。１つ気になったのが、こういった区の特色をぜひ前面に押し出していただきたいと思うのですが、その点いかがか尋ねました。","respondent":"中谷指導課長","answer":"お話しいただいたとおり、例えば動画として実際に職員室などを映しながら、どういった方が働いていらっしゃるのか。独自の教育を進めているということが伝わるのかなと思いますので、そういった動画の作成も検討してみたいと思います。","id":"exchange-095"},{"speaker":"やなぎさわ委員","kind":"意見","question":"スクール・サポート・スタッフは、前年度で５０円時給が上がったのですけれども、実は上がっていないのですよね。今、賃金が逆転してしまっているので、ぜひその辺の改善をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-096"},{"speaker":"塚本委員","kind":"質問","question":"それから３９５ページ空調改修工事費ということで伺っていきたいと思います。元の空調がしっかり効くような形になると伺ったのですけれども、これについて区としてどういった対応をされているのか、お伺いしたいと思います。","respondent":"荒木学校施設担当課長","answer":"これに加えまして、専門の委託業者に保守点検も委託をしておりまして、日常的な維持点検も実施をしております。この維持点検の中で急な不具合等が発生すれば、区のほうでしっかりと工事を発注して、即座に対応するという対応を取っているところです。","id":"exchange-097"},{"speaker":"塚本委員","kind":"質問","question":"３８１ページの教員支援経費なのですけれども、今年度からですか、副校長補佐というものが配置をされました。この副校長補佐が配置をされたことによる学校側の評価というのはどういったものかということを、お聞きしたいと思います。","respondent":"中谷指導課長","answer":"今年から、副校長の精神的な負担が減りましたという回答をいただいておりまして、これが任用している学校の９５％からそのようにいただいております。増えましたと９割が回答してくださっているということがありますので、こういった事業で、非常に実感しています。","id":"exchange-098"},{"speaker":"塚本委員","kind":"質問","question":"そのような形での仕切りがされているかと思うのですが、実際今、そういった意味でのその副校長補佐の役割というものについてどう考えるか。もう少しできるのであればお願いしてもいい部分というのはあったりするのではないかというようにも思うのですが、いかがか尋ねました。","respondent":"中谷指導課長","answer":"東京都教育委員会からのものを提出するための下準備として基礎資料を作ったりという、そういった内容が多いと思います。ですので、補佐の方が一部でもやってくれるというところの安心感だと思いますので、こういったことを続けていきたいと思っています。","id":"exchange-099"},{"speaker":"塚本委員","kind":"質問","question":"品川区は今年度、既に理科の教員が１人区内の中学校から転任されて、小学校のほうで教科担任制をされていると。このことについての区の評価、今その教科担任の方をどういった評価をされているか、お伺いいたします。","respondent":"中谷指導課長","answer":"今ちょうど半年たったところですけれども、子どもたちの理科の学びの質的な高まりがもう既に出ているということは申し上げたいと思います。やはりその働き方改革という意味では、ここに関しては現時点では検証中というところになっております。","id":"exchange-100"},{"speaker":"塚本委員","kind":"質問","question":"それで、既に来年に向けて１０月１日から、今度は保健体育の体育科で１名ということで、今、品川区が公募をされていると。１つお伺いしたいのは、１名という人数は、そういった知見も生かして今後の教科担任制に向けての区の見解を伺いたいと思います。","respondent":"中谷指導課長","answer":"その内容を生かす形で東京都教育委員会と連携しながら、加配をさらに拡大することを前提に検討していきたいと考えています。この東京都の事業が始まる前から、６つの義務教育学校では教科担任制ということをいち早く取り入れながら進めてきた経緯があります。","id":"exchange-101"},{"speaker":"塚本委員","kind":"質問・要望","question":"ＧＩＧＡスクール第２期ということで、この端末の更新ということが議論というか進められるということになっております。どういう状況なのかというのを聞きたいのと、今後どのようなスケジュールでなされていくのか、現状をお聞きしたいと思います。","respondent":"柏木学務課長","answer":"なので、そちらの価格を含めて検討しています。令和８年３月で切れますので、その４月から新しく使えるような形で、来年度から順次進めていきたいと考えています。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３７２ページから始まる教育費に関わって、義務教育の無償化を求めて伺います。品川区はこの教育の発展で利益を得るのは誰だと思っているのか伺います。","respondent":"柏木学務課長","answer":"誰の利益になるかということですけれども、最終的には子どもたちの利益になってくるものと考えています。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問","question":"最終的には子どもたちということですけれども、そこの個人の問題だけでなくて、やはりそうしたことが社会を発展させていくという認識はお持ちなのかどうか伺います。","respondent":"柏木学務課長","answer":"無償化するにあたって、子育て世代の負担を軽減して、子育てしやすい環境を整備するということを掲げて実施していますので、当然社会に対してもそういうことが還元されるものと考えています。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした中で、一義的にはやはり国が実施をしていくべきものだと思います。この間、義務教育の無償化への財源を国や都に求めるべきだと思いますけれども、この間求めてきたのかどうか伺いたいと思います。","respondent":"柏木学務課長","answer":"特別区の教育長会、または区長会等から、そういう財源については要望を出しています。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問・要望","question":"義務教育学校、小・中一貫校の標準服は、必ず着用しなければならないものなのかどうか伺います。実際の着用率が分かれば伺います。","respondent":"柏木学務課長","answer":"体操着等の無償化ですが、今後の保護者の負担軽減・無償化につきましては、予算編成作業の中で考え方については整理をしていきたいと考えています。着用率ですが、義務教育学校では、八潮学園を除いては、おおむね着用していると聞いております。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問","question":"無償化に向けては予算編成の中でということですけれども、こうした制服についても検討の中に入っているのかどうか、伺いたいと思います。そうした中で、小学校についてはこの標準服をやめるべきではないかということも思うのですけれども、いかがか尋ねました。","respondent":"柏木学務課長","answer":"初めに標準服の無償化についても検討に入っているかですが、一つの選択肢としては入ってあります。学校、あと保護者、地域のほうで検討して標準服の導入を決めているものです。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり教育課程の中で行われている修学旅行、その教育的意義は何か、伺いたいと思います。そして、無償化に踏み出してほしいと求めましたが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長、柏木学務課長","answer":"修学旅行の意義ですけれども、本区でありますと関西方面が多くありますけれども、日本にあります歴史や文化に触れながら日本の歴史に触れるというところで、大きな意義があると考えております。 修学旅行の無償化につきましては、今後、予算編成の作業の中で整理をしていきたいと考えています。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問・要望","question":"教育的意義もあるということですので、この修学旅行、ほかにも制服も含めて本当に義務教育の完全無償化で、経済力に関係なくやはり教育を保障する。そして子どもたちの人格発展にも寄与するように、義務教育の無償化を実施していただきたいと求めておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-109"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、３７５ページＰＴＡ関係費、３９３ページ学校ＩＣＴ活用経費、３９９ページ学校給食費無償化について、お伺いします。どのようなお声をいただいているのか、説明を求めました。","respondent":"柏木学務課長","answer":"教育委員会としてはその軽減されたお金については、別の形でお子さんに還元していただければと考えています。それと、区民の方からの声なのですけれども、無償化になってありがとうありますという声はいただいてあります。","id":"exchange-110"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"けれども国が動かないから、私も区にお願いするしかないので、ぜひその実現に向けて取り組んでいただければと要望して、この件は終わりにします。このような中で、品川区では今このＰＴＡについてどのような課題があると認識をされているのか、お知らせください。","respondent":"舩木庶務課長","answer":"今、委員のご指摘のとおり、様々な時代の移り変わりとともに、ＰＴＡの活動のあり方も変わってきているということは認識しております。丁寧に協議をした上で、あとは学校とＰＴＡのそれぞれの信頼関係…","id":"exchange-111"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"こういったものについても改善を求めるというような陳情だったと思いますが、そしてＰＴＡ、それぞれができることというのはあると思いますけれども。それがいいかどうかは別ですけれども、皆さんが楽しく活動のできるような組織にぜひしてほしいと求めました。","respondent":"舩木庶務課長","answer":"貴重なご意見ありがとうあります。例えば参画のあり方も、そのあたりについてはどういったあり方が好ましいかというところは、いろいろ検討してまいりたいと考えております。","id":"exchange-112"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"前回の一般質問でも生成ＡＩの活用などを区に求めましたが、教育委員会にもぜひお願いをしたいと思います。今までは自分の跳び箱を跳ぶ姿というのはどうしても見ることができなかったのだけれども、それを見て、私はタブレット端末の導入を求めました。","respondent":"丸谷教育総合支援センター長","answer":"子どもたちが楽しく体を動かす、スポーツに親しむということは大変意味のあることだと、大切なことだと考えております。生成ＡＩの力も借りながら、そういった教育に生かせるようなものを取り入れられればと思います。","id":"exchange-113"},{"speaker":"高橋（伸）委員","kind":"質問","question":"３７７ページプール指導員経費、それと時間があれば、３９１ページ地区図書館運営費についてお尋ねをさせてもらいます。最初に３７７ページ、プール指導員経費についてお伺いします。","respondent":"丸谷教育総合支援センター長","answer":"当然雨天ですとか暑さで中止・延期せざるを得ないということはありましたけれども、おおむね８割の学校は計画どおり進めることができたと。残りの２割につきましても、２時間続きの授業が１回程度中止せざるを得なかったという程度で…","id":"exchange-114"},{"speaker":"高橋（伸）委員","kind":"質問","question":"このプールの授業は、先生方も本当に大変なご苦労もあったかと思います。それで改めてお聞きしますけれども、このプールの授業の意義について、ご説明をお願いいたします。","respondent":"丸谷教育総合支援センター長","answer":"楽しさや喜びを味わい、その行い方を理解するとともに、その技能を身につけるということが目的とされております。行い方、泳法を身につけるということで、そういった目的が示されているところです。","id":"exchange-115"},{"speaker":"高橋（伸）委員","kind":"意見","question":"特に学校屋外のプール授業においては、熱中症が本当に今年に限らず、昨年も熱中症のリスクがむしろ陸上より高まるという指摘があると思われます。それで、現在区ではプール授業において何に注意をし、何を準備しながら実施を行っているのかをご説明願いますとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"水泳授業の実施にあたっては、まず気温や水温など、こうしたものをしっかりと見ております。おおむね足して５０度を下回ったときは、例えば暑さ指数が３１を超えると、その日の暑さ指数をしっかり測って実施を行っているところです。","id":"exchange-116"},{"speaker":"高橋（伸）委員","kind":"質問","question":"屋外だけではなく、屋内でもその整備が進んでいるとお聞きしております。現在、品川区のプール授業を安全に進めるための今後の方針をお示しください。","respondent":"丸谷教育総合支援センター長","answer":"例えばタオルを持ち込むであるとか、水筒を持ち込むとか、そういったことは既に学校のほうでは取り組んでいるところです。そういったものをしっかりと学校には注意喚起しながら、安全な水泳指導に努めてまいりたいと考えております。","id":"exchange-117"},{"speaker":"高橋（伸）委員","kind":"質問","question":"関連してお聞きします。歳入のところでいろいろ質問もありましたけれども、改築が進んでいる学校のプールにおいてはどのように考えておられるのか、ご説明願います。","respondent":"荒木学校施設担当課長","answer":"改築工事中の学校のプールの熱中症対策に関する取組について、ご説明いたします。来年度以降、何か対策が取れないかというところを試験的に検討してまいりたいと考えています。","id":"exchange-118"},{"speaker":"高橋（伸）委員","kind":"質問","question":"本当に安全で楽しく水泳で身体能力を磨いて、特に着衣泳とかそういうものもやっていると思うのです。水の事故を未然に防ぐためにもプール授業は大変有意義な授業だと思いますので、発展を希望して、私の質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-119"},{"speaker":"田中委員","kind":"質問・要望","question":"私はぜひ教育にも利用していただきたいという思いで、少し質問をします。この９か所が選ばれた理由をお聞かせほしいと求めました。","respondent":"舩木庶務課長","answer":"これは貴重な歴史的文化財をしっかりと守っていく、継承していくです。ただ、しかしながらこういった文化の日の３連休のところには一般に公開をし、歴史を感じていただくといったところの試みです。","id":"exchange-120"},{"speaker":"田中委員","kind":"質問・要望","question":"３、４日ということなので、土・日・月で祭日であります。今回のこの３日間の中で、学校への招待・紹介というのはあるのか尋ねました。","respondent":"舩木庶務課長","answer":"特に学校への直接の招待ということは、広く周知はしていますが、個別に特定の学校をお招きするということはございません。いろいろな史跡巡りとか、こういった貴重な機会もどのように区民の方に感じ取っていただくかということについては検討してまいりたいと考えます。","id":"exchange-121"},{"speaker":"田中委員","kind":"質問・要望","question":"どういう方が対象だったのかということは改めてそこは学んだ上で別の機会でお伺いをしていきたいと思いますが、既に先ほどのお話のように。既に設置をしている先輩として、ぜひ交流をしてほしいと求めましたが、ご見解をお聞かせほしいと求めました。","respondent":"中谷指導課長","answer":"その中で、現在正会員に入られている自治体があるのですけれども、今、光市は入られていないということを確認しています。教育委員会職員同士での懇親会というのも毎年やらせていただいておりますので、そこからいろいろ教育的な活動の交流をしていきたいと思います。","id":"exchange-122"},{"speaker":"田中委員","kind":"質問・要望","question":"私は特に、日本を代表する教育者である人物の学びは、すばらしい題材だと思いますので、ぜひ教育委員会としてより積極的に捉えていただきたい。特に地元の第三日野小学校を中心にお願いしたいと思いますが、ご意見をお伺いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"福澤諭吉の学習についてなのですけれども、現在市民科の３、４年生の教科書の中で、人物紹介をしています。","id":"exchange-123"},{"speaker":"田中委員","kind":"意見","question":"私が先ほども言いましたように、それを子どもの教育だけではなくて、大人のいわゆる生涯教育といったことも含めて広く、またその年代も小学校だけではなく、教育の題材としては最高の題材だと思いますので、中学校をはじめしっかり積極的にお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-124"},{"speaker":"吉田委員","kind":"質問・要望","question":"私が質問したのは、生徒指導提要の１０５ページに書かれているような事例をイメージしたのですけれども、適切と判断したのでしょうか。それぞれ伺います。","respondent":"中谷指導課長","answer":"現在の項目をご覧いただいているかと思うのですが、それに関しては性暴力もあり、体罰等もありというようなところになっています。都内全地区、それが東京都教育委員会の立場から考えると共通項目で取るという必要性を感じて、このような形になったのかと受け止めています。","id":"exchange-125"},{"speaker":"吉田委員","kind":"質問","question":"ただ、一方で体罰、いわゆる生徒指導提要の１０５ページに書かれているような体罰がなくなったとはちょっと思えないのです。ではそれはもう少しこういう項目を増やすべきだというような意見を言えるはずだと理解していたのですけれども、それは違うのか尋ねました。","respondent":"中谷指導課長","answer":"お話しいただいたとおり、性暴力に関する課題が非常に高いという受け止めをしている中で、こういうようなものに反映したのではないかと考えています。区としても、東京都教育委員会にそういった体罰等もなくなっていないということも含めた意見については…","id":"exchange-126"},{"speaker":"吉田委員","kind":"質問・要望","question":"それと、この調査で体罰に関する答えもしていいのだということを、ＰＴＡの保護者のほうに伝えるべきだと思います。この調査は体罰等に関する調査でもあるのだということをしっかり伝えていただきたいと思うのですけれども、お考えを伺います。","respondent":"中谷指導課長","answer":"お手紙が主流かと考えていますが、必ず周知をしてからお子さんたちに行うというような手立てを取っておりますので、これも引き続きやってまいりたいと思います。","id":"exchange-127"},{"speaker":"吉田委員","kind":"質問・要望","question":"香りの害を苦手とする子どもたちへの配慮を求めて、生活者ネットワークは質問を繰り返してまいりました。コロナ禍で感染防止の視点から自前の給食着を持ってきてよいことになった学校があったと伺いましたが、それは継続しているのか確認させてください。","respondent":"柏木学務課長","answer":"給食の白衣の個人の持参についてですが、学校のほうで個別に対応していますが、コロナが５類になったから、そういうのをやめたという話は聞いてございません。","id":"exchange-128"},{"speaker":"吉田委員","kind":"質問・要望","question":"最近では、化学物質過敏症または環境過敏症などと呼ばれて、合理的配慮が求められるようになりました。ぜひこの品川区においても、この点についての香りの害についての問題意識をどのようにお考えか、伺いたいと思います。","respondent":"柏木学務課長","answer":"令和３年に国の５省庁が化学物質過敏症の啓発のポスターを周知して、そちらのほうを各学校のほうに周知をしています。令和４年３月に厚生労働省のほうから、こちらのほうも学校のほうに周知し、化学物質過敏症について啓発をしています。","id":"exchange-129"},{"speaker":"吉田委員","kind":"質問・要望","question":"前に伺ったときは、ポスターはデータで送られてきて、教育委員会としてそれぞれの学校に配っていると理解してよろしいのでしょうか。その点についてもご協力ほしいと求めましたが、そういう検討の余地があるかどうか、ちょっとお答えください。","respondent":"舩木庶務課長","answer":"区の教育委員会の後援のあり方につきましては、区との関係性であるとかいろいろ要件がありますので、そういったところに適合するかどうかについては、検討ということになるかと思います。","id":"exchange-130"},{"speaker":"吉田委員","kind":"質問","question":"なかなか力量がなくて、そういう大々的なほかの自治体みたいなイベントを開けないのですけれども、もしそのときにはぜひご検討をお願いします。それから、調査活動についてもご説明に伺いますので、ぜひご協力・ご検討くださいますようお願いして、質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-131"},{"speaker":"若林委員","kind":"確認","question":"就学時健診の１年前に、主に言語・知的発達を確認するための検診の実施が保健所を中心に検討をされている現状があります。これについて一つちょっとお聞きしたいと思います。","respondent":"唐澤特別支援教育担当課長","answer":"就学時の前の検診についてですが、現在、教育委員会のほうでも就学相談というものを就学前の段階で行っております。内容というよりかは、やはり連携することが肝要かと考えていますので、引き続き関係部局と連携していければと考えています。","id":"exchange-132"},{"speaker":"若林委員","kind":"質問","question":"そして保健所と、また福祉との検討会というのでしょうか、協議会というのでしょうか。そこに臨んでいただいて、子どもたちにとって有益となるような１年前の検診になるように切に希望いたしますが、ご答弁をお願いしたいと思います。","respondent":"唐澤特別支援教育担当課長","answer":"我々で実施する就学相談の１年前に情報が分かるという形であれば、その間、保護者の方がいろいろ検討する時間というものも出ますでしょうし。教育委員会としましては、そうした情報を整理しながら、関係機関と連携していければと考えています。","id":"exchange-133"},{"speaker":"若林委員","kind":"確認","question":"次に、３９５ページの学校環境整備関連について、何点か伺います。いいのかどうかという確認と、併せて年に８個であるとすれば、これについても確認をします。","respondent":"荒木学校施設担当課長","answer":"令和５年度は鈴ケ森中学校と富士見台中学校で実施しまして、本年度も台場小学校と京陽小学校２校で実施をしております。令和１０年度までに完了するというなかなか高い目標は示しているのですけれども、今後も計画的にしっかりと改修を進めてまいりたいと考えております。","id":"exchange-134"},{"speaker":"若林委員","kind":"質問・要望","question":"環境も守る、また地域の声も大切にするという難しい仕事かもしれませんけれども、着実に進める部分については進めてほしいと求めました。これは事務事業評価を基に質問していますので、もう少し明確な答弁があるかなと思いましたけれども、今後またぜひ進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-135"},{"speaker":"西本委員","kind":"質問・要望","question":"３７８ページの教育指導費についてお尋ねします。教育長、ぜひお答えいただきたいのですが、これからの品川区の教育、子どもたちをどうしていかれたいと思いますか。","respondent":"舩木庶務課長","answer":"それからその実現のための教育施策の目指すべき姿、これを大きなグランドデザインとして示すことができるよう、現在検討を進めております。今教育委員会にある教育目標や基本方針をどのように具現化していくかということを体系的に示していくものですが、今、検討を進めておりま…","id":"exchange-136"},{"speaker":"西本委員","kind":"質問・要望","question":"私は教育長に答弁を願いたかったのです。子どもたちをどうしていくのですかということ、予算立てをどう考えているのですかということ、いかがか尋ねました。","respondent":"伊崎教育長","answer":"ただいま庶務課長のほうから、今年度教育振興基本計画の策定準備をしているということをご説明させていただきました。その獲得に向けて、学校・地域・家庭がどのように協力して進めていくということを示していきたいと、そのように考えております。","id":"exchange-137"},{"speaker":"西本委員","kind":"質問・要望","question":"特に教育ですから、こうあるべきという、これは国の動きがあってではないですか。これは施設を問わず就学前教育なのではないのですかということ非常に疑問を思いますので、この２つについての考えをお聞きしたいと思います。","respondent":"唐澤特別支援教育担当課長、中谷指導課長","answer":"発達障害教育支援員の配置や、お話にありました医療的ケアの対応につきましては、令和３年度より就学相談を通して看護師の配置等対応しています。今後もこうした支援につきまして、誰一人取り残さないでお子さんを育てるという視点で… 地元の幼稚園、保育園、そして小学校がチームとなっていくことが大事だと考えています。特に架け橋期である５歳児から１年生の２年間の教育の工夫と充実というところが重点だと考えていますので、今、まず集まる組織をつくるということ…","id":"exchange-138"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ今までやってきたことを十分に認識してほしいと求めました。そして、品川区ならでの教育をぜひ実現させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-139"},{"speaker":"石田（秀）委員","kind":"質問","question":"前教育長、前々教育長も含めて、では品川の子どもたちをどのように育てていくのですかと。変わっているのだったら何か違う言葉を言ってほしいと求めました。","respondent":"伊崎教育長","answer":"未来を創る力、未来を生きる力、未来を生き抜く力ということで、品川区は教育を進めてまいりました。新たな価値を創造する力、ちょっと一言にはならないのですけれども、こういう力をつけていきたいと考えております。","id":"exchange-140"},{"speaker":"石田（秀）委員","kind":"質問","question":"それは校長先生の権限でどうやっていくかということを、もっと校長先生を信じてあげたほうがいいと私は個人的には思っています。だからそういう形のことをどのように捉えられていますかということを、ちょっとお聞きしたい。","respondent":"中谷指導課長","answer":"これが、例えば専門家から教えていただいたら、それをしっかり学びが継続するようにカリキュラム・マネジメントのような形で。特色ある教育活動の予算として申請書を出していただければ、私たちのほうでこれを検討するというプロセスを取っています。","id":"exchange-141"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういうふうに海外だって何だってよくて、学校で子どもたちのためにここに行きたと言うのならば、私の考えはそこで制約だけは設けないでほしい。私は決していいことではないと思うので、そこら辺のところは、最後それだけ聞いておきます。","respondent":"丸谷教育総合支援センター長","answer":"東北方面に行くとか、海外はなかなかいろいろ費用面もあるとは思いますけれども、そういった可能性を広げていく。そうした学校の裁量というものは持たせているところです。","id":"exchange-142"},{"speaker":"石田（秀）委員","kind":"意見","question":"文化財の予算というのは４４０万円ぐらいだから非常に少なくて、ぜひこの辺の文化の継承については、もう少し考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"３９３ページ、教材教具等経費の中の教師用教科書、指導書購入についてお尋ねします。それで、決算額５,１４５万５,８１６円について、契約内容を伺います。","respondent":"柏木学務課長","answer":"すみません、契約の本数ですが、今すぐにはお答えできません。令和６年度の教科書は、あと指導書の購入分になってございまして、契約先は同じく東京教科書供給株式会社となっています。","id":"exchange-144"},{"speaker":"高橋（し）委員","kind":"確認","question":"では、契約本数は複数ということですか、確認します。それから、入札なのか随意なのかということをお尋ねします。","respondent":"柏木学務課長","answer":"決定権者につきましては、こちらは随意契約で所管の契約ができますので、学務課長となっています。令和６年度につきましても、同様に学務課長の決定で随意契約となっています。","id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"質問","question":"「議会の議決に付すべきものならびに」、これは４,０００万円以上ですが、「特に区長が指定するものについてはこの限りではない」ということです。なぜ議会に付さなかったのかということと、あと、契約を今幾つかに分けた、２本と言いましたが、それに分けたのか尋ねました。","respondent":"柏木学務課長","answer":"令和５年度につきましては、小学校と中学校と、あと教科書と指導書で契約は分けているものとなります。現在、契約の規則の４,０００万円につきましては一般需用費になってございまして、使用料および賃借料での契約となっています。","id":"exchange-146"},{"speaker":"高橋（し）委員","kind":"質問","question":"なぜそういうふうにお話しするかというと、令和５年度の決算が４,０００万円を超えています。４,０００万円を超えるということについては議決が必要だということをご存じだったのか、前々からやっていたのですけれども、いかがか尋ねました。","respondent":"柏木学務課長","answer":"４,０００万円以上の物品の購入については議決が必要というのは、存じ上げてあります。ただ、いわゆる一般需用費ではなく使用料の扱いになりますので、４,０００万円の対象外判断をしています。","id":"exchange-147"},{"speaker":"高橋（し）委員","kind":"提案","question":"今、そういう判断をされたということですけれども、デジタル教科書は令和２年の１億３,０００万円の中にあるのでしょうか。この件について教育長の見解と、今後の対応をどのようにするか、お伺いしますとの意見を述べました。","respondent":"柏木学務課長","answer":"繰り返しになる部分がありますけれども、こちら、４,０００万円で議決の必要につきましては、いわゆる一般需用費、物のものとなっています。令和２年度もございましたが、それは使用料という扱いになりますので、契約の規則に沿ったものと考えています。","id":"exchange-148"},{"speaker":"高橋（し）委員","kind":"質問","question":"議会の議決に付していない条件の有無についての調査、もしくは地方自治法第１９９条において、区長から監査委員に監査の要求が必要かと思われます。これは特別監査になるかと思いますが、他自治体では定期監査で見つかって、随時監査を出したり特別監査をしていますが、いかがか尋ねました。","respondent":"久保田企画経営部長","answer":"今、教科書の関係は学務課長が説明したとおりの契約ということで、我々も認識しています。今委員から指摘がありましたので、我々のほうでも経理課で確認をさせていただき、また改めて報告させていただきたいと思います。","id":"exchange-149"},{"speaker":"松本委員","kind":"質問","question":"私からは３７７ページ、就学援助費、３８５ページ、マイスクール運営費について伺います。これからの質問は、その手前の就学援助の中のお話を少しお伺いしたいのですが、これは年間でいつの段階で支給されるのか伺います。","respondent":"柏木学務課長","answer":"修学旅行費の支給ですけれども、こちらは修学旅行に行ったことが確認されて、それの後の直近の支払い月になってあります。ですので、１学期で行っている場合には７月の支給、２学期に行く場合については１２月の支給となっています。","id":"exchange-150"},{"speaker":"松本委員","kind":"質問・要望","question":"やはりこの６万円というのはすごく大きいということで、平成３０年度から新入学学用品については前倒しで支給していただいているかと思います。先に払うという対応もあるのではないかと思いますというか、これは要望したいのですけれども、いかがか尋ねました。","respondent":"柏木学務課長","answer":"就学援助の修学旅行費の前倒しについても、教育委員会としては検討しています。修学旅行の無償化のときも申し上げてありますが、予算編成の中で考えていきたいと考えています。","id":"exchange-151"},{"speaker":"松本委員","kind":"質問","question":"もちろんサービスによって、施策によっては区立校に限定するということはあると思うのですが、そことの関係でマイスクールについて伺います。対象にはならないというふうな国の法令、あるいは都の条例等の根拠があるのか、伺います。","respondent":"丸谷教育総合支援センター長","answer":"教育支援センター、私立の学校に在籍する児童・生徒は受け入れてはいけないというような法的な根拠はございません。区立学校に在籍する児童・生徒への支援も十分に行われていない段階でございまして、私立学校を含め国立、現状では難しいという判断をしております。","id":"exchange-152"},{"speaker":"松本委員","kind":"質問","question":"不登校の方たちが、もちろん優先順位はあるのかもしれませんが、そこは必ずしも拒む理由にはならないのではないかなと思っています。私立の子どもたちがどうしたらいいのかということを考えたときに、適応指導教室はあるのか、伺います。","respondent":"丸谷教育総合支援センター長","answer":"我々のほうでは、東京都が設置する適応指導教室、教育支援センターの設置は確認できておりません。","id":"exchange-153"},{"speaker":"松本委員","kind":"質問","question":"それをどう考えるかというところですが、「なお、教育支援センターの利用を認めるなど柔軟な運用がなされることが望ましい」との記載があります。やはりマイスクールの対象を区立学校に限る必要はないというか、そこは変えていっていただくのがいいのではないかと思いますが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"我々も文部科学省の通知についての認識はございまして、校内別室指導支援員の配置等、事業を拡大しております。私立等の学校に在籍する児童・生徒の受入れについて、キャパシティーが今後生まれるようなら検証していきたいと考えております。","id":"exchange-154"},{"speaker":"松本委員","kind":"質問・要望","question":"要望というわけではないのですが、課長に伺ったら、この場を借りて昨日の報告をさせていただきました。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-155"},{"speaker":"須貝委員","kind":"質問","question":"こんなことをいつまでもやっていていいのでしょうか。専科は別ですが、この２つの免許が必要ですが、２つの免許を持った教員は集まっているのか尋ねました。","respondent":"中谷指導課長","answer":"かねてより東京都に対して移譲ができないかということも引き続きやっているところでありますので、これは継続していくというところになります。小学校と中学校、固有教員に関しては、そういった方が集まっていただいているという現状です。","id":"exchange-156"},{"speaker":"須貝委員","kind":"質問","question":"これは前もお聞きしましたが、結局、東京都の教員ですから、３年たったら出入り自由ですよね、先生方が。やはりこういうシステムも、私は何か改善していかないとまずいかと思うのですが、その辺についてもう１回ご見解を説明を求めました。","respondent":"中谷指導課長","answer":"国の「当面は」というフレーズがずっと残っているという現状についてのご指摘かと考えていますけれども、先日行いました小中一貫全国連絡協議会の中でもやはり話題になっておりましたので、継続してそのことは発信していく必要はあると思っています。","id":"exchange-157"},{"speaker":"須貝委員","kind":"質問","question":"１８年たってなかなか正式に認可されないような状況、これは失敗するのですかね、このまま行ったら。もう公立に行かない、そういう子どもたちが多いように私は聞いているのですが、この数字は間違いないか尋ねました。","respondent":"柏木学務課長","answer":"区立小学校を卒業し、私立の中学校に行かれる方のパーセンテージですけれども、委員のおっしゃる数字を若干上回っている感じです。","id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"何か指導に対して不安とか、そういうことの表れでもあるのではないのですか。私たちは「何やっているのですか、教育委員会」というふうに言わざるを得ないのですが、その辺についてご見解を説明を求めました。","respondent":"中谷指導課長","answer":"もしも１つの種目を継続していれば、技術面での上達が高く期待できるということを直接おっしゃっていました。その責任感を育てなければいけないと考えていますので、しっかり魅力として捉えていきたいですし、発信もしていきたいと思っています。","id":"exchange-159"},{"speaker":"須貝委員","kind":"質問","question":"こんな教員を都から言われたって、やはり明確に手を挙げていかないと、品川区の教育制度は１８年たちましたが全然変わらないではないですか。どういう教員を品川区で育てていくのだとか、そういうことの根本をやらないと、教育委員会の皆さんだってしようがないではないか尋ねました。","respondent":"中谷指導課長","answer":"例えばやりたい部活ができるようにというのは、今まさに地域移行も進めておりますし、引き続き力強くやっていきたいと考えています。先ほどもお話しいただいたとおり、いま一度、これからどういうステージで歩んでいけばいいのかというところを発表していきたいと考えています。","id":"exchange-160"},{"speaker":"鈴木委員","kind":"質問・要望","question":"伺いたいのが、その会計年度任用職員の内訳を教えてほしいと求めました。学校巡回、経験の蓄積も大事な専門職であるにもかかわらず、なぜ正規職員ではなくて全てが会計年度任用職員なのかについても伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"教育総合支援センターには心理士が２７名、教員免許を持っている方が１９名、東京都任用のスクールカウンセラーが５４名おります。新規で採用を目指す方との機会均等の確保といったことも考えまして、会計年度任用職員としています。","id":"exchange-161"},{"speaker":"鈴木委員","kind":"質問","question":"大体手取りで２０万円ちょっとぐらいではないでしょうか。会計年度任用職員のこういう状況ですので、これは待遇の改善が必要だと思いますが、区としてどう考えられているのか伺いたいと思います。","respondent":"宮尾人事課長","answer":"昇給の仕組みですけれども、年度ごとに新たに設置をするという考え方ですので、昇給という考え方につきましてはなじまないものと考えています。勤勉手当につきましても今年度から支給がされているというところで、一定程度、改善というものはなされているものと認識をしています。","id":"exchange-162"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから、定期昇給をしてほしい、退職金が欲しい、継続雇用にしてほしい、いずれも３０数％の方が答えています。こういう会計年度任用職員の声、要望というのは届いているのか、それに対してどう捉えているのか伺いたいと思います。","respondent":"宮尾人事課長、丸谷教育総合支援センター長","answer":"それにつきましては、真摯にいつも対応しています。今年度から勤勉手当の支給も開始というところもありますので、そういったところも一定程度、処遇改善というのは図られているものと認識をしています。 東京都のスクールカウンセラーが、品川区でも複数名入れ替わっているところではありますけれども、学校から、スクールカウンセラーの変更に伴い何か不都合があったというような報告は、こちらのほうには上がってきておりません。","id":"exchange-163"},{"speaker":"鈴木委員","kind":"質問・要望","question":"こういう働く人の立場を考えて、品川区としても継続雇用ができる制度に改善すべきではないかと思うのですが、いかがでしょうか。この総務省の通知に対しては、品川区として検討したのか、その検討の中身も説明を求めました。","respondent":"宮尾人事課長","answer":"総務省の任用回数の上限を撤廃する通知に対しての対応です。品川区は、毎年職の必要性を検討して職を設置するという考えでやっておりますので、実際に雇用されていらっしゃる方がいるという現実があります。","id":"exchange-164"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これは、ぜひ推進計画をつくっていただきたいということで求めたいと思います。ぜひ区としてもこの推進計画をつくっていただきたいと求めたいのですが、いかがか尋ねました。","respondent":"唐澤特別支援教育担当課長","answer":"特別支援教育の現状につきましては、長期基本計画、総合実施計画などに基づいて行っているところです。２３区の現状、推進計画を単独でつくっていたり、そのほかの中と一緒に併せてつくっている地区があることは存じております。","id":"exchange-165"},{"speaker":"大倉委員","kind":"質問・要望","question":"頑張って３園、受入れが進んでいくようにしてほしいと求めましたが、いかがでしょうか。学校の１階から３階ですからすごい数の紙を、紙が全部埋まったというような、すばらしい取組になりました。","respondent":"中谷指導課長、荒木学校施設担当課長","answer":"今年度から台場小学校で、かけ橋研究会といいまして年間８回程度の集会を開くということで、教員同士の交流ができるようになっております。まずスタートとしてとても大事だと考えていますので、促進を促していくために… 児童、保護者から、地域も含めて大変好評だったということを伺っております。子どもたちや地域の思い出づくりの一環として、工事期間中ならではの機会を提供できるように、今後検討してまいりたいと思います。","id":"exchange-166"},{"speaker":"大倉委員","kind":"質問・要望","question":"小学校のお別れ会の評価ということで、そういった会があれば支援していっていただきたいと考えています。予算の考え方、ぜひそういったことに取り組む際にはつけていただければと考えていますので、その件についてお話を聞かせてください。","respondent":"柏木学務課長","answer":"校舎とのお別れのそういう紙代等ですけれども、特段そのために予算を、校舎を閉じるときに取っているということはございませんが、学校からそういうご相談があれば、学務課で相談には乗りたいと考えております。","id":"exchange-167"},{"speaker":"大倉委員","kind":"提案","question":"何か記念のときに、また１００周年とか、そういう周年行事とかに使うというようなことも考えているのだと思います。以前もご提案をさせていただきましたが、ぜひ検討していただきたいと思うのですが、いかがか尋ねました。","respondent":"荒木学校施設担当課長","answer":"現在実施している学校改築時における歴史保存の取組について、ご説明します。庁内他部署や他自治体事例を確認しながら、研究を進めてまいりたいと思います。","id":"exchange-168"},{"speaker":"大倉委員","kind":"意見","question":"歴代の卒業生が作っていた作品を泣く泣く処分しなければいけないということもありましたし、それを、ＶＲを使えば全部見られます。動画も見られるようになりますので、そういったことをぜひ研究して、検討につなげていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-169"},{"speaker":"あくつ委員","kind":"提案","question":"３７７ページ、私からはベーシック・サービスの観点から、教育に係る費用の無償化について伺ってまいります。そして、今後、修学旅行費の無償化をベーシック・サービスとして取り上げていくことがふさわしい取組ではないでしょうかとご提案を申し上げましたとの意見を述べました。","respondent":"柏木学務課長","answer":"７年生も移動教室がありまして、私費として食事代等を出す部分で１万１,０００円、令和５年度の実績で１人当たり６万５,０００円となっています。６年生の移動教室で２,１００万円、７年生の移動教室で２,２００万円…","id":"exchange-170"},{"speaker":"あくつ委員","kind":"質問・要望","question":"いかがでしょうか。ぜひ無償化を要望いたしますが、いかがか尋ねました。","respondent":"柏木学務課長","answer":"移動教室、修学旅行、標準服等の無償化の件です。委員が言われたものにつきましては様々検討をしていますが、繰り返しの答弁になりますが、今後の予算編成の中で整備していきたいと考えています。","id":"exchange-171"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今日は統一したご答弁ということですが、ほぼ、全ての会派からそのような要望が出ておりますので、ぜひ検討を進めてほしいと求めました。品川区の教育の無償化を完成させてほしいと求めましたが、最後に森澤区長、いかがか尋ねました。","respondent":"森澤区長","answer":"今、区が進めているウェルビーイングの考え方にも同じものだというふうに、同じ方向だというふうに感じているところであります。そういった中では、奨学金をどういった形で実現できるのかということを、具体的に検討していきたいと感じているところであります。","id":"exchange-172"},{"speaker":"あくつ委員","kind":"提案","question":"議会としても提案をしますので、品川区からも新たなベーシック・サービスの形をつくっていただいて、その発信をお願いしたい。そのことをお願いいたしまして、本日６日目となります款別審査、私の質問を終わらせていただきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-173"},{"speaker":"まつざわ委員","kind":"質問","question":"３８１ページ、４０１ページの学校改築推進経費、順不同で伺います。これを踏まえて、もう一度ご答弁をお願いします。","respondent":"丸谷教育総合支援センター長","answer":"水泳のみならず様々な授業で、教員が主たる指導者として、チームティーチングで授業を支えていただいております。子どもの安全管理ですとか、指導、技能の向上を目指すという形で関わりをいただいているところです。","id":"exchange-174"},{"speaker":"まつざわ委員","kind":"確認","question":"テクニカルアドバイザーが教員を支えているというのを確認しました。委託料が１,５００万円だと思ったのですが、この委託料の１,５００万円はどういうふうになっているのか、そこを確認させてください。","respondent":"柏木学務課長","answer":"そのうち何回か指導員が派遣されているという形になりますので、プールの中止が多いから委託ができていないというわけではないと。それと、その人の人件費は払わなければいけないと考えていますので、そこはスポーツ協会がきちんとと精算して実施しているという形になってありま…","id":"exchange-175"},{"speaker":"まつざわ委員","kind":"質問","question":"何と言えばいいですかね、やはり中止になろうが何だろうが、お金というのが発生するということですよね。そういうことですね。","respondent":"柏木学務課長","answer":"例えばもう何日かまでは台風が来るとか、そういうのが分かっていれば、もう事前に中止になりますので、そこら辺ではもうお金は発生しないということになりますが、先ほど言ったとおり、今日が暑くて駄目だったという場合については、お金は発生するという形になってあります。","id":"exchange-176"},{"speaker":"まつざわ委員","kind":"質問","question":"半分以上できていないです。何というのですかね、プール授業というのは学校でできない分は補えるかなと思うのですが、そこら辺のご見解を説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"こちらは体育の授業という形ではなくて、教育課程外ではありますけれども、児童の水泳の技能の向上のために開かれているものだと認識しております。移動しなければいけないというような様々な課題もありますので、そうしたことがクリアされれば…","id":"exchange-177"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"でも、それもカウントされてしまうと多分８０％となるので、ぜひ検討していただきたいと思っています。現在までにどのように進んできたのか、またどれだけ改築していない学校が残っているのか、説明を求めました。","respondent":"荒木学校施設担当課長","answer":"区内における改築の実施状況です。進捗状況といたしましては、４６校中２７校ということで、５９％の改築に着手したという状況です。","id":"exchange-178"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"地域バランスというのはどういうふうに考えるのかなというのは、地域バランスというところで、またいろいろと検討していただきたいと思っています。そうすると、まだこれから今後２５年ですかね、２０年ぐらいかかりますよね。","respondent":"荒木学校施設担当課長","answer":"今後の学校改築のビジョンですが、現段階では総合実施計画に基づき、１年１校というペースで着手をしています。学校から福祉施設、地域コミュニティ施設への転用など、将来の区民要望や社会ニーズに合わせて柔軟に対応できるような施設としております。","id":"exchange-179"},{"speaker":"まつざわ委員","kind":"質問","question":"城南第二小学校の工事の見学会に行って改めて思ったのですが、これも工事が６年ぐらいですか、かかってしまうのですね。工期がどうして長くなってきたのか、保護者から工期が長いことについて心配する声などがあったのか、説明を求めました。","respondent":"荒木学校施設担当課長","answer":"これは、就学人口増への対応や、特別支援教育の充実化などに対応するためです。必要な教室数を確保しつつ、校舎をコンパクト化することや、標準的な仕様で安定供給が見込めるような資材の調達に努めているところです。","id":"exchange-180"},{"speaker":"まつざわ委員","kind":"質問","question":"やはり１５分、１０分で走って帰ってきて、間に合わないのですよね。もう全力で走っていって、やはり安心・安全の部分が心配かなと思ったのですが、こういうときというのはどういう対応をしたらいいのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"課題としては認識いたしました。学校には情報提供するとともに、ぜひ保護者の方から各学校、顧問にお問合せをいただいて、改善に努めていければと思います。","id":"exchange-181"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/285407?Template=document&Id=6859#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":117794,"voices":401}},{"id":"r06-20241021-4","meetingId":"r06-c-settlement","date":"2024年10月21日","dateIso":"2024-10-21","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ３時５１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を101件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"西村委員","kind":"質問","question":"初めに、品川区における令和５年度決算について質問いたします。特別区税収など歳入決算額の推移と併せて、令和５年度決算に対する区の評価について説明を求めました。","respondent":"久保田企画経営部長","answer":"省エネルギー対策設備更新助成金の実施や、プレミアム付区内共通商品券の販売等により、事業者や区民生活を支援してきたところです。「誰もが生きがいを感じ、自分らしく暮らしていける品川」の実現に大きな成果を上げたと評価しています。","id":"exchange-001"},{"speaker":"西村委員","kind":"意見","question":"今、様々な施策をお聞かせいただいた元となります、令和５年度、区は４つのビジョンを掲げております。新規事業の実施に当たっての区の考え方、また財源の確保について説明を求めました。","respondent":"久保田企画経営部長","answer":"新規事業の実施に当たっての区の考え方等ですけれども、令和５年度予算は、未来を見据えた積極予算を編成したところです。新規事業に対する区の考え方につきましては、事業の実施により見込まれる成果・効果、積極的に予算化したところです。","id":"exchange-002"},{"speaker":"西村委員","kind":"質問","question":"新規事業と財源の確保についてお伺いさせていただいたのですが、様々、新規事業に関しまして実施していただいていることは理解しております。どのような考え方の下に補正予算を編成されているのか、改めて区のお考えを説明を求めました。","respondent":"久保田企画経営部長","answer":"補正予算ですけれども、予算に追加変更を加えるというものでございまして、速やかに対応するために事業を予算化するというものです。昨今は、様々な緊急事態・事象への対応が強く求められておりまして、区民の安全・安心を守るための施策を実現していく必要があると考えておりま…","id":"exchange-003"},{"speaker":"西村委員","kind":"確認","question":"事業のスクラップの考え方について伺ってまいりたいと思います。初めに、区では事業のスクラップの必要性をどのように捉えているのか、伺いたいと思います。","respondent":"久保田企画経営部長","answer":"多様化する区民ニーズに対応するため、新規事業の立ち上げや必要な事業を継続的に行うことを可能とするなど、重要な取組であると認識しています。その中で、事業のスクラップ等につきましても進めてきたところです。","id":"exchange-004"},{"speaker":"西村委員","kind":"質問・要望","question":"この削減された約２３億円については、どのような視点で算出されたものなのかをお知らせほしいと求めました。どのように捻出していかれるのか、現状のお考えを説明を求めました。","respondent":"久保田企画経営部長","answer":"評価の視点や考え方を大きく分類しますと、まずは１点目として、事業の廃止を判断したというものがあります。約２０億円を捻出することを目標として、多角的・客観的に評価を行いまして、財源の確保に努めていきたいと考えております。","id":"exchange-005"},{"speaker":"西村委員","kind":"質問・要望","question":"今年も２０億円の削減を目標とするということも理解はしております。その点、また見解をお聞かせほしいと求めました。","respondent":"久保田企画経営部長","answer":"長期基本計画や総合実施計画等の中長期的な展望の中で、事業の必要性や手法の効率性などを総合的に検討し、予算化しています。スクラップ・アンド・ビルドを継続的に実施し、新たな施策に財源を捻出し、振り向けていきたいと考えているところです。","id":"exchange-006"},{"speaker":"西村委員","kind":"提案","question":"様々、事業のスクラップについてお伺いしたいと思って伺ってまいりました。こういった懸念を解消するために、ぜひ予算編成や事務事業評価にサンセット方式を取り入れてはいかがかとご提案いたしますとの意見を述べました。","respondent":"久保田企画経営部長","answer":"社会経済の変化に伴う新たな行政課題や区民ニーズに的確に対応していくためには、事務事業を見直すための有効な手法の一つであると考えております。今後の予算編成や事務事業評価を進めていく中で、他自治体の取組などを調査研究しつつ、検討していきたいと考えているところです。","id":"exchange-007"},{"speaker":"西村委員","kind":"質問・要望","question":"続きまして、款別でも質問させていただきました５歳児健診について伺います。３歳児健診よりも、集団における振る舞いや発達状況を確認することの重要性が、こども家庭庁の通知でも伝えられています。","respondent":"阿部健康推進部長","answer":"私からは、３歳児健診でできる点と課題についてお答えいたします。３歳児健診の時点では発育・発達の個人差がまだ大きいため、子どもごとの支援の必要度の見極めがまだ困難であることが課題であると認識しております。","id":"exchange-008"},{"speaker":"西村委員","kind":"質問","question":"せっかく総括の機会でありますので、今、母子保健について担当課から伺わせていただきましたが、課を越えての取組をお願いしたいと思います。横断的にという点におきましても、教育についても伺ってまいりたいと思いますが、５歳児健診は年中で実施しますので、就学相談は年長児となります。","respondent":"米田教育次長","answer":"就学時健診は１０月から１１月に実施しているため、そこから就学相談を進める場合、手続や検討を含め、期間が短くなる現状があります。そうした実態を踏まえながら、保護者との対話を通して丁寧に対応していく必要があると考えております。","id":"exchange-009"},{"speaker":"西村委員","kind":"質問・要望","question":"こちらはこれから検討される段階ですので、要望とさせてほしいと求めました。これまでの３０年の振り返り、そしてこれからの未来の３０年をどうつくっていくのかを伺います。","respondent":"柏原区長室長","answer":"これまで、友好都市を結んで３０年ですけれども、オークランド市とはこれまでの３０年間で約１,３００人の方が交流してきたところです。様々な見地から検討いたしまして交流を促進いたし、国際社会発展に寄与できるよう、推進してまいりたいと考えています。","id":"exchange-010"},{"speaker":"西村委員","kind":"提案","question":"子どもたちが８０人近く集まったと伺っております。語学だけではなく、文化、芸術、スポーツの交流も求めますが、区の見解を伺いますとの意見を述べました。","respondent":"柏原区長室長","answer":"実施体制や経費のところ、こういったことも踏まえまして、国際友好協会と共に総合的に検討してまいりたいと考えております。形で、いろいろなところで広がりがあろうかとありますので、さらなる取組の拡充について今後検討していきたいと考えています。","id":"exchange-011"},{"speaker":"西村委員","kind":"質問・要望","question":"少し難しい要望かもしれませんが、対象地を広げるということもご検討いただきたいと考えています。ご答弁いただいてもよろしいか尋ねました。","respondent":"柏原区長室長","answer":"対象地を広げる検討といったところのご質問です。これらの国々との交流もさらに広げていくなど、新しい国際交流の在り方については模索してまいりたいと考えています。","id":"exchange-012"},{"speaker":"西村委員","kind":"質問・要望","question":"本当に、子どもたちのこれからの国際交流、グローバルな子どもたちを育てていくということを考えると、いろいろな取組が国際交流で考えられると思いますので、文化、芸術、そしてスポーツと、ぜひとも様々な発想で取組をご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"澤田副委員長","kind":"質問","question":"そこで伺います。教職員、保護者、当事者である児童などから、発達障害教育支援員が配置されてから寄せられているお声はありますか尋ねました。","respondent":"米田教育次長","answer":"発達障害教育支援員全校配置後のお声ですが、毎日配置されることで時間割や授業に応じて柔軟に対応できることなどが挙げられております。毎日１名の支援員がいることで、計画的な支援につながっていること、柔軟に対応できることなどが挙げられております。","id":"exchange-014"},{"speaker":"澤田副委員長","kind":"確認","question":"今年度からは発達障害教育支援員が毎日１人入ってくださっていますが、１校に１人では足りないというお声も伺っております。支援を行う人材の拡充の強化についてどのようにお考えか尋ねました。","respondent":"米田教育次長","answer":"支援員を含めまして、区で実施している特別支援教育に係る施策などについて、区民の方々への周知に努める機会を様々検討してまいります。各学校や教職員の特別支援教育の理解や啓発、支援員への研修の充実など、質の向上にも併せて努めてまいります。","id":"exchange-015"},{"speaker":"澤田副委員長","kind":"質問","question":"児童に対して、発達障害をはじめとした障害についての理解教育は現状どのように行われていますでしょうか。理解教育の必要について、区としてはどのようにお考えか尋ねました。","respondent":"米田教育次長","answer":"児童・生徒向けの発達障害の理解に向けた教育の実施についてですが、現在、区主催の研修会や各学校の校内研究で教職員向けの研修を実施しており。互いに認め合うことは重要なことと認識しておりますので、引き続き…","id":"exchange-016"},{"speaker":"澤田副委員長","kind":"質問","question":"本区には、発達障害児に特化したリーフレットなどはあるでしょうか。併せて、保護者に向けた発達障害児の理解についてどのようにお考えか尋ねました。","respondent":"米田教育次長","answer":"説明会についても、回数、実施場所を増やして対応したところです。教育委員会で作成しております特別支援教育リーフレットをホームページに掲載するなど、福祉・就学前施設等、関係部門との連携も図ってまいります。","id":"exchange-017"},{"speaker":"澤田副委員長","kind":"質問","question":"発達障害に特化したリーフレットをご検討ほしいと求めましたが、いかがでしょうか。通称「しなぽけ」との連携についてなど、区のお考えを説明を求めました。","respondent":"米田教育次長","answer":"発達障害につきましては、今後も説明会や研修会などの機会を捉え、区民の方や教職員への理解啓発に努めてまいります。発達障害児に特化したリーフレットにつきましては、関係各課とも連携し、既存の刊行物の活用など、その作成の在り方について検討を行ってまいります。","id":"exchange-018"},{"speaker":"澤田副委員長","kind":"質問","question":"続きまして、先ほどの質問の中で触れましたしながわこどもぽけっとについてお聞きします。その要因としては、チラシを母子手帳配付時に配ったこと、内容の充実が功を奏しているのではないか尋ねました。","respondent":"佐藤子ども未来部長","answer":"これらの対応により、利用者の満足度が高まり、結果としてアクセス数の増加につながったものと分析しております。今後も引き続き、子育てメッセなど、子育て中の保護者が集まるイベントを含めまして、様々な機会を捉え、周知活動を進めてまいります。","id":"exchange-019"},{"speaker":"澤田副委員長","kind":"意見","question":"子どもに人気の水遊びができるかどうか、ボール遊びが可能かどうか、さらに詳しく情報を増やすのも利便性向上につながると考えます。公園を紹介するに当たり、公園課と子ども育成課で連携している点、公園についての項目の充実への考え方を説明を求めました。","respondent":"佐藤子ども未来部長","answer":"次に公園課との連携ですが、アプリ開設当時、最新の情報の取得等について連携して対応いたしました。多くの子育て世帯が必要な情報の一つと考えますので、関係部署と連携しながら検討を進め、サービスのさらなる向上に努めてまいります。","id":"exchange-020"},{"speaker":"澤田副委員長","kind":"質問","question":"続きまして、「マイガーデン」農業体験についてお伺いします。大変好評と伺っており、今年度は「子ども青空農園」を第二庁舎で開催、また「マイガーデン」の３園目を検討されています。","respondent":"溝口防災まちづくり部長","answer":"かつ一定の広さを有する屋上などが必要となり、今回は第二庁舎の屋上緑化スペースを活用するなどの工夫をすることで実施することができました。大変ご好評を頂いている事業ですので、できるだけ発展できるように、今後も持続的に取り組んでいきたいと考えているところです。","id":"exchange-021"},{"speaker":"澤田副委員長","kind":"質問","question":"「マイガーデン」、「子ども青空農園」ともに大変好評であるということが、改めてお伺いできました。３園目を楽しみにしている方もたくさんいらっしゃいますけれども、４園目と続けて造っていただく上で、お考えはいかがか尋ねました。","respondent":"久保田企画経営部長","answer":"青空の「マイガーデン」の設置ということのご質問ですけれども、自由に出入りができないというのがほとんどですので、既存の区有施設の屋上に青空農園を設置することは難しいものと考えているところです。","id":"exchange-022"},{"speaker":"澤田副委員長","kind":"質問","question":"品川女子学院に「区民と議会の交流会議」でお伺いした際にも、「農業体験をしたい」、「野菜を育ててみたい」とおっしゃっていました。併せて、屋上を活用している学校があるのかも説明を求めました。","respondent":"久保田企画経営部長、米田教育次長","answer":"私からは、今後整備する区有施設に「マイガーデン」を設置したらどうかというようなご質問にお答えいたします。その場合には、新規施設を整備するですので… 小学校と義務教育学校を中心に、全４６校中３２校で設置しております。収穫した作物については、家庭科での調理実習や給食で使用するなど、子どもたちの食の関心を高めているところです。","id":"exchange-023"},{"speaker":"澤田副委員長","kind":"質問","question":"お伺いしたところ、食べるものを育てるという喜びを理解していただくためにも、今後とも屋上活用なども含めてご検討ほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"ゆきた委員","kind":"提案","question":"款別審査で我が会派より質問しましたが、個人情報の管理が必要な窓口であることから、こうした窓口への設置も必要ではないでしょうか。ご見解を伺いますとの意見を述べました。","respondent":"寺嶋福祉部長","answer":"関係団体と意見交換等をしながら、効果的な普及啓発について検討してまいります。それから在宅介護支援センター、ご議決を頂きましたら速やかに設置を行い、実施状況を確認した上で今後につなげていきたいと考えております。","id":"exchange-025"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"片耳の購入費は４万５,０００円、両耳購入費は９万円の助成を今年度の８月から実施し、両耳への購入費助成を実施する自治体も出てきています。そこで、都の事業の説明をいただくとともに、両耳の補聴器が購入できるよう、費用助成の拡充を求めますが、区の見解を伺います。","respondent":"寺嶋福祉部長","answer":"事業開始からまだ１年と数か月ですが、これまでの検証がまずは必要と考えております。昨今の経済状況につきましては十分認識していますので、さらなる社会参加支援に向けて、拡充について検討を進めていきたいと考えております。","id":"exchange-026"},{"speaker":"ゆきた委員","kind":"提案","question":"２点目はベーシックサービスの観点から、さらなる教育費の無償化を求めて質問します。そこで、改めて伺いますとの意見を述べました。","respondent":"米田教育次長","answer":"７年生は平均で１人当たり約１万１,０００円、総額として約２,０００万円を見込んでおります。５年生の夏季施設については、平均で１人当たり約１万６,０００円、総額として約４,８００万円を見込んでおります。","id":"exchange-027"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"修学旅行費をはじめとした校外での体験活動について、所得制限のない無償化を決断していただきたいと考えますが、いかがでしょうか。中学校・義務教育学校の標準服、いわゆる制服も教育のベーシックサービスにほかならず、標準服代金の無償化を要望しますが、ご所見を伺います。","respondent":"米田教育次長","answer":"子育て家庭の負担を軽減し、子育てしやすい環境を整備するため、給食費や補助教材費の所得によらない無償化を段階的に進めてきたところです。修学旅行費や標準服代等、さらなる無償化とのご提案につきましては、今後の予算編成作業の中で考え方を整理し、検討を進めてまいります。","id":"exchange-028"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"そこで、子どもの未来の育成のため、改めてベーシックサービスの考え方とウェルビーイングの関係について、どうお考えか伺います。大学と授業料の無償化である、品川区独自の給付型奨学金の創設を求めますが、ご所見を伺います。","respondent":"佐藤子ども未来部長","answer":"ベーシックサービスの考え方とウェルビーイングの関係に関わる区の認識についてお答えいたします。区独自の大学生向け奨学金の実施につきましては、所得制限によらない奨学金の在り方について具体的に検討していきたいと考えております。","id":"exchange-029"},{"speaker":"ゆきた委員","kind":"質問","question":"そこで、国の事業について、区の認識をお聞きするとともに、耐風診断の目的など、事業概要と利用件数など、実績についてお聞きします。過去の台風における品川区内の被害状況について、屋根被害の件数や区の対応についてもお知らせください。","respondent":"鈴木都市環境部長","answer":"令和４年度より、屋根の耐風診断および改修補助事業が国より開始され、強風による住宅屋根の被害防止に効果があるものと認識しています。そうした状況の中での区の対応ですが、見舞金や罹災証明の発行、それから住宅改善工事助成等の事業の周知を行ってきたところです。","id":"exchange-030"},{"speaker":"ゆきた委員","kind":"提案","question":"そこで、品川区において風害による被害を減災するためにも、国の補助事業を活用した耐風診断・耐風改修助成の実施を提案します。併せて耐風診断、耐風改修の周知について求めますが、区の見解を伺いますとの意見を述べました。","respondent":"鈴木都市環境部長","answer":"屋根の安全化に関する直接的な事業は実施していないところですが、現在、強力に推し進めているところです。ご提案の耐風診断助成補助につきましては、今後の補助に関する都の動向や他区の取組状況などについて注視してまいります。","id":"exchange-031"},{"speaker":"ゆきた委員","kind":"質問","question":"近年増加する風水害に対して、ぜひ前向きに進めてほしいと求めました。これで私の質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"塚本委員","kind":"質問","question":"初めに、豪雨による水害対策について伺います。そして、現在までの取組成果と目標達成度合いについて、区の公共施設などと、また民間の土木建築とのそれぞれについて説明を求めました。","respondent":"溝口防災まちづくり部長","answer":"公共、改定いたしました東京都豪雨対策基本方針の目標である時間８５mm降雨に対して浸水被害を防止するため、その一部を担う不可欠な取組です。設置の割合につきましては、民間が全体の７割となっている状況です。","id":"exchange-033"},{"speaker":"塚本委員","kind":"提案","question":"６mmの目標についてもほぼ達成しているというところで、その中でも７割が民間の対応によって達成されているというところをお伺いいたしました。区の見解を伺いますとの意見を述べました。","respondent":"溝口防災まちづくり部長","answer":"流域対策を積極的に実施している企業を都が認定することにより認知度向上を図り、流域対策の推進を、一体となって進めていくこととしております。活用を図るとともに、様々な場面を捉えまして民間の取組をＰＲするなど…","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問・要望","question":"区の見解を伺います。近年の豪雨の激甚化に伴い、浸水被害のリスクが高まっていますけれども、避難情報緊急通知コールの登録対象地域の見直しについて区の見解を伺います。","respondent":"溝口防災まちづくり部長、鈴木都市環境部長","answer":"改定した東京都豪雨対策基本方針では、時間１０mm降雨に対応する流域対策を加え、内水氾濫による浸水被害を防止することとしております。都の打ち出した時間８５mm降雨への対応として、様々な対策を実施していくことで… 他区において、現在のところ、区としての補助の実施は難しいと考えているところです。近隣の支持地盤データの提供や助言・アドバイスの実施など、区としましては引き続き、必要な支援を行ってまいります。","id":"exchange-035"},{"speaker":"塚本委員","kind":"質問・要望","question":"試験にパスできずに帰国せざるを得ない事態を避けるため、区として日本語習得も含めた資格試験合格のための支援策を求めます。事業所の負担を軽減する支援策について、区の見解を伺います。","respondent":"寺嶋福祉部長","answer":"こういった状況も踏まえて、どのような形の支援策が必要で効果的であるか、今後の重要な検討課題として捉えているところです。外国人雇用を進める上では、こういったあたりの支援が大変重要だと考えておりますので、こちらの点につきましても検討課題として認識しています。","id":"exchange-036"},{"speaker":"塚本委員","kind":"提案","question":"外国人の方の力を借りながら、今提案したことについての検討課題ということでございましたけれども、よろしくお願いいたします。区の見解を伺いますとの意見を述べました。","respondent":"寺嶋福祉部長","answer":"介護福祉専門学校に一定の外国人枠をという２つ目のご質問ですけれども、それから、一方で現場では外国人の受入れが進んでいると。そのような学生を支援する団体の聞き取り等も始めておりますので、どのような取組が可能であるか、引き続き情報収集に努めていきたいと考えていま…","id":"exchange-037"},{"speaker":"塚本委員","kind":"提案","question":"同行援護の資格取得のための研修は約２万円の費用がかかりますが、同行援護研修費を補助し、同行援護従事者を増やす試みを提案します。区の見解を伺いますとの意見を述べました。","respondent":"寺嶋福祉部長","answer":"研修費用が負担になっていることは認識しておりまして、この部分の支援が何らか必要ではないかというところは、区でも十分考えているところです。どのような支援をすることが一番効果的であるのか、この辺についてもしっかり検討していきたいと考えております。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問・要望","question":"助成上限額と申請回数についても、都の上限額１０万円と２回まで申請可能としていることを最大限に活用し、拡充するよう求めます。それぞれ、区の見解を伺います。","respondent":"阿部健康推進部長","answer":"助成の拡充についてのお尋ねですが、アピアランスケアは昨年令和５年７月に開始して１年数か月がたちまして、申請が徐々に増えてきているところです。１人の方が複数品目を購入するケースなどもありますので、申請者のニーズをよく酌み取った上で…","id":"exchange-039"},{"speaker":"塚本委員","kind":"質問・要望","question":"令和６年都議会第３回定例会の公明党代表質問で、片目失明者などにも対象拡大するよう求めたのに対し、前向きな答弁がありました。区の見解を伺います。","respondent":"阿部健康推進部長","answer":"エピテーゼ等、アピアランスケアを必要とする方への支援の必要性については、区も認識しております。今後、都や他区の動向を注視しつつ、支援の拡充については検討してまいります。","id":"exchange-040"},{"speaker":"ひがし委員","kind":"質問","question":"今年度、地域医療連携課が新設され、この２つの事業が移管されたと伺いました。さらに、地域医療連携課の目的についても併せて伺います。","respondent":"遠藤健康推進部次長","answer":"あるいは緊急医療救護所の医薬品の入替え、令和６年度はどちらにつきましても地域医療連携費として、地域医療連携課に措置しています。コロナ禍の対応を総括する趣旨で検証いたしました、新型コロナウイルス感染症対応の検証と、健康危機管理体制の基盤整備検討報告書の中におい…","id":"exchange-041"},{"speaker":"ひがし委員","kind":"質問","question":"２０２１年看護職員実態調査の結果によると、８割近くが自身への感染の恐怖や不安を感じ、長引く感染症対策で心身に疲労が深まる様子が伺えました。どのような内容が話し合われたのか、今までの会議体はどうなるのか、また品川区の地域医療連携における課題についても、あれば説明を求めました。","respondent":"遠藤健康推進部次長","answer":"いわゆる連携して取り組む事項、２回目を開催するということで、今週中にも実施することで進めているところです。それぞれの参加者の方の話を聞いて、どこまでできる・できない部分がありますので、それをより詰めていければと考えているところです。","id":"exchange-042"},{"speaker":"ひがし委員","kind":"質問","question":"そこでお伺いします。多職種との連携強化のためには必要と考えますが、こちらについても区の検討状況を併せてお答えください。","respondent":"遠藤健康推進部次長","answer":"今後、区としてどうするかですけれども、東京都の補助金が３年というところで聞いているところです。来年度までは補助金を使って医師会で進めるという形になりますけれども、話を聞いて検討していくような形になろうかと思っているところです。","id":"exchange-043"},{"speaker":"ひがし委員","kind":"質問・要望","question":"こちらは要望とします。それぞれの対象、また作成する人、またその作成における課題についても説明を求めました。","respondent":"寺嶋福祉部長、遠藤健康推進部次長","answer":"個別避難計画の状況ですが、まず障害者からご説明しますけれども、対象者は、身体障害者手帳１級から３級、愛の手帳１度から２度の方。それから、町会・自治会からのご意見としては… 窓口でアンケートを取りまして、その中から希望者という形になりまして、昨年からの実施で最終的には５０件の作成が行われたところです。先ほどの障害者や高齢者と一緒で…","id":"exchange-044"},{"speaker":"ひがし委員","kind":"確認","question":"前回確認したときよりも大分進捗が進んでいると実感しております。現在どのように進めているのか尋ねました。","respondent":"寺嶋福祉部長、滝澤災害対策担当部長","answer":"で、いわゆる基本的な接し方等についての普及啓発といったものも広げていって、支援者を増やしていくということが必要であろうと考えております。作成の段階で相談支援員… 避難支援に当たる防災区民組織に対して、現在、庁内で検討しています。いずれにしましても、災害弱者と言われます避難行動要支援者の支援体制を万全にできるよう、さらに検討を具体化していきたいと考えております。","id":"exchange-045"},{"speaker":"ひがし委員","kind":"質問・要望","question":"そちらをお願いさせていただきまして、私からの質問は以上で終わります。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"松永副委員長","kind":"質問","question":"本区では、２０２５年には６５歳以上の方がおよそ何人ぐらい予想されておりますでしょうか。なぜ６５歳以上について伺ったかといいますと、６５歳になりますと、その人数の方がほぼ退職されるのはないかと危惧しております。","respondent":"川島地域振興部長","answer":"昭和３７年６月の人口４２万２,８８０人が記録上の最多の人口になっておりますが、近い将来、品川区の人口は過去最多の人口を超える見込みです。そちらを見据えまして、ご指摘の６５歳以上の方でも…","id":"exchange-047"},{"speaker":"松永副委員長","kind":"質問","question":"シルバー人材センターについて伺うのですけれども、現在、シルバーセンターに雇用として登録されている数について伺いたいと思います。そして、シルバーセンターの中でどのぐらいの職種があるのか、併せて伺いたいと思います。","respondent":"川島地域振興部長","answer":"引き受けた仕事の内容に応じまして、土曜、日曜、祝日、早朝や繁忙期のみの就業など、短時間あるいは超短時間での対応も可能としているものです。それから簡単な事務作業などがありまして、ホームページで紹介されている範囲で言えば…","id":"exchange-048"},{"speaker":"松永副委員長","kind":"質問・要望","question":"約２０種類ぐらいということで伺いました。こうしたご要望にもぜひ応えていただきたいと考えていますので、これは要望で終わらせてほしいと求めました。","respondent":"溝口防災まちづくり部長","answer":"愛犬しつけ教室の実績といたしましては、令和３年度は１０回、１２５人、令和４年度は１４回、１５６人、令和５年度は１６回、１７８人の方にご参加いただいているところです。","id":"exchange-049"},{"speaker":"松永副委員長","kind":"質問・要望","question":"こうした人数と回数を確認させていただきました。この状況についても、同じく回数と人数を、もし計算してあれば教えてほしいと求めました。","respondent":"溝口防災まちづくり部長","answer":"令和５年度から愛犬しつけ教室の開催に合わせまして、仮設のドッグランの試行実施をしています。令和５年度の実績といたしましては、しながわ中央公園、東品川海上公園、戸越公園の３公園で計８回、実施できているところです。","id":"exchange-050"},{"speaker":"松永副委員長","kind":"質問・要望","question":"そこで、愛犬しつけ教室の利用者からアンケートを取っていただいているそうですが、主にどういった声が上げられておりますでしょうか。併せて、恒久的なドッグランの設置を要望いたしますが、いかがか尋ねました。","respondent":"溝口防災まちづくり部長","answer":"一方で、ペットを連れていない公園利用者からは否定的な意見も頂いているところです。愛犬しつけ教室の利用者の声、ドッグランの設置に向けて、引き続き検討していきたいと考えているところです。","id":"exchange-051"},{"speaker":"松永副委員長","kind":"質問・要望","question":"そこで伺いますが、もし万が一、飼い主の安否が確認されず、ペットのみが発見された場合、区としてどのような対応をされているのでしょうか。併せて伺います。","respondent":"滝澤災害対策担当部長","answer":"被災動物の保護は、動物関係団体などと共同して設置し運営する動物救護本部が中心となって行い、基本的には東京都で実施するようになっております。区としましては、東京都と連携しながらペットの適切な保護に努めてまいりたいと考えております。","id":"exchange-052"},{"speaker":"松永副委員長","kind":"質問・要望","question":"犬や猫を避難させた方たちへの受入れ体制は大丈夫なのでしょうか。併せて伺いたいと思います。","respondent":"滝澤災害対策担当部長","answer":"ペットの同行避難要領についてですけれども、現在、５２か所の区民避難所のうち３４か所でペット同行避難が可能な状況です。併せてペット用の避難の備蓄の充実を含めて、現在、受入れ態勢を万全にしていこうと考えているところです。","id":"exchange-053"},{"speaker":"松永副委員長","kind":"確認","question":"確認なのですが、先ほどの３４か所については全部、ペット受入れ可能ということだったのでしょうか。それで、備蓄についてもペット用品、例えばどういったものなのか尋ねました。","respondent":"滝澤災害対策担当部長","answer":"例えば犬であると区内に１万３,０００頭、区民の避難も約２割が避難所に避難されるということで、備蓄数については検討しております。家屋が倒壊、５％程度の方が備蓄品を持って来られないということを前提に、備蓄品についてはそれを基準に保管しています。","id":"exchange-054"},{"speaker":"松永副委員長","kind":"質問・要望","question":"ウサギとか、今後もしかしたらそうした要望が来るかもしれませんので、そうした受入れ体制についてもしっかりと取り組んでほしいと求めました。そうしたところで質問なのですけれども、目視調査について、それぞれ３年間の実績を伺いたいと思います。","respondent":"鈴木都市環境部長","answer":"アスベスト自体の除却助成につきましては、令和３年が１件、令和４年が２件、令和５年が１件。それから事前調査の派遣になりますが、こちらは令和３年が１件、令和４年以降では０件の状況です。","id":"exchange-055"},{"speaker":"松永副委員長","kind":"質問・要望","question":"いろいろ調査の実績を３年間伺いました。そうしたことも踏まえて、今後この助成についてどのように検討されていくのか、お知らせください。","respondent":"鈴木都市環境部長","answer":"項目によっては予定件数に達しているものもありますが、これまでの実績を見ると、予定件数まで事業者にしっかり使っていただきたいと思いますので。例えば今、成形板への拡充も法的には図られておりますので、国や他自治体の状況を注視しながら…","id":"exchange-056"},{"speaker":"松永副委員長","kind":"質問・要望","question":"ぜひ、こうした補助金や件数を増やしていただきたいと考えていますので、どうぞよろしくお願いします。以上で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"鈴木委員","kind":"質問","question":"周知する中身についても伺います。マイナ保険証に登録しなくても、医療にはこれまで同様かかれるのか、伺います。","respondent":"遠藤健康推進部次長","answer":"１０月２８日から受付を開始できるよう、現在、作業を進めているところです。次に、１２月２日からの国民健康保険・後期高齢者医療制度の保険証廃止および、１１月に広報紙でお知らせする予定となっております。","id":"exchange-058"},{"speaker":"鈴木委員","kind":"質問・要望","question":"も保険証廃止を強行するわけですから、このことを徹底して周知していただきたいと思っています。保険証の期限が切れる前に資格確認書が送られて、これを周知していただきたいと思うのですが、またしないのであればその理由を伺います。","respondent":"遠藤健康推進部次長","answer":"先ほど、１１月に広報等でお知らせするという形でありますけれども、そちらも含めまして、一般的な事項の一つとして、そちらも周知を行う予定です。マイナ保険証の登録取消し等についても同様に考えているところです。","id":"exchange-059"},{"speaker":"鈴木委員","kind":"質問・要望","question":"医療現場が大混乱の実態をどう受け止められているか、伺います。今からでも保険証廃止をやめるよう、国に求めてほしいと求めましたが、いかがか尋ねました。","respondent":"遠藤健康推進部次長","answer":"全国保険医団体連合会が実施した調査、それからその結果については、区で確認させていただいているところです。区といたしましては国により是正するものと考えておりますので、対応を注視していきたいと考えているところです。","id":"exchange-060"},{"speaker":"鈴木委員","kind":"質問・要望","question":"残り９人分で公約達成ということなのか伺います。これまで補助金を出して建設されたグループホームの数と、その年度についても伺います。","respondent":"寺嶋福祉部長","answer":"もともとは令和６年度までに４８名分の定員増という実施計画の指標、これに対しまして令和８年度末までに１００名分の定員増に引き上げる。施設整備費補助を受けて建設したグループホームは令和４年度に１件、こちらを活用したグループホームは、令和４年・５年度に各１件ずつで…","id":"exchange-061"},{"speaker":"鈴木委員","kind":"確認","question":"このことに対して、区としてどう捉えているのか伺います。そして、区内に戻りたいと希望している方の人数と、その受皿をどうつくるのかも伺います。","respondent":"寺嶋福祉部長","answer":"ただし、遠方のグループホームをご利用で区内を希望しているという方がいらっしゃるようでしたら、それについては整備促進が必要だと考えております。施設入所者全員に対して意向調査を行ったことがありますが、これはグループホームは対象外でありましたので…","id":"exchange-062"},{"speaker":"鈴木委員","kind":"質問・要望","question":"最も求められている知的障害、身体障害、中・重度者、また医療的ケア対象のグループホームをどう整備していくのか。そして医療的ケア者を対象としたグループホームについて、整備が必要な数は明らかになっているのか、それぞれ何人分と考えているのか伺います。","respondent":"寺嶋福祉部長","answer":"先ほど申し上げたとおり、調査は施設入所者全員に対して行いまして、１９人が区内を希望しているという回答を頂いております。現在は見込み数３１７名、うち精神障害が１２３名、このように見込んでおります。","id":"exchange-063"},{"speaker":"鈴木委員","kind":"質問・要望","question":"世田谷区のように区有地の洗い出し・活用とともに、民間物件の購入や借受け可能な土地建物の積極活用の検討も求めますが、いかがでしょうか。いかがか尋ねました。","respondent":"寺嶋福祉部長","answer":"今後の必要数、それから計画数、目標数といったものの表示の仕方も含めて検討していきたいと考えております。この辺もしっかり進めていくとともに、重度者受入れをはじめとした事業者支援についても、引き続き検討を進めてまいります。","id":"exchange-064"},{"speaker":"鈴木委員","kind":"質問・要望","question":"関係者が、地域包括支援センターとはどうあるべきなのかの認識の共有がまず必要ではないかと思いますが、いかがでしょうか。それから、委託することになるかと思うのですが、その場合、社会福祉法人など非営利の法人にするように求めますが、いかがか尋ねました。","respondent":"寺嶋福祉部長","answer":"それと、実務者レベルによる会議体等を設けて二重構造で検討を進めるなど、実効性のあるものにしていきたいと考えております。今年度第９期がスタートしたということになりまして、この中で１０期に向けて方向性を示せるように検討を進めたいと考えています。","id":"exchange-065"},{"speaker":"鈴木委員","kind":"質問・要望","question":"区民にとって安心して暮らせる地域、頼れる包括センターの設置を求めて、安藤委員に代わります。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"それと、これだけの声が寄せられているわけですから、区として測定や調査を行うべきではないでしょうか。伺います。","respondent":"鈴木都市環境部長","answer":"調査を区が行うべきではないかですが、大気環境につきましては、国が羽田空港周辺における調査を実施し、結果が公表されているところです。引き続き必要な取組の実施、区民負担の軽減を、国に対し強く求めてまいります。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問","question":"区は、国のこの調査により、羽田新ルートは資産価値に影響がないと考えているのか、伺いたいと思います。私は、この声を受けて調査が行われるべきだと思うのですけれども、調査は行われる必要がないと考えているのか伺います。","respondent":"鈴木都市環境部長","answer":"調査の結果の考察あるいは結果につきましては、実施主体の国において区民に丁寧に説明・周知が行われるべきものと考えております。資産価値に対する意見も含めて、寄せられた声は国に届けるとともに、様々な手法による区民への丁寧な周知・説明を求めてまいります。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問・要望","question":"しかし、実際には何が起きているのでしょうか。それぞれの土地所有者、借地権者、マンション区分所有者の数と、開発地区面積、見込まれる事業費と補助金額も伺います。","respondent":"鈴木都市環境部長、鴇田都市整備推進担当部長","answer":"昨年実施の区民アンケートですが、回答した区民の４４.５％が新飛行ルートによって影響を受けていると。今後も引き続き国に対し、区民への丁寧な説明・周知と、区民負担の軽減につながる取組を強く求めてまいります。 続きまして開発の面積ですけれども、北地区で約６ha、西地区で約３.５ha、南地区で約４haとなっています。総事業費、補助金額につきましては、現在、各準備組合によりまちづくり検討が行われている状況であるため…","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問","question":"おかしいと思いますけれども、いかがでしょうか。いかがか尋ねました。","respondent":"鴇田都市整備推進担当部長","answer":"各準備組合により検討されている内容の情報発信ですけれども、基本的には、情報を保持している主体である各準備組合が判断するものと考えています。委員ご指摘のとおり、準備組合に加入したくない方…","id":"exchange-070"},{"speaker":"安藤委員","kind":"質問・要望","question":"区は準備組合に是正を指導すべきではないのか、伺います。区長、いかがか尋ねました。","respondent":"鴇田都市整備推進担当部長","answer":"委員長が円滑な議事進行を求めたのにもかかわらず、再開発に反対する方々が続けて意見を述べている状況があったことは認識しています。区長に直接その実態を聞いてもらいたいという願いにつきましては、市街地再開発事業を所管しています都市環境部にて対応したいと考えています。","id":"exchange-071"},{"speaker":"安藤委員","kind":"質問・要望","question":"区長に聞いてもらいたいという思いがありますので、ぜひ応えていただきたいと、改めて求めたいと思います。都市開発課は、なぜこちらの請願、議会に請願・陳情を出すことを、カスタマーハラスメントと捉えたのか伺います。","respondent":"鴇田都市整備推進担当部長","answer":"昨年区で実施しました悪質クレームカスタマーハラスメントの状況調査と考えますが、本調査については、長時間対応を要するなど。なお、こちらは請願・陳情の対応業務そのものを否定するものではなく、もちろん請願権を否定するといったことにはつながらないものと認識しています。","id":"exchange-072"},{"speaker":"安藤委員","kind":"質問","question":"住民の暮らしと財産を守るのが区の役割だと強く申し上げて、質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-073"},{"speaker":"藤原委員","kind":"質問・要望","question":"これはどうなっているのですか。そのことについてもお伺いします。","respondent":"川島地域振興部長、柏原区長室長、鴇田都市整備推進担当部長、鈴木都市環境部長","answer":"西大井駅前の喫煙所の煙の流出対策ということになると思いますが、お答えします。現在の喫煙者数に対応するには、パーティションを設置しまして… 簡単に移設というのは、像と一緒に移設ということを考えなくてはいけませんので、どういった形ができるかというのは検討していきたいと思います。… 協議会では地権者と意見交換を実施しながら、まちの課題や将来のまちづくりの方向性といったものについて検討してまいります。… 補助第２９号線とのネットワークや…","id":"exchange-074"},{"speaker":"藤原委員","kind":"質問・要望","question":"それもよく考えて、まちづくり、駅前ということを考えてほしいと求めましたが、いかがでしょうか。ホームドアの件も、ぜひ強く要望してほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市環境部長、堀越副区長、柏原区長室長、溝口防災まちづくり部長","answer":"設置された経緯をご説明いたしますと、西大井駅は昭和５９年に建設が開始されましたが、駅舎建設につきましては。ニコン開業もしておりますので… たしか、平成３０年の９月だったと思います。西大井地区も、たしか記憶では１０ポイントぐらいの領域率が上がってきたとも認識しておりますので… 私から、花壇の件についてお答えします。それは１つ、検討の材料ではあるのですけれども、どういったところが効果的なのかというのはもう少し検討さ… 年々…","id":"exchange-075"},{"speaker":"藤原委員","kind":"質問","question":"品川区の子どもたちに伊藤博文公ということでどういうふうに教育しているのか教えてください。それだけ私たちは伊藤博文公に強い思いがあるのですけれども、いかがか尋ねました。","respondent":"米田教育次長、辻文化観光スポーツ振興部長","answer":"６年生による伊藤博文のお墓の掃除を通して、伊藤博文と伊藤小学校の関係について知り、愛校心を育てております。引き続き、地域ゆかりの人物や資源等の学習も含めまして、学校教育の充実を図ってまいります。 現在まで品川歴史館で、伊藤博文公を単独でテーマとした企画展というのは実施したことがございません。引き続き、伊藤博文公に焦点を当てた展示の可能性を探りながら、歴史や資料の研究を進めてまいりたいと考えております。","id":"exchange-076"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと福祉部、役所の人員は大丈夫ですか。国は在宅支援を求めているにもかかわらず、訪問介護の報酬が減るという、とんでもないことをやっていると思っています。","respondent":"森澤区長、新井副区長、寺嶋福祉部長","answer":"障害を抱えることもあります。そういったときにしっかりと区民の皆さんを支えられる品川区でありたいと考えていますので… 頂いたご懸念について２点、ご説明させていただければと思います。データというかエビデンスに基づいた説明を、数字だけのご説明だと味気ないので… それから、これまでもコロナ禍における業務継続支援金や今年度の居住支援手当等々、独自で支援策を打ち出してきたという経緯もあります。今後も工夫する余…","id":"exchange-077"},{"speaker":"須貝委員","kind":"質問","question":"一方、事業主は借金を増やしながら経費節減をして経営を続けていますので、区も何かしらの支援をするべきだと私は思いますが、教えてください。そして、認識していたら支援の手をやはり今は差し伸べる時期ではないかと私は思うのですが、ご答弁をお願いいたします。","respondent":"川島地域振興部長","answer":"現在の区の経済状況等の認識というようなところだと思いますが、地域経済に対する認識につきましては、引き続き厳しい状況にあると認識しています。今後の事業継続、それから持続的な成長に向けまして、経済環境の変化を踏まえた支援策が引き続き必要であると認識しています。","id":"exchange-078"},{"speaker":"須貝委員","kind":"質問","question":"そして、こんな不公平な対応でいいのでしょうか。この現状では、所得が低い人ほど物価高騰の影響が多いと私は思いますが、ご答弁をお願いいたします。","respondent":"川島地域振興部長","answer":"電気代、将来的な電気代・ガス代の削減が期待できる設備更新への助成金を提案いたしまして、１１月から実施予定としております。今後とも区内事業者の経営環境の変化に対応しまして、必要な支援を積極的に進めていきたいと考えております。","id":"exchange-079"},{"speaker":"須貝委員","kind":"意見","question":"そして、大東市では市独自の施策として、物価高騰対策給付事業として、住民基本台帳から１１万８,０００人分を対象として行っています。今はその時期ではないかと思うのですが、もう一回ご答弁をお願いいたしますとの意見を述べました。","respondent":"川島地域振興部長","answer":"委員と経済状況等の認識というのは同じでございまして、しっかりとした区としての対策ということで、今説明したとおりの事業を着実に進めていきたいと思っているところです。","id":"exchange-080"},{"speaker":"須貝委員","kind":"質問","question":"建築や修繕工事の場合は３社以上の業者から見積りを取り、より安く信用できる業者にお願いします。お答えください。","respondent":"久保田企画経営部長","answer":"私どもは、予定価格１００万円以上の発注につきましては、予定価格を公表しています。事業者等が職員から予定価格を聞き出そうとするような、いわゆる官製談合を未然に防止するということを目的として行っているといったものです。","id":"exchange-081"},{"speaker":"須貝委員","kind":"質問","question":"競争原理が働かない１社入札は、あらかじめ落札業者が決まっているようなもので、随意契約と同じではありませんか。お答えください。","respondent":"久保田企画経営部長","answer":"結果的に１社になってしまっているですけれども、いろいろと積算・見積り等をした結果、辞退されているといったところです。私どもとしましては、入札といった制度をきちんと執行しておりまして、そういった指摘は当たらないものと考えているところです。","id":"exchange-082"},{"speaker":"須貝委員","kind":"質問","question":"だって、もともとやれないのではないですか。お答えください。","respondent":"久保田企画経営部長","answer":"公契約上、大事な視点だと思ってありますので、そのようなことをする考えというものは私どものほうではございません。設定しているといったところでございまして、こういったことにつきましても、適正な設定をして我々は対応しているです。","id":"exchange-083"},{"speaker":"須貝委員","kind":"質問","question":"そういう例が多々あるのですか。そして毎回毎回、きちんとした入札に対しても、後で適正な評価をしているのか尋ねました。","respondent":"久保田企画経営部長","answer":"私は質の低下というようなお答えはしてございませんので、きちんと公平性・透明性を担保していきたいということをご答弁させていただいたです。辞退して、事業者にそういった経済活動をする環境・機会を与えることで、公契約の透明性確保を守っていくといったところです。","id":"exchange-084"},{"speaker":"須貝委員","kind":"質問","question":"これが事実なら、何もしない、仕事をしないで支払いを受けていることになりますが、もしこれが本当ならおかしいと思うのですが、どうですか。お答えください。","respondent":"久保田企画経営部長","answer":"そうしたことを通しながら、工事の実態について把握しているといったところです。今、委員からご指摘のようなこと、ＪＶの筆頭会社だけで仕事をしているというような事実はないというものです。","id":"exchange-085"},{"speaker":"須貝委員","kind":"意見","question":"ここの見解では、談合疑惑感度といって、各工事の落札率が９５％以上になった工事は談合の疑いが極めて強い。すぐにでもこれは改善すべき数値ではないかと私は思うのですが、年間三十億円、その辺についてご見解を説明を求めました。","respondent":"久保田企画経営部長","answer":"結果として落札率が９５％等になってありますので、また規定等に基づいてやってありますので、そういった談合というものはございません。品川区として公平公正な契約事務の手続を進めているところですので、そういったところを改善するといった予定もございません。","id":"exchange-086"},{"speaker":"須貝委員","kind":"質問","question":"これは恐らく、民間でやったらどうなのですかね。どうか尋ねました。","respondent":"久保田企画経営部長","answer":"きちんとした手続を踏まえて入札をして、こういった結果が出てありますので、今おっしゃったような事例とは全く異なるものと認識しています。手続上も、我々はきちんとした適正な手続を踏んで行ってありますので、改善する予定はございません。","id":"exchange-087"},{"speaker":"松本委員","kind":"質問","question":"最初に、事務事業評価について伺います。今後どういうふうに事務事業評価を行っていくのか、お示しいただいていますが、今後どういう方向性を持っていらっしゃるのか伺いたいと思います。","respondent":"久保田企画経営部長","answer":"事務事業評価を行うことによって、各事業の検証や見直し、改善を行いまして、質の高い行財政運営につなげていきたいと考えているところです。令和６年度も２０億円の財源捻出を目標にして事務事業評価を進めていきまして…","id":"exchange-088"},{"speaker":"松本委員","kind":"提案","question":"果たして高齢者の安否確認、安全確認との関係で有効と言えるのか、伺いたいと思います。安否確認という成果を得るためには、同じ高齢者安否確認事業の中にある高齢者見守りネットワーク事業のほうが効率的で、この点はいかがか尋ねました。","respondent":"寺嶋福祉部長","answer":"品川区で実施しております高齢者安否確認事業につきましては、それからその後、お話がありました高齢者見守りネットワークの３事業を展開しています。敬老の日に合わせて９月近くに実施するということもありますので…","id":"exchange-089"},{"speaker":"松本委員","kind":"質問","question":"そこで伺いたいのですが、女性委員の割合が低い審議会を、低いほうから３つ教えてください。都内には４０％をクリアしている自治体もありますが、そうした自治体でなぜ達成できたのかの分析は行われているのか尋ねました。","respondent":"柏原区長室長","answer":"ということで、トータルとしては１０年間の計画ということで目標を考えているといったところです。行動計画の部分の見直しも今図っているところでございまして、この目標値についても、検討しているといったところになってあります。","id":"exchange-090"},{"speaker":"松本委員","kind":"提案","question":"いかんせん２回目ですので、区として方向性を考えているところがあれば、お伺いできればと思います。事務事業評価が始まる前にも提案したところではあるのですけれども、この事務事業評価シートと、最後にこの点をお伺いできればと思いますとの意見を述べました。","respondent":"久保田企画経営部長","answer":"記載内容に類似する点が多いということは認識しておりまして、事務の効率化の視点も含めまして、検証が必要であると考えておるところです。いろいろと課題が多いと考えておりますので、議会のご意見もお伺いしながら、引き続き検討していきたいと考えているところです。","id":"exchange-091"},{"speaker":"松本委員","kind":"質問・要望","question":"伺います。そこで、区として各町会・自治会と連携して、各防火水槽の現状の確認、見回りを行ってはいかがかと思いますが、どうか尋ねました。","respondent":"滝澤災害対策担当部長","answer":"協力して消防水利の確保及び消防力の強化に努める」と定めておりまして、都区間の役割分担を含めて消防と連携した対応を定めているところであります。地域防災力の向上にもつながりますので、都や消防と協力しながら地域の声を聞き、区として必要な対応をしていきたいと考えます。","id":"exchange-092","title":"町会・自治会支援"},{"speaker":"松本委員","kind":"質問","question":"戦前に設置されたものや、あと老朽化が進んでいるものもあるかと思うのですが、区内の防火水槽の耐震化率はどうなっているのでしょうか。区内１,８００基、把握できているもので結構ですけれども、設置から５０年を経過したものというのはどのくらいあるのか尋ねました。","respondent":"滝澤災害対策担当部長","answer":"引き続き、区としましては、公園などの改修に合わせて、区の管理する防火水槽の更新などを実施してまいります。木造密集地域における防災広場の整備に取り組んでおり、その中で防火水槽の設置を実施しているということで、実績はございません。","id":"exchange-093"},{"speaker":"松本委員","kind":"質問・要望","question":"地域の方たちが区に要望させていただいているのですけれども、それに対して区は、「難しいです」というご回答でした。区も防火水槽、やはりもう少し何かしら地域の方たちの要望に応えていく姿勢があってよいのではないかと思いますが、この点をお願いいたします。","respondent":"滝澤災害対策担当部長","answer":"防火水槽の新設や増設を行う考えはございませんが、区としては、必要に応じて消防と連携した対応を実施してまいりたいと考えているところです。このほか、東京消防庁が管理している防火水槽も複数設置されておりますので、これらの防火水槽の利用について…","id":"exchange-094"},{"speaker":"松本委員","kind":"質問","question":"整備方針、整備計画を立ててほしいと求めましたが、いかがでしょうか。[時間切れにより答弁なし]。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-095"},{"speaker":"まつざわ委員","kind":"提案","question":"今回の決算特別委員会におきまして、区民の皆様や各種団体などから頂きました声をまとめ、会派の委員より指摘や政策提案を致しました。この指摘や提案が品川区の令和７年度予算事務事業に反映され、区政運営が区民福祉の一層の向上に寄与することを求めとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-096"},{"speaker":"若林委員","kind":"提案","question":"未知の感染症などから区民の生命と健康を守るため、堅実に、かつ速やかな体制の構築を冒頭に求めておきたいと思います。会派からの意見・要望を真摯に受け止められ、今後の区政運営および来年度予算に反映されるよう求め、意見表明といたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-097"},{"speaker":"大倉委員","kind":"提案","question":"執行率が９５％となり、普通会計の実質収支も約５８億円を超える黒字となっており、健全財政を維持していることを確認いたしました。学校教育、各課題への積極的な取組を確実に進めるとともに…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-098"},{"speaker":"のだて委員","kind":"質問・要望","question":"平和首長会議の要請書と同じ立場に立ち、核兵器禁止条約の締約国会議に少なくともオブザーバー参加し、条約を批准することを国に求めるべきです。以上、区民の暮らしを支える区政への転換を求めて意見表明とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-099"},{"speaker":"須貝委員","kind":"質問・要望","question":"そして、ロシアのウクライナ侵攻や中東紛争など、多くの死傷者を出し、エネルギーと食糧危機をもたらす戦いはやめるべきです。以上で、品川改革連合の意見表明を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-100"},{"speaker":"せらく委員","kind":"提案","question":"子育て支援では第２子以降の産前産後の家族支援や教育費の支援、子どもの事故予防の観点からも、様々な提案・要望をさせていただきました。事業に反映していただくよう要望するとともに、さらなる区民サービスの向上が図られることを求め…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-101"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/285407?Template=document&Id=6861#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":102437,"voices":234}},{"id":"r06-20241024-10","meetingId":"r06-cm10","date":"2024年10月24日","dateIso":"2024-10-24","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時５０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"令和６年陳情第３８号、オンラインでの陳情・請願の受付に関する陳情","agenda":"令和６年陳情第３８号、オンラインでの陳情・請願の受付に関する陳情","exchanges":[{"speaker":"西村委員","kind":"質問","question":"いただいた陳情の中に書いているものでもありますが、オンラインでの陳情・請願の受付に関する他自治体の状況ですとか、課題などを事務局のほうで把握されていたら、教えていただけますか。","respondent":"大澤区議会事務局長","answer":"オンライン化をしますと、これらを効率的かつ適切に執り行うために、対応の見直しも必要になるのではないかと考えております。お話をお伺いして、審査についてのご説明などを行った上で、このようなことが現在の課題として考えられるのではないかと認識しています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"ふだんあまり区政や区議会に関心をなかなか持ちにくい世代からの要望ということで、私は採択して、強く要望するということでもありますので。〔「質疑ですか」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"意見","question":"共産党はそういう意見なのですけれども、皆さんほかに何かありましたら、出してもらいたいですし、どうぞお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"こんの委員","kind":"確認","question":"その辺も伺いたいと思いますし、理由の２番目で、その対応をされたことがあるのか。その辺も３点伺いたいと思いますが、現状が分かりましたら、お願いします。","respondent":"大澤区議会事務局長","answer":"現在の対面での対応ですけれども、事務局でかなり丁寧に対応していまして、丁寧に対応しています。郵送での陳情の提出も、来られないというわけでもないのですが、人によっては郵送での受付の場合もあります。","id":"exchange-004"},{"speaker":"こんの委員","kind":"質問・要望","question":"オンライン化、効率化といったところが求められている内容だと思うのですが、そうした陳情の中身というのも少し理解できるかという感じはいたします。ただ、こうしたことについて調査研究、これから必要な課題ではあるのかと思うところです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"今お話をいろいろお聞きしましたけれども、内容で提出されるわけですから、事務局の方にお話をする。意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"西村委員","kind":"質問・要望","question":"一方で、事務局より課題を伺いましたけれども、セキュリティなど、丁寧な準備には時間がかかるということが分かります。文章の修正や訂正を必要とされることもありまして、現在も来庁いただいた際に修正を依頼することがままある様子を伺っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"こんの委員","kind":"質問・要望","question":"どういう形でやるのがいいのかといったことも、品川ナイズのオンラインのやり方というのをもっと研究しなければいけない。このように感じることから、その時間も必要なので、継続させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"松永委員","kind":"確認","question":"本人確認をする方法や、議員の本人確認をする方法、様々な課題がまだあると考えています。より一層、しっかりとした形で進めていただければと考えていますので、この陳情については継続でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"安藤委員","kind":"意見","question":"これを採択して、オンラインを進めていこうという議会の意思をまず定めて、その上で調査研究というのを行われたほうがいいのではないかと。そうすべきだと私は思いますので、採択を主張したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"私は、先ほど述べましたけれども、やはり基本的には、請願・陳情に対しては、本人とじっくり話し合う、対面するということが基本だと考えています。品川区議会には議会改革検討会議がありますから、そこで十分検討されるというのも一案だと思いますので、私も今回継続としますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"}]},{"id":"topic-02","title":"令和６年陳情第４５号、区民の民意を議会運営委員会に反映させる陳情","agenda":"令和６年陳情第４５号、区民の民意を議会運営委員会に反映させる陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"現在の議会運営委員会の構成について、規定としてはどうなっているのか、事務局に伺いたいと思います。陳情にもあるのですけれども、前回の議運でも、実際に発言が認められた委員外議員は、どのような規定なのかも説明を求めました。","respondent":"大澤区議会事務局長","answer":"議会運営委員会の委員の定数は１３人で、委員選出基準は、会派に所属する議員の中から比例配分方式により委員を選出するとなっています。品川区議会会議規則第１０９条で、その出席を求めて説明又は意見を聞くことができる」、その許否を決める」という規定になってあります。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"確認","question":"今おっしゃっていただいた申し合わせ確認事項に定数１３人ということで、会派に所属する議員の中から比例配分方式によって委員を選出するとある。規定を修正し、少なくとも全会派から委員を選出すると規定する必要があるのではないかと思うのですけれども、これは皆さんにも伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"２人ということならば、２人ずつ組めば、そこに一つの大きな壁があるというのは非常に残念だと思います。どうするか、こちらからどうこうとは言えませんけれども、私も２人以上というのはやっていっていいのではないかと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いしたいと思います。公平性を当てはめることは必ずしも適切とは言えないのではないかと思いますので、これらのことを踏まえて、不採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"塚本委員","kind":"意見","question":"現状今やられている１３の定数の中で、会派ごとに比例配分方式で進めていくということが、我々としては最も公平なのだろうと思います。そういうときにどうするのだという話で、現行のルールで運営していくのが望ましいと思いますので、不採択でとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"松永委員","kind":"確認","question":"議会運営委員会のメンバーについては、先ほどご説明があったように、申し合わせ確認事項にもありますとおり、メンバーは１３人で決められております。〔「会派の差別じゃないの」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問","question":"委員外議員として発言できる機会を保障すべきなので、前回議運でも認められたように、今後も申出があれば認めるようにすべきだと思います。今後そういったところを進めていく、民意を反映させていくという点でも重要だと思いますので、採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"須貝委員","kind":"意見","question":"そこでやはり私は議論または検討しても、決して問題になる話ではないと思うので、非常に皆さんの意見を聞いていて、残念です。私としては、先ほど申し上げましたけれども、検討してほしいということで、継続でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"須貝委員","kind":"意見","question":"採択不採択という、本日結論を出すという話に今決まったので、私としては、それならば、採択でお願いしたいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"}]},{"id":"topic-03","title":"令和６年陳情第４６号、議会改革提案取り下げを要求する陳情","agenda":"令和６年陳情第４６号、議会改革提案取り下げを要求する陳情","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"自民党から、説明をさせていただきたいと発言がありましたけれども、本日は修正案は出されるのでしょうか。伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"そもそも時間制限そのものを取り下げるべきだと思うのですけれども、自民党の今のお考えがあれば、伺いたいと思います。〔「陳情審査じゃないでしょう」「今日は協議しない」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"西村委員","kind":"質問","question":"そのことも含めて、皆さんの意見を改めて伺いながら、説明する場を設けたいと思っていますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"安藤委員","kind":"提案","question":"こういう陳情が出ているものですから、時間制限をかける必要性がないので、自民党は今この場では表明しないということでした。もう少し伺いたいのですけれども、所管する委員会の議員は討論できないものとするという項目が提案されていましたけれども、伺えればと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"西村委員","kind":"質問","question":"先ほどのご質問ですけれども、２分を目安にという点は、あくまで例示だと申し上げています。これも含めまして、しっかりと説明する場を設けてと申し上げていますので、これも含めて改めて皆さんのご意見を伺いたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"安藤委員","kind":"提案","question":"提案を出すその必要性すら理解できないというか、この陳情にもあります、所管する委員会の議員は討論できないものとするという提案がありました。前回、そこについては何も修正がなかったのですけれども、それは修正しないという考えなのですかというのを聞いたのですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"西村委員","kind":"意見","question":"すみません。前回申し上げたことの繰り返しになるのですけれども、説明の場をと申し上げていますので、そのようにご理解ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"須貝委員","kind":"意見","question":"前に、議員に対する決議案を出しましたけれども、それでもやはり３か月４か月かかるのです、それを作るには。やはりきちんと案が出たら、皆さんで様々な議論をすればいいかと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"西村委員","kind":"質問・要望","question":"９月１８日の議会運営委員会で、自民党から再度説明をする、皆さんの意見を伺うと申し上げました。ですが、これから審議する内容でありますので、継続でお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"塚本委員","kind":"質問","question":"これまで何回かこの議運の場で取り上げられてきて、現在は、今、自民党からお話があったとおり、説明、また、いろいろ皆さんの意見を伺いながら進めている最中ということでありますので、継続で。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"安藤委員","kind":"提案","question":"本日結論を出すで、これは採択すべきだと思うのですけれども、その理由ですが、この陳情は、自民党の議会改革なる提案を取り下げてほしいと。その上、なぜこの提案を出さなくてはいけないのかという説明も全くないのですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"須貝委員","kind":"提案","question":"先ほども申し上げましたが、自民党・無所属の会からは、現在、議会改革の提案に対して、検討中というお話を何度も聞いております。したがって、今回に関しては、継続ということでお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"}]},{"id":"topic-04","title":"令和６年第３回定例会","agenda":"令和６年第３回定例会","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"固定資産税・都市計画税の軽減措置の継続を求める意見書についてご説明いたします。本意見書は、東京都が現在実施している固定資産税および都市計画税に係る軽減措置を令和７年度以降も継続するよう求めるものであります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"}]},{"id":"topic-05","title":"議事日程(4)および追加議事日程","agenda":"議事日程(4)および追加議事日程","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"採決時の起立が難しいため、賛成は挙手によるものとしていただきたいということ、以上の３点をご了承いただけないでしょうか。ご検討をお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"}]},{"id":"topic-06","title":"広報会議からの報告事項","agenda":"広報会議からの報告事項","exchanges":[{"speaker":"せお委員","kind":"質問","question":"７問ほどで、区議会だよりで取り上げてほしい情報、リニューアルする際に改善してほしい点などをお伺いします。各議員のメールにも、アンケートのＵＲＬやＱＲコードなどをお送りしますので、ぜひ各議員においてもＳＮＳ等での周知を。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759442?Template=document&Id=6845#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":22612,"voices":119}},{"id":"r06-20241106-6","meetingId":"r06-cm11","date":"2024年11月6日","dateIso":"2024-11-06","committee":"区民委員会","time":"午後 １時００分～午後 ２時２５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"第２４回 品川区中学生の主張大会","agenda":"第２４回 品川区中学生の主張大会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"各中学校というか後期課程のほうから代表者が選出されるまでの過程について少し伺いたいのですが、どのように代表者というのはそれぞれの学校で選出されていくのかというのをお伺いするのと、何名いらっしゃってどのような方に依頼しているのか伺いたいと思います。","respondent":"宮澤地域活動課長","answer":"１名、学年も学校によってはまちまちという形になっておりまして、そこは学校の判断にお任せしています。学識経験者の方１名、地区委員連合会から地区の会長を２名、計５名で審査する形です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"それを大人が受け止めてリアクションを返して、自分たちが出した意見が、この目的達成のために非常に重要なのではないかなと私は考えています。この場をそういったものにしていっていただきたいのですが、中学生のこの主張を通して、あれば例えばどんなものがあったのか伺いたいと思います。","respondent":"宮澤地域活動課長","answer":"目的にしております「地域事業の企画・実施に資する」です。その中で、防災をテーマにするといったバスハイクとかといったところの企画にはつながっているのかなと感じているところです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"意見","question":"子どもの権利条約にもありますように、子どもとは１８歳までの子どもですが、全ての子どもに関わる施策というのは子どもの声を聞いて実施していくということの重要性がうたわれていますが、そうした立場でこの中学生の主張大会もさらに発展させていっていただければなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"おぎの委員","kind":"質問","question":"これは今まで２４回やっていますが毎回自由だったのかということと、安藤委員のほうが審査員については５名ということでお聞きいただいて、どういった内容で審査されているのかという部分をお聞かせほしいと求めました。","respondent":"宮澤地域活動課長","answer":"直近１０年近くはテーマを自由とさせていただいて、１回目からは、様々な中学生の視点でテーマをとらえて発表していくです。大きく２つございまして、伝え方というところを大きな２つのテーマとして、基準として審査していただきます。","id":"exchange-004"},{"speaker":"おぎの委員","kind":"質問・要望","question":"ずっと各学校代表１名ですけれども、これだけではなく、また機会を見て検討していただけたらいいなと思います。最後は要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問","question":"いわゆるこれは中学生の主張大会ですから主張をするということですが、今どういうふうに、そういうやりがいも出てくるのかなと思うのです。この目的を達成するには非常にいいのかなと思うのだけれど、その辺の何か仕組みづくりみたいなものはあるのかどうか説明を求めました。","respondent":"宮澤地域活動課長","answer":"主張発表の進め方、本当に中学生がどういうところに気づいて、どういう考えを持っているのかということの発表が大きいところかなと考えています。特に当日会場で行いますけれども、より多くの人に中学生の理解を進めるという点では…","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"この主張大会が成功するようにしていただきたいなと、これは要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"吉田副委員長","kind":"質問","question":"すみません、先ほどの審査基準というのは、あくまでこの主張大会での審査基準ということですよね。各学校で選ばれて出てくるときの審査基準というのか選出基準というのでしょうか、それとも、何かそういうテーマ設定などはあるのか尋ねました。","respondent":"宮澤地域活動課長","answer":"審査基準は、この当日の５名の審査員に共通して持ってもらっている審査基準です。学校のほうにお伺いすると、夏休みの宿題として取り組んでいる学校等もあると聞いております。","id":"exchange-008"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"要望にとどめますけれど、文字では読んでいますが、伝え方となると少し違うかなと思って楽しみにしております。これは要望にとどめます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"}]},{"id":"topic-02","title":"喫煙状況実態調査の結果および今後の対策方針","agenda":"喫煙状況実態調査の結果および今後の対策方針","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"大崎広小路駅のこの理由を教えてもらいたいのと、こちらの理由を併せて教えてもらいたいのと、何が変わるのだろうかというのが少しよく分からない点があるので説明を求めました。","respondent":"河合生活安全担当課長","answer":"先ほどご説明しましたが、駅前に設置されている喫煙所から道路上にはみ出しているものをカウントしておりまして、そこが上乗せになっております。規制強化で訴えて、そこで規制が守られないようであれば、また規制強化というところで段階規制としての方向が妥当だと考えておりま…","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"パブリックコメントの目的を改めて伺いたいのと、それと、町会・自治会への意見聴取の結果というのはどのようにこの方針に反映されるのでしょうか。それともその意見を踏まえてパブリックコメントにかける内容を変えるというような感じなのでしょうか、そこら辺も伺います。","respondent":"河合生活安全担当課長","answer":"個別具体的に今、いろいろ進めているのですけれども、効果というのは助成率のほうが改善されると見込まれるのかなという見込みはあります。町会長会議のご意見をいただいて条例改正の規制の度合いですとか…","id":"exchange-011"},{"speaker":"おぎの委員","kind":"質問","question":"実際に今までこの過料を払った方とか、そういう実態はどうなっているのでしょうか、お願いします。","respondent":"河合生活安全担当課長","answer":"今後またそれが守られないと規制強化があるかもしれないというところでやはり、いろいろ改めて考えていただける機会になるかなと認識しております。やはり最近いろいろ苦情がありますので、そういったところで個別的に丁寧に対応する形で…","id":"exchange-012"},{"speaker":"おぎの委員","kind":"意見","question":"１３４件と思ったよりあったなと思うのですが、吸う人の権利といいますか、そういった方々の場所もうまく確保できるようにとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"区民の声を集約した形で進めてほしいと求めましたが、それがどのぐらいの間隔でこの議題が知らされるのかというのが確認したいことの１点。もう一点がパブリックコメントについてなのですが、どういうふうな媒体で行われるのか、そこについてお聞きできればと思います。","respondent":"河合生活安全担当課長","answer":"その場で意見聴取だけではなく、そこでご説明した上でいろいろ町会でもんでいただいたりする必要もあるのかなと思いますので。資料のほうは、あと、各センター等にもそれについての関係の資料を確認できるような形で実施する予定です。","id":"exchange-014"},{"speaker":"ゆきた委員","kind":"確認","question":"町会・自治会長の件に関して確認させていただきました。そういった工夫も講じていただきながら進めてほしいと求めましたが、この辺についてもう一度、何かあればお聞きできればと思います。","respondent":"河合生活安全担当課長","answer":"アプローチに関しては、ＳＮＳとか以外でもというところでなかなか、考えられるのはこちらのほうでも、生活安全サポート隊のマイク広報とかといったところで周知はいろいろ行っておりますので、そういったところで効果があるようなところを少し検討していきたいなとは思います。","id":"exchange-015"},{"speaker":"石田（し）委員","kind":"質問","question":"区の方針は、禁煙なのですか、分煙なのですか。教えていただけますか。","respondent":"河合生活安全担当課長","answer":"やはり、吸う人、吸わない人、双方が納得できる対策というところで、やはり健康面等がありますけれども、喫煙者、喫煙率が下がってもいますので、分煙という形で、妥当なところを選択します。","id":"exchange-016"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"区が何かを区民に求めるときに、大体この２つをいつも言うのですが、基本的にはどちらかというと自分からその情報を取りに行くときしか見ないのです。僕はこういった本当に区民の皆さんに何かを求めるのであれば、やはり、こういうことを品川区はやりますよという広告を打つべきだと思うのです。","respondent":"河合生活安全担当課長","answer":"喫煙している苦情の対応とか、改めて実態調査というところではもう既に、そこはしっかり酌んでいきたいと考えております。こちらのほうは、委員ご指摘のところで検討と、あと、戦略広報課とも話し合いながら、そういったところも検討していきたいと考えています。","id":"exchange-017"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"なので、ぜひそこは前向きに取り組んでいただいて、やはり時代に合った広報の在り方というのは、ぜひ進めていっていただきたいなと思います。これは要望で終わりますけれど、みんながハッピーになれる、そういった政策をさらに進めていってほしいと求めましたので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"藤原委員","kind":"質問・要望","question":"３０人以上いるではないですかと言ったときに、何言っているのですか、きちんと現場を確認して答弁しているのだとおっしゃいましたよね。それについていかがか尋ねました。","respondent":"河合生活安全担当課長","answer":"喫煙所をパーティションで設置して、そこは継続して対策は講じて、年度内にパーティションがしっかり設置されれば。やはり一時的に２５名とかになったりすることもありますが、基本は２０名以下で収まっていますので、煙のリスク等も防止できるという判断です。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問・要望","question":"どうでしょうか。重たいことをここで要望、ぜひその辺も考えていっていただきたいと思うのですが、いかがか尋ねました。","respondent":"河合生活安全担当課長","answer":"実際、あとコスト面で設置に大体２,０００万円から３,０００万円、ランニングコストも年間２００万円以上かかるというところがありますので。これが一番効果があるというふうに、生活安全担当のほうでは判断しておりますので、そういった方向で決めております。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問・要望","question":"投資対効果のお話が出るならば、たばこ税で３０億円上がっているのだから、２,０００万円いいではないですか。たばこの中には入っているわけですから、何種類も作っているではないですか、うちわもボールペンもシールもしなぼうも。","respondent":"河合生活安全担当課長","answer":"こちらの主導という形ではないと、寄贈いただくというところでありますので、そこは調整しながら検討していきたいとは思います。","id":"exchange-021"},{"speaker":"せお委員","kind":"質問・要望","question":"それで、細かいことになってしまうのですが、今、検討している規制強化の骨子の中の今後のところで私有地とあるではないですか。そういったところの、そこに住んでいる方たちのご意見とかをご存じでしたら教えていただきたいということを、まずお願いします。","respondent":"河合生活安全担当課長","answer":"やはり私有地ですので、今回の公共の場所という形にはならないので、やはり配慮義務として、少し丁寧に対応していくという形になるかなです。そういったものを見て、そういうところもないと思いますので、やはりバランスを見ながら喫煙の整備は進めていきたいと考えております。","id":"exchange-022"},{"speaker":"せお委員","kind":"質問","question":"看板とかもそうですよね、もう、何々禁止みたいなところで。なので、少し社会が明るくなるような、そういった周知の仕方といったところとか、何か考えていることがあれば、すみません、説明を求めました。","respondent":"河合生活安全担当課長","answer":"直接的な指導、駄目ですよという指導も含め、そういったところは喫煙されている方々に直接お伝えできるように検討しております。表示物のほうも、貼って効果がある部分についてしっかり検討した上で貼付していく方向でやっていきたいと考えております。","id":"exchange-023"},{"speaker":"おぎの委員","kind":"質問","question":"ボックス型というのですか、中の状態が分からないから入って吸うのが怖いのか何なのか、あの外に出て吸ってしまっているのです。お願いします。","respondent":"河合生活安全担当課長","answer":"今考えているのは、１か所を少し下のほうを開けておいてというような形で逃げられるような形にするなど、そういった安全面のほうも検討しております。安全面を心配されている方だけではないかなとは思います。","id":"exchange-024"}]},{"id":"topic-03","title":"「エシカル消費イベントｉｎしながわ」の開催","agenda":"「エシカル消費イベントｉｎしながわ」の開催","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"エコとか地球環境ということですので、最終目的といいますか、環境課との連携についてはどういうふうになっているのか。気候危機対策とかそういうところとも密接につながる事業にしていったほうがいいと思うのですが、そこら辺はどうでしょうか、伺いたいと思います。","respondent":"小林地域産業振興課長","answer":"今回、環境課ともいろいろ相談というか、どういうところに出店いただくかというところでもいろいろアイデアというかご紹介もいただいたところです。これは１１月１７日のイベント開催ですけれども、フードロス…","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"いろいろ打合せもしているということですけれども、相乗効果といいますか、やはり日々の生活とか消費が環境にどうつながっているかということは非常に大事な観点だと思いますので、さらにこれから連携などを強めていっていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"この左側の、品川の品をくにょくにょとやったような、初めて見たのですがこれは何のマークか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"こちらのチラシの左上にあるのは、そちらを冠につけさせていただいています。情報発信をしてまいります。","id":"exchange-027"},{"speaker":"藤原委員","kind":"確認","question":"最後に１点だけ伺いたいのですが、品川区においては、お膳立てしてそれで終わりですか。どういう効果がありましたとか、どういうふうになりましたみたいなことというのは、企業同士とかで確認はしていくのか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"そういったところでのつなぎを継続して区としてはフォローしていって、そういったものは蓄積していこうというふうには考えているところですので、フォローしますといったところです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"この景況報告会というのをやったのかというのと、あと、この調査に所管課としてはどのように関わっているのかというのを伺いたいと思います。","respondent":"小林地域産業振興課長","answer":"こういうデータについて、実際にこれが前期とどう違ってくるか、我々内部でまずきちんと理解し把握するための報告会になっております。あるいは補正予算、今回もちょうど補正予算を提出したところですけれども、そういうところの施策の活用などに活かしています。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"６月１０日の区民委員会で、私はぜひ区民委員会で定期的に報告してもらいたいと要望し、地域の産業の実態と。区としては、正副委員長から求められた場合は報告するという考えがあるのでしょうか、伺いたいと思います。","respondent":"小林地域産業振興課長","answer":"例えば補正予算の説明ですとか、そういうところに活用しながらご報告というのですか、一部使えるような形にもしております。一方で、もう一つ、委員会の中でどういうふうに対応していくかというところにつきましては、議会の対応に従うところです。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"具体化していただきたいのが、この景況調査、四半期ごとに出しています。報告会もやっているわけですから、その内容も報告していただきたいというふうに思うのですけれども、正副委員長、いかがか尋ねました。","respondent":"高橋（伸）委員長","answer":"以前もそういったお話をいただきました。改めて、今日は持ち帰りということでいただければと思いますので、よろしくお願いいたします。","id":"exchange-031"},{"speaker":"安藤委員","kind":"意見","question":"ぜひ検討してもらいたいのですが、この委員会に何を報告してもらうかというのは、やはり委員会ごとで検討して決めることだと思いますので、ぜひ、区民委員会として主体的な判断ということで、ぜひ具体化していただければ大変ありがたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/332921?Template=document&Id=6869#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":27727,"voices":90}},{"id":"r06-20241106-7","meetingId":"r06-cm11","date":"2024年11月6日","dateIso":"2024-11-06","committee":"厚生委員会","time":"午後 １時００分～午後 ２時０４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"指定管理者候補者（予定者）の選定","agenda":"指定管理者候補者（予定者）の選定","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"今回は建物１と建物２の高齢者の施設ということなのですけれども、この中でデイサービスはないのか、その点も伺いたいと思います。それの日程というか、これからの公募とかはどんなスケジュールになるのか、その点も教えていただけたらと思います。","respondent":"東野福祉計画課長、佐藤障害者施策推進課長、菅野高齢者福祉課長","answer":"こうほうえんの法人の概要ですが、鳥取県と東京都で事業を展開している事業者で、東京都におきましては、都内５か所で複合施設の運営をしております… 条例を改正した後に候補者の公募等を行ってまいる予定で、令和９年の、先ほど申し上げたようなところで予定しています。 １点、答弁漏れがございました。デイサービスですが、こちらにつきましては、特別養護老人ホーム、ショートステイなどはありますけれども… ちょっと補足します。この施設においては…","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"それからあと、指定管理料がどれくらい見込まれているのか。その点についても伺いたいと思います。","respondent":"東野福祉計画課長","answer":"現在、今月中旬には品川区中高層建築物の建築に係る紛争の予防と調整に関する条例に基づく説明会などを行う予定となっております。全体工事費等につきましてはまだ出ていない状況でして、それに伴う補助金につきましてもまだこれからということでこの委員会では報告します。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"整備率が１.５％以下のところは割増しとかとなっているので、指定管理料はおおよそどれくらいの見込みなのかということも先ほど伺ったので、その点も教えていただけたらと思います。","respondent":"東野福祉計画課長","answer":"工事費等の算定によりましてその辺も変わってきますので、まだ見込額、はっきりした金額は出ておりません。それから指定管理料につきましても、これから法人のほうとの協議などもありますので、こちらにつきましてもまだ算出はされていない状況です。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問","question":"公募要項の１０ページに（６）その他というところがありまして、社会福祉法人等による利用者負担額軽減制度を利用することになるのでしょうか。ほかの施設の状況と併せて、この施設がこれを利用することになるのか、その点について伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"段階に応じて４分の１を軽減するというような制度はありますので、今回においても同じような形で、この制度を利用する方がいらっしゃったらお願いしますということで公募要項には記載しています。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"あまり記憶になかったのですけれども、それは見落としていたのか、そこら辺のところは状況を教えていただけたらなと思います。","respondent":"菅野高齢者福祉課長","answer":"この制度について、区内の社会福祉法人、対象者がいる場合には使っていただいていると認識しております。やっていただいているということで、委員おっしゃったように、福栄会とかそういったところも活用していただいてはおります。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問","question":"「鳥取県にある本部との連携が図られており、新たな課題への取り組みというのは具体的にどういうことなのか、その点についても伺えたらと思います。それから、ここの施設の人員体制がどの程度になるのか、その点についても伺いたいと思います。","respondent":"東野福祉計画課長","answer":"ペットを使って何かできないかとか、ペット療法というのですか、そういうような提案も探ってみたいというようなお話がございました。人員体制ですが、小規模多機能型居宅介護が１４人体制ということで、手厚い人員体制をとっていくということでのご報告をいただいております。","id":"exchange-006"},{"speaker":"ひがし委員","kind":"提案","question":"「看取り１００％」という字が書いてあって、あと、事業者Ｇとこの点差が出たのはどういうところなのかなというところも併せて伺えればと思います。今回９者からの応募があったということで、その点について何か新たな取組等、工夫されたところがあれば、その点も説明を求めました。","respondent":"東野福祉計画課長","answer":"それから、９者来ていただいたですが、事前に区内の法人には声かけをさせていただきました。品川区で取り組んでいるウェルビーイングに資する施設というところで、集まっていただけたのかなと考えています。","id":"exchange-007"},{"speaker":"ひがし委員","kind":"確認","question":"今、区内の事業者・法人にお声がけということだったのですけれども、区内以外の方からもこの事業に手を挙げられていたのかという点を最後に確認だけしておきます。","respondent":"東野福祉計画課長","answer":"区内の事業者のほか、区外のほうがこの９者の中、実は多かったものですから、区外・区内ということで言葉遣いをさせていただきました。区内の事業者につきましては３者、区外が６者だったということになります。","id":"exchange-008"},{"speaker":"やなぎさわ委員","kind":"質問","question":"財務状況のことでお伺いしたいのですけれども、財務評価のところで、９者のうちの６者が借入金に対しての懸念があるようなコメントがあります。借入れの懸念があるというような記載があるところも２４点だったりして、この点はどういう評価というか、いかがか尋ねました。","respondent":"東野福祉計画課長","answer":"財務状況につきましては、公認会計士によります財務状況分析を行っておりまして、７ページをご覧いただくと、その点数的なところも出てあります。財務状況について特筆している部分としてこちらの評価のところに記載があるものですので…","id":"exchange-009"},{"speaker":"やなぎさわ委員","kind":"質問","question":"公認会計士の方の分析の評価ということですけれども、その中において、４０点満点ということですが、これぐらいが経営を任せられる最低基準の点数だみたいな、そういったものは設けているのか尋ねました。","respondent":"東野福祉計画課長","answer":"経営分析では、Ａ、Ｂ、Ｃ、Ｄ、Ｅという評価を行います。ですから、こちらの点数にもそれなりの評価が表れているというふうに見ていただければと思います。","id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"意見","question":"８年後もしっかり運営ができるというところを選定しなくてはいけないということを考えれば、財務状況は非常に大事かなと考えております。４００点満点のうちの４０点が財務状況というよりは、そういったことは、受け止めがあればとの意見を述べました。","respondent":"東野福祉計画課長","answer":"先ほどお話ししたとおり、社会福祉法人、コロナ禍の影響もございまして、最近の財務状況、決して芳しくないというような事業者が増えてあります。ＣまたはＤの評価でも実際の経営が成り立っているというところで考えたときに…","id":"exchange-011"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ちょっと気になったのは、第１回目の選考で一番評価が高かった３２６点の事業者Ｂが１６点なのですよね。やっぱり８年間というところを任せるという意味ではちょっと心配だなと思ったので、こういったことをお伺いしました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"やなぎさわ委員","kind":"質問","question":"何点かお伺いしたいのですけれども、現在、外国人受け入れ支援というところで、令和５年度に１６名いらっしゃるということなのですが、これは技能実習とか特定技能とか、そういった内訳はどのような感じになっていますか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"インドネシアの方ですと、ＥＰＡで入ってきたという方もいらっしゃいます。一番多いのは特定技能ではないかなと捉えております。","id":"exchange-013"},{"speaker":"やなぎさわ委員","kind":"質問","question":"了解しました。３、金額を増やすとか、そういったことは何か改めてされる予定はあるのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"先ほどもちょっと説明させていただきましたが、今年からの大きなところは、５０万円の補助というのを新たに追加する予定となっております。件数がすごく少ないというところも伸びていくというか、実際に必要だと思いますので、増えていくのかなと思っているところです。","id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"質問","question":"３００万円の介護職員を雇っても、９０万円ぐらいかかってしまうということで、そこではないのだよという意見も伺ったりしております。介護職員の居住支援手当で１万円プラスしていただいたというのは、受け止め等あれば、お伺いしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"そこが本来の介護事業者ではなくて、国の審議会でも話題になっていたりとかして、重く受け止めているところです。折に触れて事業者の声を聞きながら、何が適切に、いいのかというところは研究していきたいと考えています。","id":"exchange-015"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"要望なのですけれども、介護施設へ回るかなと思いますので、そういったことをもし検討できたらなと思います。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"筒井委員","kind":"質問","question":"居住支援手当は月額１万円ということで始まったと思うのですけれども、住宅の確保ということで、家賃助成については居住支援手当とは別物なのか。低廉な家賃住宅の提供は大体何件ぐらいあるのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"利用者の負担が大体１人当たり２万円ぐらいの負担で、法人が本当に一部補助というか、持つというような形の仕組みになっております。外国人だとか、そういったことの制限を設けつつも、家賃助成をできるだけしたいというような仕掛けは考えていきたいと思っているところです。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひこれからも引き続き進めていってほしいと求めました。今回、まずスケッターの６か月無償トライアル利用を決定したというその経緯ですか、このマッチングするサイトというのはもうあるのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"すごく２０代、３０代、３０事業者以上のところに手を挙げてもらえたらなというところを働きかけたいと思っているところです。サイトのほうは、ボランティアがこれがいいなというところをぽちっと押すような仕掛けになっていますので、ぜひ後で検索していただければと思います。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。まだ始まったばかりだと思うのですが、そこから本格的に介護の仕事を専業でやろうかなという人とかは、現時点でいらっしゃるのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"そのままそこに就職することになったとか、そういうような事例は聞いておりますので、最終的にはそういった部分も期待はしています。","id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問","question":"それで、技能実習だと在留資格が３年だと思うのです。合わせて８年ということになると思うのですけれども、どういう支援があって、教えていただけたらと思います。","respondent":"菅野高齢者福祉課長","answer":"品川区で、先ほど技能実習とか特定技能が多いというお話をさせてもらいましたが、そういった方たちはその資格を基本的には持っておりません。ある法人では２名の方が合格したというような実績はありますが、区としては今後…","id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問","question":"日本人も１３人入られているという状況なのですけれども、その１３人というのは、希望すればそういうふうに入ることができるのか。１万円の家賃助成というのはそれはそれで、法人がアパートを借り上げて、そこら辺の考え方についてはいかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"ただ、実際は事業者が従業員の方用に借り上げたアパート代に対して、東京都のほうで８分の７というところで助成する仕組みがあります。なので、そういった意味では、民間のところもそれぞれのところで借り上げて、工夫はしていただいていると認識しております。","id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問","question":"３の具体的な取り組みのグリーンのところの丸の３つ目に、これはどういうことなのか、教えていただけたらと思います。区内５社会福祉法人ということなのですけれども、この５社会福祉法人はどの社会福祉法人なのか、５法人についても教えていただけたらと思います。","respondent":"菅野高齢者福祉課長","answer":"２点ご質問いただきまして、１点目は保健師採用促進支援のことだと思います。区内５法人ということなのですけれども、品川総合福祉センター、福栄会、さくら会、春光福祉会、三徳会の５法人となっております。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問","question":"ケアマネジャーで保健師を雇用した場合というのは、ケアマネジャーの中で保健師を雇用することの必要性というか、メリットというか、そういうものというのがどういう意味なのかがよく分からないので、そこのところを教えていただけたらと思います。","respondent":"菅野高齢者福祉課長","answer":"居宅介護支援事業所や在宅介護支援センターでも、医療的な部分の知識がある方というところで、ケアマネジャーをやりつつも保健師の資格を持っている方が採用された場合には、そういう補助するものをつくらせてもらいました。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問・要望","question":"なぜこんなに人材不足なのかといえば、やはり介護人材の賃金が低いというところが一番の原因だと思うのです。そういう声をどんどん、区からも上げてほしいと求めましたし、私たちとしても上げていきたいなと思っているところです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/814344?Template=document&Id=6867#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":19435,"voices":70}},{"id":"r06-20241106-8","meetingId":"r06-cm11","date":"2024年11月6日","dateIso":"2024-11-06","committee":"建設委員会","time":"午後 １時００分～午後 ４時１８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件整理しています。","topics":[{"id":"topic-01","title":"戸越六丁目１８・２０番東地区に関する都市計画案","agenda":"戸越六丁目１８・２０番東地区に関する都市計画案","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"９名の方が来られたということで、地図で見ると１５軒ぐらい建物があるように見えるのですが、なぜ９名だったのかという。もし意見がありましたら、教えてほしいと求めました。","respondent":"小川木密整備推進課長","answer":"１.５ｍ壁面を下げなければいけないということで、その違いということでご説明をさせていただいて、ご納得をいただいたところです。そのほかに、こちらに関しましては、品川区の開発指導要綱に沿った形で設定をさせていただいたという形でご回答をさせていただいているところで…","id":"exchange-001"},{"speaker":"澤田委員","kind":"質問・要望","question":"別の３の都市計画案の説明会の開催予定での質問をさせていただきたいのですけれども、それ以外に何か周知というのはされる予定はないのでしょうか。説明を求めました。","respondent":"小川木密整備推進課長","answer":"区ホームページというのに関しましては、あくまでも都市計画案の公告・縦覧ができる場所がこちらという形で記載をさせていただいているものです。説明会の周知につきましては、今回の場合は８０ｍになるのですが、広く説明会の実施の周知については努めているところです。","id":"exchange-002"}]},{"id":"topic-02","title":"ＡＩオンデマンド交通の実証運行","agenda":"ＡＩオンデマンド交通の実証運行","exchanges":[{"speaker":"つる委員","kind":"質問","question":"スケジュールにあるとおりだとは思うのですが、その上で、区としての考えというのがあると思うのです。喜んでいただいている声というのが大きいのかと思っていますけれども、いわゆるこのエリアの範囲というのは、何km四方になるのか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"今回、１台で検証をやらせていただくのですが、１台でカバーできる範囲で、おおむね１.５から２km四方というのが標準的なエリア設定の考え方となっております。","id":"exchange-003"},{"speaker":"つる委員","kind":"提案","question":"運行条件というのは事業者提案を踏まえ決定となっているわけですけれども、それはこの場で言える言えないも含めて教えていただきたいのですが。桑名市はたしか５km四方と言っていましたけれども、車両の大きさというのですか、これがどのぐらいになるのだろうというところとの意見を述べました。","respondent":"櫻木地域交通政策課長","answer":"車両の考え方ですが、その辺りを考えると、大体５名から８名ぐらいが乗車定員になってくるのかと考えています。現時点でできるかというところはありますが、車椅子を畳んで乗っていただけるような方については、ご利用いただけるのかと考えています。","id":"exchange-004"},{"speaker":"つる委員","kind":"提案","question":"事業者の提案とか、そうしたところの配慮というか、ぜひお願いしたいと思います。３００円、視察のときにも伺ったのですが、必要なのかと思いましたとの意見を述べました。","respondent":"櫻木地域交通政策課長","answer":"利用を促進していく上で非常に大事なことだと思っておりまして、事業者に説明会等をやっていただくよう、考えているところです。いわゆる高齢者地域支援課でやっているスマホ教室との連動みたいな話も少し調整はしているので。","id":"exchange-005"},{"speaker":"つる委員","kind":"質問","question":"ありがとうございました。最後に、それから、その辺のこれは実証実験なのだとかということの周知を走らせながらやるというところの部分についての考えを説明を求めました。","respondent":"櫻木地域交通政策課長","answer":"ラッピング広告掲載等のお話をいただきまして、グリーンスローモビリティもそうなのですけれども、今、実証運行ですので、車両をお借りして走らせるという状況の中でどこまでできるかというところで、事業者提案等も踏まえながら考えていくところかとは思っております。","id":"exchange-006"},{"speaker":"澤田委員","kind":"質問","question":"１点だけお伺いしたいのですけれども、どうなるのかというのをお伺いしたいと思いまして、。","respondent":"櫻木地域交通政策課長","answer":"まさに検討中のところでございまして、介助者の方とご一緒でないと、どうしてもご利用が難しい方はいらっしゃるという想定はしております。その中で、例えば３００円という料金設定でいくのかいかないのかというのは…","id":"exchange-007"},{"speaker":"えのした副委員長","kind":"質問","question":"地図が小さいのですけれども、点を数えると、１８か所になるのですかね。そちらはまた公共の交通を使ってほしいということもあるとは思うのですけれども、そういった延長みたいなことも考えられているのか、説明を求めました。","respondent":"櫻木地域交通政策課長","answer":"道路運送法上では町丁目単位でエリアを指定することになっていますので、その辺でどこまで、町丁目単位で広げる広げないという概念になってくる。その辺を考えながらということになってまいりますので、様子を見ながら、少し今後の展開を考えさせていただければと考えています。","id":"exchange-008"},{"speaker":"横山委員","kind":"提案","question":"今回、そうした放課後の移動についても使われていらっしゃるというような結果が出ているというお話をお伺いしまして、やはりお子さんが小さいと。例えば、そういった割引についても、区としてはそういったお子さんのみの利用みたいなところはどのように考えていらっしゃるのか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"お子様のみのご利用は区としても認識しておりまして、子育て世帯というところで、塾利用というところは一つ想定しているところではあります。料金につきましては、先ほど申し上げたとおり、これから提案等も踏まえて考えていきたいと考えています。","id":"exchange-009"}]},{"id":"topic-03","title":"東品川海上公園におけるＰａｒｋ－ＰＦＩ制度の導入に向けた公募設置等指針の公表","agenda":"東品川海上公園におけるＰａｒｋ－ＰＦＩ制度の導入に向けた公募設置等指針の公表","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"Ｐａｒｋ－ＰＦＩということで、民間の方々の様々なお知恵等を反映していただけるかと思いますので、大変期待しているところです。２０２０年の予算特別委員会で、そういった公園の植栽の維持管理みたいなところですかね、区のお考えを説明を求めました。","respondent":"大友公園課長","answer":"本公園につきましては、かなり著名なガーデナーの方のアドバイス等々をいただきながら植栽の管理をしているというところになってあります。しっかりした会社を選んでいきたいと考えてございまして、そこの評価、提案についてしっかり見ていきたいと考えているところです。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問","question":"どういう団体なのですか。こちら側から団体に伺っていったのか。","respondent":"大友公園課長","answer":"今回、地元調整という段におきましても、団体とも調整をさせていただいているところになってあります。特に東品川海上公園を使って活動している団体に声をかけさせていただいて、いろいろご意見等々を賜ったところになってあります。","id":"exchange-011"},{"speaker":"つる委員","kind":"確認","question":"改めて確認なのですが、法律の立てつけ上、面積に対して１２％ですね。これ、パーセンテージとか平米でどのぐらいの想定になっていたのか、改めて、その団体ももしあれば、説明を求めました。","respondent":"大友公園課長","answer":"１０％上乗せというところも考えられるのですけれども、２％の中だと、４００m2ちょっとのものが建てられるかと思います。この４００m2というところの建物、２００m2というようなところもありますので、十分な広さの確保の建物は建てられるのかと考えています。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"既存の建物というか、これもパーセンテージの中に入ってしまうのですか。既にあるトイレなども含まれてしまうのか尋ねました。","respondent":"大友公園課長","answer":"建蔽率の中には、既存である建築物の建物は既に入ってしまいます。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問","question":"一遍に聞けばいいのですけれども、そうすると、現在、何％なのですか。それだけ最後に説明を求めました。","respondent":"大友公園課長","answer":"１％も満たず、０.何％、詳細の数字を把握していなくて、誠に申し訳ありません。影響がある数字ではないです。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/463917?Template=document&Id=6865#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":15218,"voices":52}},{"id":"r06-20241106-9","meetingId":"r06-cm11","date":"2024年11月6日","dateIso":"2024-11-06","committee":"文教委員会","time":"午後 １時００分～午後 ４時２７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"高橋（し）委員","kind":"提案","question":"いろいろな予定があって、もろもろ調整したりすると思うのですが、いつ頃に議会のほうに提案される予定でしょうか。現状の見込みで結構ですとの意見を述べました。","respondent":"中谷指導課長","answer":"見込みとしましては、本日、給与勧告の概要をご報告させていただいておりまして、この後、給与勧告の内容について特別区の組合と妥協予定があります。そうしまして、１１月２５日と２６日の文教委員会で、固有教員…","id":"exchange-001"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、２５日、２６日で委員会をやって、その後の本会議でということになるのですか。それとも、その前に何か臨時でということがあるのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"西村委員","kind":"意見","question":"例年よりも内定されている方が多いのではないかなと思っているのですけれども、当初の人数的な目標だったり、結果、お感じになられているところがあれば、説明を求めました。","respondent":"中谷指導課長","answer":"定員３０名を充足するというところを１つの目標としてずっとやっておりましたが、各学校に１人の固有教員をつけていく必要性が大変高まっております。すぐに次年度に全校１人というわけにもいかないため、今回は６名という数字を設定させていただいて…","id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"質問","question":"恐らく東京都とか横浜市とかほかの自治体と品川区を併願している方々が多いと思うのですが、そのような中で、こうして品川区を受け、面接なり書類なりで、どうして品川区を選んだのかという理由で、何か印象的なものがあれば、二、三で結構ですので説明を求めました。","respondent":"中谷指導課長","answer":"やはり様々な自治体を比較された受験者が、品川区では地域とよく連携して学校教育を進めているというところに高い関心を持ってくださったことです。英語教育が一貫教育であるというところで、この２つが今回は特に特徴的であったかなというふうに振り返っております。","id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"この８名の方にはぜひこういった思いを持ち続けて、品川区の中で定着していってほしいと求めました。そして、中堅、ベテランになっていくことを期待します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"山本副委員長","kind":"質問","question":"私からも１点、質問します。１学校につき１人を配置することを目標としていらっしゃるということなのですけれども、現状ですと、どのように考えていらっしゃいますか尋ねました。","respondent":"中谷指導課長","answer":"４６校に義務教育学校の課程が６名加わりますので、５２名というような見込みで配置をしていきたいというふうに考えております。は、固有教員というものがあって、こういった特色があるというようなことを直に学生にご説明するというようなことをやっております。","id":"exchange-006"}]},{"id":"topic-02","title":"令和６年度品川区学力定着度調査および令和６年度全国学力・学習状況調査の結果","agenda":"令和６年度品川区学力定着度調査および令和６年度全国学力・学習状況調査の結果","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"学校で、この学校のこの学年の子どもの社会の点数がよかったというのは、それは当然分かるということでよろしいのでしょうか。そこでどういう教育をしているということを抽出するということなのか尋ねました。","respondent":"中谷指導課長","answer":"小学校６年生の歴史で何を子どもたちが学んできたかということを、そこが意識されていないというところが課題だなというふうに思っております。そういったところに切り込んでいけるような話合いや研究ができればいいかなと考えています。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"意見","question":"分かりました。それに対して的確に対応されていく、教育委員会は優秀な方ばかりですので、また引き続き品川の子どもたちをとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは要望します。いわゆる定期テストなどの確認の仕方、それが、恐らく定期テストが終わってしまうと全部忘れてしまうところがどうしてもあります。","respondent":"中谷指導課長","answer":"おっしゃっていただいたとおりだと思いますので、そのようにやってまいりたいと考えています。先ほど申し上げたとおり、そこをきちんと連動させていけるようにというところで、教育会のほうで工夫してまいりたいと思います。","id":"exchange-009"},{"speaker":"山本副委員長","kind":"質問","question":"７年生以上で、過去との比較でいうと、どういう状況なのでしょうか。それから２つ目としては、教育会等で、どのようなやり方をお考えでしょうかということです。","respondent":"中谷指導課長","answer":"特に意欲、どういった学びが授業の延長線上として継続できるようにするかといったところに非常に工夫をしていかなければならないと考えています。何に取り組む必要があるのかを考え、また…","id":"exchange-010"},{"speaker":"山本副委員長","kind":"質問・要望","question":"２つ目のところで、ぜひそこは、そのようにお考えほしいと求めました。これは要望です。","respondent":"中谷指導課長","answer":"研究員といいまして、１年間以上こちらに所属をして、ご自身が選んだ教科を授業研究という形でしっかり学ぶというような制度があります。こういったところに積極的に品川区の先生方が、校長先生の推薦を受けて参加されるというようなことを推奨していきたいなと考えています。","id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"質問","question":"８年のテストは地理、９年は８学年で歴史をやっていれば、これは歴史という認識ですか。例えば、３分野のうちのどこかが少し弱いとか、そういった分析をどういうふうにされているかということをお尋ねします。","respondent":"中谷指導課長","answer":"その中の特に思考・判断・表現、それから９学年になりますと、そういったところを踏まえた取組をしていきたいというふうに思っております。毎年こちらは進級して４月にやっておるのですけれども、基本的には、その前の学年までにやった学習内容ということになっております。","id":"exchange-012"},{"speaker":"西村委員","kind":"質問・要望","question":"１点だけ、お願いします。１ページ目のところで、今年度の特徴でしたり、近年の傾向があればお聞かせほしいと求めました。","respondent":"中谷指導課長","answer":"不安を感じたりすることがあるというような内容の質問に対しては、昨年度よりも、よい傾向が出ているということがあります。学校の授業の予習や復習のような学習習慣に関する項目については低いという状況が、かなり目立って出ているというところでご紹介をしています。","id":"exchange-013"},{"speaker":"西村委員","kind":"質問・要望","question":"先生方もご努力いただいていると思うのですけれども、なかなか子どもたちに根づくのは難しいのかなと思ったりします。ぜひ生かしていただきたいなと思うのと、授業のアプローチですとか学校の取組に、この結果を生かしていただきなというふうに思います。","respondent":"中谷指導課長","answer":"すみません、１つ補足をします。自分の学校でどうだったのか、そういった改善のプランをつくって発信するということになっておりますので、よろしくお願いいたします。","id":"exchange-014"}]},{"id":"topic-03","title":"区立学校におけるいじめの重大事態の調査結果","agenda":"区立学校におけるいじめの重大事態の調査結果","exchanges":[{"speaker":"せらく委員","kind":"確認","question":"この件については、令和６年５月９日が答申日となっていて、本日の委員会でのご報告なのですけれども、６か月ほど時間があったのは、保護者へ公表希望を確認していたからということか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"今おっしゃっていただいたとおりです。もう少し考えさせてほしいですとか、公表は希望しませんというようなご希望を出されたということで、今回の報告までに時間がかかっているです。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問","question":"品川区においても、そういった、前の年度、２０２３年度の全国の小中高校で起きたいじめの重大事態が１,３０６件ということで過去最多。それは２０２３年度の話ですが、品川区は増えていないのか、その辺りを説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"しっかりと法に基づいた対応をしていくということで、また認識を改めた対応の結果だと考えております。自治体が、それぞれ法に基づいた対応をしている成果だというふうな捉えをしておりますので、いじめの未然防止に努めてまいりたいと考えております。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"確認","question":"４割が見過ごされていたのではないかというようなところについては、今、学校関係者の間では共有認識としてあるのか。それに対してどのような思いで取り組まれているのかということを確認させてください。","respondent":"丸谷教育総合支援センター長","answer":"本区におけるいじめの重大事態それぞれについてですけれども、いずれも重大事態になる前に、いじめの認知としての対応は行っております。今回、全国の発表にあったような、しっかりと学校の意識も高めてまいりたいと思います。","id":"exchange-017"},{"speaker":"山本副委員長","kind":"質問","question":"私からも１点、いじめの重大事態に関連して、いじめ問題についてお伺いします。７月頃から、それ以降、重大事態化しているものが減っているのかどうかというところのご感想をほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"１つのツールが全て網羅的にできるかというと、今、事例として上がってきております。今後も引き続き重大化は未然に防げるような取組は続けてまいりたいと考えております。","id":"exchange-018"}]},{"id":"topic-04","title":"品川区子ども読書活動推進計画（素案）に係るパブリックコメントの実施","agenda":"品川区子ども読書活動推進計画（素案）に係るパブリックコメントの実施","exchanges":[{"speaker":"西村委員","kind":"質問・要望","question":"子どもが行きやすい、質問させていただいたのですけれども、そういった環境設計に関して素案に記されているものがあるかということを伺います。全ての図書館で自習室を開放されているのか、自習室となっていないようなスペースもたくさんあると思いますので、その辺りを伺えればと思います。","respondent":"河内品川図書館長","answer":"子どもたちが、より図書館を利用しやすくなるような形で、全館を挙げて取り組んでまいりたいと考えているところです。お互いの配慮が将来的な読書の推進につながるものだというような意識啓発も含めて、今後の事業を進めてまいりたいと考えているところです。","id":"exchange-019"},{"speaker":"西村委員","kind":"質問","question":"こしょこしょ話でも怒られてしまうというような、びくびくした中で子どもたちが宿題とかをしている姿も見るものですから、ぜひ期待をしております。３７ページで、どう本を好きになってもらえばいいのかというのは、本当に永遠のテーマのような気がしています。","respondent":"河内品川図書館長","answer":"皆さんに楽しさの中で読書に親しんでもらう活動を地道に続けることが大事かなというところで、まずはしっかりやっていきたいと考えているところです。回答になっていないかもしれませんが、そういった考えでおります。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問","question":"いざというとき、関心を持ったときにアクセスしやすい図書館であってほしいと強く思います。大変お世話になっているので、なかなか望むものはないのですけれども、１点だけ伺います。","respondent":"河内品川図書館長","answer":"ボランティアのご協力ありがとうあります。","id":"exchange-021"}]},{"id":"topic-05","title":"品川区児童福祉審議会の開催","agenda":"品川区児童福祉審議会の開催","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"(3)の部会の中の2)子どもの権利擁護部会について、もう１回、本会のほうにかかって最終的な結論を出すということなのでしょうか。全員で行う本会は年２回、特定の事項については各部会ということなのか、その辺りの仕組みについて教えてほしいと求めました。","respondent":"柴田子ども施策連携担当課長","answer":"本会におきましては、各部会、その年度でこういったものがあったという報告の場というような形になってあります。ご理解をいただく、そういった一定の結論もありながら、そういったところを今後もいろいろな材料として提示していく形になっていくかと思います。","id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問","question":"どういった役割を果たすのかというところも含めて、どういう振り分けをお考えになっているのか、そこを詳しく教えてください。措置と一致しない場合、「特定の事項については各部会にて審議する」となっているのですが、年間で何件ぐらいを想定されているのか説明を求めました。","respondent":"柴田子ども施策連携担当課長","answer":"子どもから声が上がってきた場合は、すぐに開けるようにということで、月に１回定例で実施を予定しています。実施の回数としては、できる回数は２か月に１回置いていますけれど、実際の回数はもっと少なくなるというふうに想定しております。","id":"exchange-023"}]},{"id":"topic-06","title":"再度、予定表の順番を入れ替えて、(1)議会の議決を欠いた契約に関する調査結果","agenda":"再度、予定表の順番を入れ替えて、(1)議会の議決を欠いた契約に関する調査結果","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"１つだけ伺います。２ページの３段落目で、動産にはあたりませんとあるのですが、これは何を基にこういった記述がされているのかだけお尋ねします。","respondent":"佐藤経理課長","answer":"というのは、デジタルソフトを使用する権利を購入するということで整理しておりまして、使用料で支払う。一定の期間、そのソフトを使用する権利を購入するという形になりますので、それぞれ分けて契約をしているです。","id":"exchange-024"},{"speaker":"高橋（し）委員","kind":"質問","question":"その説明は、何を基にしてお話しされているのか尋ねました。","respondent":"佐藤経理課長","answer":"歳出をどの節で分類するかというところについては、いわゆる行政実例等の参考にする書籍がありますので、そういったものを基にしまして判断しています。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問","question":"この調査報告の４ページのただいまの結論のところなのですけれども、６番のところです、何にこれは違反をしたのでしょうか。根拠法令を説明を求めました。","respondent":"柏木学務課長、佐藤経理課長","answer":"地方自治法で普通地方公共団体の議会の議決で条例で定めるものがございまして、それによって区の条例が定められております。ですので、根拠としては、こちらの地方自治法に違反しているという考えです。 その第８号に、条例で定める財産の取得について処分をすることとなっております。地方自治法施行令の中で一定の金額以上の動産の買入れについては議決が必要という規定になっておりますので、そのような体系になっております。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"確認","question":"ありがとうございました。確認もあったということですが、もしかしたら決算特別委員会の質疑の中であったのかもしれないのですけれども、把握している範囲で説明を求めました。","respondent":"柏木学務課長","answer":"報道ベースにはなりますけれども、今回このように議決を欠いた契約、品川区と同様の契約を行った自治体は１３自治体はあるというふうに把握はしています。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問","question":"しつこくてごめんなさい、ありがとうございました。何か特筆すべきような原因があったのか、その辺りも参考に説明を求めました。","respondent":"柏木学務課長","answer":"私どもで確認している限り、原因は、我々と同様の認識が欠けていたという部分が多く見られます。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"意見","question":"再発は絶対にしてはいけないと思いますし、また万が一こういうことが起きると、もう恐らく追認というわけにはいかない事態になると思います。ここに書いてある再発防止の施策を確実に、そして、年月を経ても引き継がれるような形でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"山本副委員長","kind":"質問・要望","question":"では、私からも１点。５番の再発防止に向けた取組について確認させていただきたいのですけれども、予定価格に応じた議決の必要性が確認できるようにします」ということは。","respondent":"佐藤経理課長","answer":"今考えているのは、４,０００万以上であれば議決が必要ですという形で注意喚起するというメッセージが出ることを考えております。止めることも考えてはみたのですけれども、比較考量して、そういったメッセージを出すことを考えております。","id":"exchange-030"},{"speaker":"山本副委員長","kind":"質問・要望","question":"やはり人が進めていくとなると、どうしてもヒューマンエラーが出てきてしまう。できるだけ防げるような仕組みをしていただきたいですし、そこは両面で、今後の再発がないように努めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"}]},{"id":"topic-07","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"西村委員","kind":"質問・要望","question":"何点か伺わせてほしいと求めました。学習支援、通訳派遣、訪問支援、この３点に、実際どういう方がその支援に出向いておられるのかということも伺えればと思います。","respondent":"染谷子ども家庭支援センター長","answer":"こちらは令和５年度から実施しておりまして、令和６年度につきましては、第１回が６月３０日でございました。学習支援につきましては、学習支援とあわせて、そういった生活支援の部分も含めて実施していただけるということで。","id":"exchange-032"},{"speaker":"西村委員","kind":"質問・要望","question":"学習イベントというものも９人も来られていて、これもどのようなものだったのかということを伺いたいなと考えています。ヤングケアラーの問題を予防するとは、どうしていくのかというところを、お考えがあればお聞かせほしいと求めました。","respondent":"染谷子ども家庭支援センター長","answer":"学習支援における、年齢の若い子たちで、主に小学生と実施させていただきました。そういった取組を進める中で、決してそれが悪いことではないという前提の下、予防という取組が進められるのではないかと今考えているところです。","id":"exchange-033"},{"speaker":"西村委員","kind":"意見","question":"食に困っているのか、言語に困っているのか、学習に困っているのかというのは本当にその子によっても様々なのだと思うのです。そういった発想から、いろいろな取組が声からできていくということを期待しておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ヤングケアラーのところからまず伺いたいのですけれども、ヤングケアラーサポートＬＩＮＥについて、ともだち登録数２０１人とのことでした。事務局の方が把握して、個別にやり取りをしているという意味なのか、継続的にというところの意味を教えていただきたいことが１つ目の質問です。","respondent":"染谷子ども家庭支援センター長","answer":"この３７件については、令和６年８月末時点での数字ではあるのですが、いわゆるチャットでのやり取りを継続して実施している件数となります。必要というふうにこちらで判断をしていますので、ご家庭と…","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そういうよく使われている言語ではなくて、本当にレアな少数民族の言語みたいなものであったとしてもやっていっていただきたいです。ヤングケアラーについては以上です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"その後、ほかでもう１回やらせていただければ。では、こちらも質問してしまっていいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今どのようなことを支援企業とお話をされていて、今後の方向性としてどういったことを考えていらっしゃるのか教えていただきたいということが１つ。これは子ども未来部門と教育委員会、どちらからの見解も伺いたいと思います。","respondent":"飛田子育て応援課長、舩木庶務課長","answer":"区としても、どうにか支援ができないかということで話し合っております。もう１つ、何かしら子どもの食の支援というところでできればというふうに考えていますので、協議していく必要があると考えております。 子どもの食の支援というところもそうですし、連携がとれるところは連携をとって、情報等も共有しながら進めてまいりたいと考えております。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問・要望","question":"当時、２０１５年、１６年ですから、子ども食堂への理解自体がなかったということもあります。それと、子どもの朝の居場所づくりということをこれから学校の中で取組まれるということですから、これは切っても切れないものだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"せらく委員","kind":"質問","question":"２枚目の3)番の子ども若者応援フリースペースについて、何点かお伺いしたいと思います。一度視察に伺ったことがありまして、お話も聞いてきたところなのですけれども、思ったよりも危うい子どもたちがいたなというふうに感じております。","respondent":"柴田子ども施策連携担当課長","answer":"毎年４月に、前の年に利用していても、新たに来た子は登録をするということになっております。令和２年度が１７１人、始まった当初の１００台で推移したときよりは上がってきているなというふうに、こちらでは認識しています。","id":"exchange-040"},{"speaker":"せらく委員","kind":"質問・要望","question":"その対応として、環境整備と支援メニューの充実をというところなのですけれども、こちらについて、具体的なものがあれば教えていただきたいです。支援メニューは、現在どのような支援メニューがあって、どのようなものが今後必要になってくるかもお考えを教えていただけますか尋ねました。","respondent":"柴田子ども施策連携担当課長","answer":"今後の支援メニューの充実なのですけれども、元気になって、社会に飛び立つということが理想な部分がどうしてもあろうかと思います。まだ具体的にこれというものは出ていないのですけれども、仕事につながるようなメニューも入れていきたいというふうに考えているところです。","id":"exchange-041"},{"speaker":"せらく委員","kind":"確認","question":"今後、自立に向けた支援を拡充していきたいという思いでいらっしゃるということを確認いたしました。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"西村委員","kind":"質問","question":"先ほど、子ども食堂のことも伺えばよかったのですけれども、改めて伺えればと思います。どのようにお考えかというところと、今、幾つぐらい区内にあるのか伺えればと思います。","respondent":"飛田子育て応援課長","answer":"いろいろな考え方があるのですけれども、子どもだけでも、もちろん食べに来ていいんだよという声をかけてくれることもあります。そういう子どもだけでも行けるところがどのくらいあるのか、運営会議とかがありますので、そういうところで聞き取りをしてみたいと考えております。","id":"exchange-043"},{"speaker":"西村委員","kind":"質問","question":"運営する側の方にとっても継続しやすいというか、そういったお声もあるかと思います。今、ご寄附が潤沢にあるのかとか、子ども食堂によって、ご寄附の分配の仕方とかも様々ご苦労されていると思うので、その辺り、最後に伺います。","respondent":"飛田子育て応援課長","answer":"２回転、３回転やっているところもあるのですけれども、もうそのままお弁当で対応しているところもある場所も結構あります。つい最近は、食肉市場のほうから牛肉の寄附がありましたので、そういったものも分配しているような状態です。","id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"質問","question":"学校が先にヤングケアラーを何となく把握して、ここのところ、あるのかということを伺いたいと思います。それからあともう１つ、学校との連携は、フリースペースのほうでどのようにされているのかお尋ねします。","respondent":"丸谷教育総合支援センター長、染谷子ども家庭支援センター長、飛田子育て応援課長、柴田子ども施策連携担当課長","answer":"ヤングケアラーについては、２年前から各校での研修も実施していただいて、学校の理解も進んでいるところです。具体的には… ヤングケアラー支援を子ども家庭支援センターで実施する意義の１つとして、要保護児童対策地域協議会の活用も考えられるかと思います。… そういうときは、子ども家庭支援センターのほうにということは伝えています。必要に応じて、ボランティアや企業での社会貢献活動… フリースペースと学校の関係性についてですけれども…","id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それこそ子ども政策連携というフレーズがあるものですから、学校とか、こういった垣根を越えて進めていってほしいと求めました。予防という意味においては、お子さんの様子が分かるところなので、ぜひ学校の先生方のそういった目も大切にしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"山本副委員長","kind":"質問・要望","question":"少しお伺いしたかったのが、視察のときにお話に少し上がったエリアの偏り、空白地帯の手当てというものがあるのではないかと思います。これはどう受け止めていらっしゃるのか、もっともっといたほうがいいと思っていらっしゃるのかどうか、数に対するご認識を説明を求めました。","respondent":"染谷子ども家庭支援センター長、飛田子育て応援課長","answer":"実際に令和５年度に、先ほどご説明した相談ツールをタブレットに設定するなど、基本的にはデジタルの活用を進めていきたいと考えております。定期的に実施していくことが必要であるというふうに認識しておりまして… 西小山駅周辺とか、しながわ水族館の周辺は、少し少ないかなということは認識しているところです。今、運営の事業者数が多いか少ないかということは、なかなか難しいかなと考えています。","id":"exchange-047"},{"speaker":"山本副委員長","kind":"質問・要望","question":"それぞれに支援の拡充、効果的に進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/435368?Template=document&Id=6863#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":57449,"voices":173}},{"id":"r06-20241106-5","meetingId":"r06-cm11","date":"2024年11月6日","dateIso":"2024-11-06","committee":"総務委員会","time":"午後 １時００分～午後 ３時０６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件整理しています。","topics":[{"id":"topic-01","title":"議会の議決を欠いた契約に関する調査結果","agenda":"議会の議決を欠いた契約に関する調査結果","exchanges":[{"speaker":"西本委員","kind":"意見","question":"億単位であれば、何かやらなければいけないという認識があると思うのです。数千万円という形になると、今後は適正な経理関係、議決というのをしっかりとしていただくようにお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"須貝委員","kind":"確認","question":"これは確認なのですが、令和２年度、主管課長に委任しましたと。お互いにそういう考え方だと思うのですが、わざわざ契約事務規則をここで改正したというのは、何か理由があるのか尋ねました。","respondent":"佐藤経理課長","answer":"令和２年度に契約事務規則を改正して、このときは２点、迅速な執行を確保して事務の効率化を図るというところを主な目的として行ったところです。すぐにできるというところを主として考えておりまして、趣旨としましては、そのような形で改正したものです。","id":"exchange-002"},{"speaker":"須貝委員","kind":"意見","question":"本当にこれは紛らわしいと思うのです。これで今回の契約に関して、４,０００万円以上に関しては経理課でやるということなので、もう間違いは起こりにくいと我々は捉えていいですねとの意見を述べました。","respondent":"佐藤経理課長","answer":"今回お示しした改善案で、職員の認識に限らず、組織として対応できる体制ができると考えておりますので、今後このようなことがないように努めてまいります。","id":"exchange-003"},{"speaker":"大倉委員","kind":"確認","question":"システムとしてどうチェックしていくかということが、システム処理時に予定価格に応じた議決の必要性を確認ということがあるのですけれども、議決の必要性の確認というところをどのようにしていくのかというところを説明を求めました。","respondent":"佐藤経理課長","answer":"３０万円を超えても、超えているけれども大丈夫ですかと、再度確認をするというものがあります。メッセージの一つとして、４,０００万円を超えた場合は議決になります、再度確認するという仕組みを取り入れたいと考えております。","id":"exchange-004"},{"speaker":"大倉委員","kind":"意見","question":"今ある、既に使っているようなシステムを応用して使っていって、人もチェックするし、システムもチェックするということが分かりました。引き続き、こうしたことがないように、ぜひ迅速に対応してほしいと求めましたので、お願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"松本委員","kind":"質問","question":"１００％は無理なので、今、システムでメッセージが出るというお話があったかと思います。メッセージを４,０００万円以上にしていくというお話があったのですけれども、これは何か別に費用がかかったりするのか尋ねました。","respondent":"佐藤経理課長","answer":"４,０００万円以上であれば議決が必要という形であれば、一定時間がかかりますが、対応できるのではないかと。追加の経費についても、そんなに多くならないということで聞いておりますので、そのような形でやっていきたいと考えております。","id":"exchange-006"},{"speaker":"松本委員","kind":"質問","question":"今のご説明だと、通常３０万円という一つのレベルがあって、３０万円を超える分にはメッセージが全部出てくるということなのかなと思うのです。３０万円以上はこういうものです、４,０００万円以上はこういうものですと、どちらの方向なのか尋ねました。","respondent":"佐藤経理課長","answer":"委員のご指摘のところでいきますと、後段のほうでして、メッセージの内容を変えて、注意を２つにするということになろうかと思います。３０万円以上については、４,０００万円を超えた場合は議決が必要ということで…","id":"exchange-007"},{"speaker":"松本委員","kind":"質問","question":"もう１個、随意契約できるかどうかというところも、お金で判断されているのではないかと思います。随意契約かどうかというのは、他自治体を見ると、ここの部分について何か予防的に対応は考えられているのか尋ねました。","respondent":"佐藤経理課長","answer":"システム化するとなると、特に今の入れているシステムがパッケージソフトなので、かなり大規模なカスタマイズになるということになろうかと思います。１件目は主管課で契約するにしても、そういった動きを見ながら、デジタル推進課と相談しながら検討していきたいと思います。","id":"exchange-008"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"確認しますということで、１か月弱の間に確認をしていただいて調査をして、大変にありがとうあります。議会の指摘を受けて動いていただいたわけなのですが、その前に、そのような動きというのはあったのかどうか、教えてほしいと求めました。","respondent":"柏木学務課長","answer":"令和６年度の契約において、大変申し訳ございませんけれども、確認をしていなかったというのが現状です。ただ、こういう事態になりまして、もっと深く考えればよかったと、そこの点については非常に反省をしています。","id":"exchange-009"},{"speaker":"新妻副委員長","kind":"意見","question":"データ的にもしっかりと、システム改修というところでのチェックという２段階があることで、改善がされていくのかなと思います。その上で、今回の事態につきましては、ホームページ上での公開というのはどのようにお考えか、説明を求めました。","respondent":"佐藤経理課長","answer":"今回の事態に関しましては、まずは区議会にご報告するということを優先して、調査等をしてきたものです。今後につきましては、戦略広報課とも意見交換等をしておりますので、公開については、する方向で検討しております。","id":"exchange-010"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"他自治体を見ますと、教育委員会のホームページの中で公表されているところが多いようでありますが、またご検討ほしいと求めました。区のお金の動きを確認するに当たっての、議決の一覧というところをまた出していただけるのかどうかというところは教えてほしいと求めました。","respondent":"佐藤経理課長","answer":"今回、防止策ということで一つ、予算書の確認ということで申し上げておりますので、今、副委員長のご指摘の部分につきましては、予算書を編成します財政課とも相談しながら検討していきたいと思います。","id":"exchange-011"},{"speaker":"松本委員","kind":"質問・要望","question":"要望だけなのですけれども、先ほどの確認で、よく出てくるメッセージになると思うのです。４,０００万円を超えているというところを確認せずに、認知上、多分そういうことが起こるのではないかと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"}]},{"id":"topic-02","title":"コンプライアンス推進のための取組み","agenda":"コンプライアンス推進のための取組み","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"なかなか全部に対応できるのはそうそうないことなので、そこはスキルアップをしていただきたい。そこをどう考えられているのかお聞きしたいのですけれども。","respondent":"石井コンプライアンス推進担当課長","answer":"例えば３０分以上の拘束がかかるとか、やはり組織として、そこはおやめくださいと言う必要はあると思います。それがあって初めてカスタマーハラスメント対策は成り立っていくものと考えております。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"実際、自治体のほうは直に会っているわけだから、そこのギャップがあるではないですか。物すごくこれは根が深いというか、生涯学習というところにもなるのかもしれませんけれども、これをどのように進めていかれる予定か尋ねました。","respondent":"石井コンプライアンス推進担当課長","answer":"今回、総務委員会資料の中で、今年８月からコンプライアンス推進担当において全庁相談事業というのを始めました。研修を進めていく上でも、きちんと文脈に応じて判断できる職員の育成というものは、進めていかなければならないかなと考えております。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"先ほどおっしゃっていたように、こういう現状があるから、正しい判断というのをしなければいけないと思うのですけれども、それはどうするのか。そういうときの判断はどうされるのか尋ねました。","respondent":"石井コンプライアンス推進担当課長","answer":"正直、それは誰がどう判断してという話になってくると、なかなか我々コンプライアンス推進担当でも難しいのではないかと考えております。そこについてはまた、おいおい検討していかなければいけない課題であると思いますけれども、まずは一つ。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問・要望","question":"傾聴とか、そういう技法もしっかりと職員側にも、それからコンプライアンス推進担当の方々にも学んでいただきたいと強く要望したいと思います。最後に、いろいろと行動規範とか、方針とか、これは総務委員会には報告をしていただけるものなのか尋ねました。","respondent":"石井コンプライアンス推進担当課長","answer":"現在策定中で、これから職員の声を聴きながらつくり上げてくるものですけれども、もちろん策定が進みました折には、この総務委員会で報告をします。","id":"exchange-016"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"だから、その辺の課題はどうやっていくのかというのと、通話録音機がよく分からなくて、通話録音機というのは、ただ録音するものですよね。そういうボイスメッセージが出るものではなくて、ふだんの通話の中で録音するものが入るのか、その辺を教えてほしいと求めました。","respondent":"石井コンプライアンス推進担当課長","answer":"昨年度まで実施していましたイメージアップの取組でも、先ほど委員がおっしゃるようなご意見などが上がっていることも事実だと考えています。録音する際には、今から録音しますという形で宣言をしなければならないかなという、運用上の制約があるという状況です。","id":"exchange-017"},{"speaker":"まつざわ委員","kind":"質問","question":"電話を受けて、これから録音しますというのは、毎回これをつけたときに、やっていかなければいけなくなってしまうということですよね。それもまた苦情の種になってしまうのかなというのが、少し心配があるのですけれども、その辺はどうお考えか尋ねました。","respondent":"石井コンプライアンス推進担当課長","answer":"録音できなかったとか、本当に録音が必要な場面でそれがされないとか、そのようなことが課題として考えられるところです。できるだけ漏れがないようにしていきたいとは考えているのですけれども、設備面で検討ですとか、検討課題として進めていきたいと考えております。","id":"exchange-018"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"しっかりやっていただきたいのと、最後に、カスタマーハラスメント対策ですけれども、議員もあるのかなと。議長のほうで３０分以上は拘束しないでと言っても、職員を守る対応策というのは一緒に考えていくのか、その辺を説明を求めました。","respondent":"石井コンプライアンス推進担当課長","answer":"そういったことも、まず執行部できちんと対応要領ができることによって、それを応用した形で検討することも可能だと考えております。議会において検討するべきだと考えておりますので、職員の対応要領を参考にしていただけますと、非常に幸いと考えております。","id":"exchange-019"},{"speaker":"松本委員","kind":"質問・要望","question":"カスタマーハラスメントのマニュアルなどをつくっていただけるのですから、ハラスメントをする人こそ参加しないということが極めてよく起こる。この２点について、カスタマーハラスメントが起きやすい部門については通話録音の告知を取り入れていただきたいと思うのですが、いかがか尋ねました。","respondent":"石井コンプライアンス推進担当課長","answer":"検討を進めていく段階で、これに関しては、やはり設備投資のコストの見合いという形になってくると考えております。対応の瑕疵が生じてしまうといったことは防がなければならないという問題意識はありますので、引き続き検討課題として検討したいと考えています。","id":"exchange-020"},{"speaker":"松本委員","kind":"質問","question":"個人顧客を対象としている企業はどうしているかというと、例えば１時間なら１時間で、複数対応するという対応を取っているように見受けられます。こうしたことは、これから恐らく運用の部分で検討されると思いますが、現状の考え方についてお伺いできればと思います。","respondent":"石井コンプライアンス推進担当課長","answer":"苦情に対応するときに、複数で対応するとか、一つの組織的な対応というところであると考えております。一番の提要は、個人で対応するものではなく、組織で対応する体制を整えるということが肝要であると考えております。","id":"exchange-021"},{"speaker":"松本委員","kind":"意見","question":"カスタマーハラスメントに該当するかどうかと、職員がどう感じたかというのは別なのだというところで、毅然と対応していただければと。おかしいと申し上げていくことがあると思いますが、そこの部分はぜひとも現場の職員を守ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"経験値として、若い職員はあまり言いにくいということも出てくるではないですか。そういうことも考えられて進められたほうがいいのではないかと思うのですけれども、ご見解を説明を求めました。","respondent":"石井コンプライアンス推進担当課長","answer":"もしかしたら何らかの検討の余地はあると思いますけれども、新庁舎の移転も考えている中で、なかなか考えづらいのではないかと考えております。ですので、現行の取組をきちんとまず進めていくことが大事だと考えております。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"進歩はあると思うのですが、どうしても上司と部下の関係というのは、これから上に上がっていくときに足かせになってしまうではないですか。押す人も、これは受付の役目ですからという形でやれると思うので、職員を守るという意味でも、そうしたらどうかということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"大倉委員","kind":"質問","question":"なぜそんなことをするのかと、その辺はお考えがあるのだろうと思っていますけれども、どのように対応するのかだけ説明を求めました。","respondent":"石井コンプライアンス推進担当課長","answer":"ただ録音しますからという形で言ってしまうと、それはそれで、また相手の気分を害するようなことになってしまうと考えております。そういったことも十分考え得る部分がありますので、通話録音装置に関する設置のための要綱ですとか、内部規定みたいなものを整える予定ですので。","id":"exchange-025"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"私も通話録音機のところで少し確認をさせていただきたいのですが、電話で問合せをすると、区役所だけが特別という認識ではないのかなと思います。誰がどのような権限で、どういう場合に開示されるのかというところが公表されていくのか、その辺を教えてほしいと求めました。","respondent":"石井コンプライアンス推進担当課長","answer":"そういった情報の取扱いについては、現在、通話録音装置の設置および運用に関する要綱という形で、ルールづくりを進めてまいりたいと考えております。ホームページで公開することになってありますので、それと同じような動きで…","id":"exchange-026"},{"speaker":"新妻副委員長","kind":"質問","question":"これは通話ということなので、電話での録音ということになりますが、窓口に来られた方の対応の録音ということのお考えというのはいかがか尋ねました。","respondent":"石井コンプライアンス推進担当課長","answer":"で窓口対応というのは、電話と比較したらそういった状況は、比較の問題ですけれども少ないと考えております。両者の録音というものを同列に捉えるということは難しいと考えておりますので、またそのときにきちんと検討してまいりたいと考えております。","id":"exchange-027"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"一方で、求める側の思いというのもあって、それをどう受け止めてくれるか、言葉のやり取りというところが、すごくそこも大きいと思っているのです。どうしても区民としては、分かっているのだけれども聞いてほしいという思いもあったりしますので、引き続き。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"そこでお金の問題が入ってきてしまうと、これは優先順位が違っていませんかと私は思うので、庁舎を建て替えるのだから、いいチャンスではないですか。ということもあるので、こういうことだから、お金はこれだけ必要だという考え方になってほしいと思うのですけれども、いかがか尋ねました。","respondent":"石井コンプライアンス推進担当課長","answer":"それにつきましては、きちんと職員の教育についても取り組んでまいりたいと考えております。そういった中で、大きな意味で、東京都内全域がきちんと対等な関係に基づいた関係が築けるようにしていきたいと考えております。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"よく言われるではないですか。自分でぐっと心に残すのではなくて、そこまでのスーパー職員になってほしいなと思って、私の気持ちを意見として申し上げたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"}]},{"id":"topic-03","title":"令和６年職員の給与等に関する報告及び勧告の概要","agenda":"令和６年職員の給与等に関する報告及び勧告の概要","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"課長が決めているわけではないので、人事委員会勧告ということなので、その辺をどのように思われるでしょうか。今回の人事委員会勧告というのは多過ぎるのではないかと思うのですけれども、その辺に対してどのようなご見解をお持ちか尋ねました。","respondent":"宮尾人事課長","answer":"先ほどご説明の中でも触れさせていただきましたとおり、そこは一定の信憑性といいますか、根拠があるのではないかと考えています。しっかり重く受け止めて、真摯に職務に邁進していくということが、今まで以上に求められているのかなと重く受け止めているところです。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問","question":"この会社名というのを教えてもらうわけにはいかないのでしょうか。区民に対して説明のしようがないので、そういうことは可能でしょうか、説明を求めました。","respondent":"宮尾人事課長","answer":"こちらは特別区人事委員会のほうで、社名を出さないということを条件に、調査に協力をしていただいているものと聞いてあります。出さないということを条件に、調査に協力していただいているというところがあると思いますので、そちらについてはご理解をいただければと思います。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"配偶者等の６,０００円廃止とあって、子に対して９,０００円から１万５００円にということなのですけれども、子どもがいない場合もありますよね。そうすると、恩恵を被っていた方が恩恵を被れなくなったという理解でいいか尋ねました。","respondent":"宮尾人事課長","answer":"扶養手当、配偶者手当の関係ですけれども、委員のお見込みのとおりです。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"これは品川区独自で考えることも可能なのでしょうか。区で考えることもできるのではないかと思うのですけれども、その自由度も含めて。","respondent":"宮尾人事課長","answer":"勧告に記載されている部分につきましては、２３区共同で設置している人事委員会に基づく勧告となりますので、こちらも品川区は適用されるといいますか、これに沿う必要があると認識しています。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"例えば沿わなくても、罰則規定があるとか、財調などにすごく影響が出るとか、そういうことはあるのですか。いかがか尋ねました。","respondent":"宮尾人事課長","answer":"罰則というところまでは、今どうかというところは持ち合わせておりませんけれども、基本的には、人事委員会というのは２３区が共同で設置をしているというものですので、そこから出された勧告というのは、守っていくべきものと考えております。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"今は財調でも、それぞれの事情に合わせた内容に変えるということも、今後考えていくべきところもあるのではないかと私は思っているのです。こういう廃止になるものもあるのだということを、きちんと示すべきではないかと思うのですが、いかがか尋ねました。","respondent":"宮尾人事課長","answer":"勧告の内容が、いろいろ今回、数字も大きく変わってくるというところも出されておりますので、そういったところも含めて、今委員からいただいたものも含めて、職員にはしっかりと職制を通じて周知をしてまいりたいと考えています。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"こういう廃止とかということについては、しっかりとプラスの面、マイナスの面というのを公表してほしいと思います。そういう情勢を見て決めているということは、ホームページの中でも何かしら伝えていくべきなのかなと思うのですが、いかがか尋ねました。","respondent":"宮尾人事課長","answer":"今、いろいろご意見をいただきましたけれども、そういったところも含めて、職員の勤務の実態ですとか、職員の働きがい、働きやすさという視点で、公表できるものはしっかりと公表していくという姿勢をこれからも持ち続けていきたいと思っています。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"だから今回、録音機能を持たせるのですとかという説明をきちんとして、区民の方々には理解を求める。職員の方々がどういう仕事をされていて、給料の細かいところまでは必要ないのかもしれないのですけれども、別途考えていただきたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"}]},{"id":"topic-04","title":"令和６年１０月２７日執行 衆議院議員選挙の結果","agenda":"令和６年１０月２７日執行 衆議院議員選挙の結果","exchanges":[{"speaker":"西本委員","kind":"質問","question":"投票率が品川区は９番目とか、１１番目とか、すみません、１番はどこなのでしょうか。自分で調べてよということかもしれませんが、もう少し有権者が審査しやすいような工夫は何かできないかなと思うのですが、その辺はいかがか尋ねました。","respondent":"今井選挙管理委員会事務局長","answer":"文京区が６４％、それから千代田区が６０％、大体この並びは変わらないところだと考えています。小選挙区ごとに実施されるものですので、国民審査の周知方法については改めて検討していきたいと考えています。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"今回、選挙違反が多かったと思うのです。実態はどうだったのか、例えばどのぐらいあって、どういう現状だったのか説明を求めました。","respondent":"今井選挙管理委員会事務局長","answer":"まず、違反警告というのはございませんで、警察からの情報提供が２件あった程度だと思います。例えばこういうポスターはいかがですかということも含めまして、お問合せは前回の都知事選より相当少なかったというのが現状です。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"証紙が貼ってあれば、内容はどうでもいいのです。これは意見として言わせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"２点お伺いします。同じような形でやっていただきたいということの要望とともに、また対応がし切れなかったとか、課題等がありましたら教えてほしいと求めました。","respondent":"今井選挙管理委員会事務局長","answer":"は投票支援カードを示されなくても、これまでどおり、車椅子または代理投票などを含めた支援をさせていただいたです。入場整理券に同封する形の中で、もう少しこれの運用につきまして、現場の選挙従事者等に確認しながら進めていきたいと考えています。","id":"exchange-042"},{"speaker":"新妻副委員長","kind":"確認","question":"右下のところにもう１枚、違うポスターというのでしょうか、それが貼ってあるところと貼っていない掲示板があったのです。なので、その違いはなぜかというのを確認したかったのですけれども、説明が悪くてすみません。","respondent":"今井選挙管理委員会事務局長","answer":"あちらのポスターも、実際には選挙のための４０・３０のポスターと、政党名の演説会などの告知も併せてやった掲示物もあったのかなと考えています。私どものほうで、また情報等をいただきましたら、改めて選挙管理委員会として確認していきたいと考えています。","id":"exchange-043"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"そうしたら、またポスターに関しては、後で個々に確認させていただこうと思います。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/837879?Template=document&Id=6871#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":40862,"voices":109}},{"id":"r06-20241107-14","meetingId":"r06-cm11","date":"2024年11月7日","dateIso":"2024-11-07","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時５１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"松永委員","kind":"質問・要望","question":"私から１点ですが、平面計画の１３番の「喫煙所を必ず作ってほしい、子ども食堂や現在の屋上の機能を持たせてほしい」というところで。実際できたらいろいろな方も来られるので、現在の状況を確認でお答えいただければと思うのですが、いかがか尋ねました。","respondent":"小林新庁舎建設担当課長","answer":"屋外に設置する場合につきましては、基本的には屋外設置のところで、今お話がございました煙等の影響がない場所を検討している最中です。引き続き検討を進めてまいりたいと考えているところです。","id":"exchange-001"},{"speaker":"松永委員","kind":"質問","question":"屋外になりますと恐らく大井町駅から出て北口のほうになるのでしょうか、それとも区庁舎の敷地内にということでしょうか。そのご検討があれば説明を求めました。","respondent":"小林新庁舎建設担当課長","answer":"今、区のほうで検討しておりますのは、いわゆる区庁舎の建設が予定されている敷地の中で設置ができないかどうかを含めて進めているところです。","id":"exchange-002"},{"speaker":"新妻委員","kind":"質問・要望","question":"当初この委員会でも１３地域センター管内での説明会の開催を求めさせていただきましたが、これがどうだったのかという認識をお伺いしたいのと。区民が出されたアンケートをどこで知ることができるのかというところを、１つ確認させてほしいと求めました。","respondent":"山下新庁舎整備課長","answer":"今回のオープンハウスの実施結果の総括といいますか、受け止めというところですけれども、冒頭に申し上げましたように。今回、行財政改革特別委員会で報告させていただいた後、区ホームページ等で新庁舎整備の部分でご報告をできればと考えています。","id":"exchange-003"},{"speaker":"新妻委員","kind":"質問","question":"今、ＪＲの再開発のほうが進んできて大きな建物が２棟建っているということで、中にはそこが区庁舎なのかというような声も聞かれています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"筒井委員","kind":"質問","question":"それとも基本的には飲物中心で、食事はせいぜい軽食程度の提供しか考えられていないのか。どのようにカフェという内容をお考えなのか、現時点で分かる範囲で説明を求めました。","respondent":"小林新庁舎建設担当課長","answer":"カフェの内容ですが、文字のとおり食堂ではないというところで、基本的には飲食の中でもいわゆる飲物を中心としたことを考えているところです。関係する所管と連携を図りながら、中身については引き続き検討している最中というところでご理解いただければと思っているところです。","id":"exchange-005"},{"speaker":"筒井委員","kind":"質問・要望","question":"なるべくご意見いただいた区民のご要望も取り入れた形にしていっていただけたらよいのかなと思いますので。私も度々質問していることかと思うのですけれども、その辺りのお考えをお知らせください。","respondent":"小林新庁舎建設担当課長","answer":"品川区らしさですが、現在は実施設計という設計の深度化を図っている最中です。そういうところをうまく表現し合いながら、内外装材の例えば素材であったりなど、活かしていければと検討を深めているところです。","id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"といいますと、単純にデザインとか外観だけではなくて、いろいろ今ある品川区の地域資源とかを総合的に表現して、全体として品川区らしさというようなお考えでよろしいか尋ねました。","respondent":"小林新庁舎建設担当課長","answer":"実施設計を行っている中では、やはり品川区らしさは非常に幅広くあると認識していますので、何か１つに特化するということではなく、様々な要素をちりばめながら、外装の計画とか、あるいは内装の仕上げ材の計画とかを進めているところです。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それと、８月に伺ったときに、議場の中が物すごく暑くて、エアコンを入れられないのですという話をされていました。無線がぱっと切り替えられるような仕組みになっているのか、していただきたいという趣旨ですけれども、この２点を確認させてください。","respondent":"小林新庁舎建設担当課長","answer":"空調機器等につきましても、快適な空間を形成していきたいと考えて設計を進めているところです。事前に周波数をしっかり把握した上で、混線がないような形のシステムが導入できるか等につきまして、現在検討のほう進めているところです。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"それはやってはいけないことなのかどうか分からないのですけれども、今回そういったことがあったので、ぜひそれはお願いしたいということです。窓ガラスの部分を全部覆い隠して、ほとんどそういったことができないということが豊島区議会ではあるということは以前にもお伺いしましたので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"例えばＪＲのところにマクドナルドが入れば、それは新庁舎にマクドナルドを入れないよねというのがあるのではないですか。コンビニだったら、例えば今のヤマザキデイリーストアはあの程度でも参加してくれるコンビニではないか尋ねました。","respondent":"小林新庁舎建設担当課長","answer":"カフェの幅ですが、具体的に検討を深めている最中ですので、これといって具体的な想定についてはまだ引き続き検討中かと思ってあります。１つの話としましては、他との差別化を含めて引き続き所管と検討を図りながら進めてまいりたいと考えています。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう意味でも、今の時代というのは何様式というものでこうやって設計をされていっているものなのですか。それと、この区庁舎というのは何様式で設計されているものなのですか、説明を求めました。","respondent":"小林新庁舎建設担当課長","answer":"窓ガラスの部分についてある程度日射を遮るような形の建物形式にするとかいうことが１つの建築の中のトレンドになりつつあるのかなと思ってあります。二、三十年とか１０年の周期の中で様式というかデザインのトレンドというのは変わってくるものかなとは思っているところです。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問","question":"品川らしさのつくり方というのは、先ほどいろいろなソフトを入れていくというか、中でやっていくしかないのでしょうか。みんながそれこそそこに行ってみたい、見てみたいとかという中のところも含めて、そういう工夫はこれから多少できるのか尋ねました。","respondent":"小林新庁舎建設担当課長","answer":"あるいは愛着を持っていただきたい建物ということでデザインを進めておりまして、また、実施設計を進めてあります。そのご期待に応えられるような形としてしっかりと設計を進めてまいりたいと考えています。","id":"exchange-012"},{"speaker":"松永委員","kind":"質問","question":"１点目は、駐車場について伺いたいのですが、一般車との割合はどのくらいになるのでしょうか。大体２時間無料とかであるのですけれども、その辺どういった形で駐輪の料金を取るのか取らないのかということで、そのところだけ伺いたいと思います。","respondent":"小林新庁舎建設担当課長","answer":"駐車場ですが、トータルとしては１５０台を整備する上で、今の計画でいきますと１１０台ぐらいを公用車等で使う予定で考えてあります。今後どういった形で整備していくかというところについては検討していますが、課金等も含めて、様々な案を周辺の状況を鑑みながら検討していま…","id":"exchange-013"},{"speaker":"こしば委員","kind":"質問","question":"配置計画のことでお聞きしたいのですけれども、広町全体の昼間人口がおおよそ５万人強であったと前に伺ったと思います。南側への、要は大井町全体の回遊性についてのご意見とか、アンケートにそういったものはあったのか尋ねました。","respondent":"小林新庁舎建設担当課長","answer":"逆に大井町全体に対する回遊性については、見ている方の中ではご意見として直接は頂戴していないところかなとは思ってあります。隣地である広町、ＪＲが整備するエリア、あるいは大井町全体としての回遊性の向上についても地区計画の中でしっかりと位置づけているところです。","id":"exchange-014"}]},{"id":"topic-02","title":"行政のデジタル化に関すること","agenda":"行政のデジタル化に関すること","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"それから、次のＤＸ推進基本計画の策定の検討に関してスケジュールおよび方針の方向性などがございましたら教えてほしいと求めました。今後の利用拡大に当たって、現在の検討状況、例えばどういうことに活かせるかとか、お考えがあればお聞かせほしいと求めました。","respondent":"横田デジタル推進課長、西澤ＤＸ戦略担当課長","answer":"このようなことで、全ての方がデジタルの恩恵を受けるという考えに基づいてこれからもＤＸを推進してまいりたいと考えているところです。いろいろ考えているところでございまして、まだ実施していないのですが… 追加要件に対応できなくてシステムが塩漬けになってしまうとかといった過去の反省を活かすというか、過去の反省から対策を考えました。今回の案件に関しましては、アジャイル開発手法の導入を取り入れることによって…","id":"exchange-015"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひ区民の皆様それから行政内の皆様からの様々な要望を受け止めて盛り込んでほしいと求めました。もう１つ、これについての概要と、あと品川区での状況とかが分かれば説明を求めました。","respondent":"西澤ＤＸ戦略担当課長、横田デジタル推進課長","answer":"令和６年度からはＤＸの人材育成方針の策定をしたいと考えておりまして。２つ目の電子決裁についてですが、財務決裁率のほうが４０.４％というところで、ここは徐々に上がっていくと考えております。 ２点目のスマホ教室の関係ですが、ホームページでこの日にここで実施するよといった周知の掲載、そういったことで連携をしております。総務省の事業の周知の関係ですが…","id":"exchange-016"},{"speaker":"山本委員","kind":"提案","question":"全廃できるのであれば全廃を目標にしていただきたいなというのは文書決裁のほうで思いましたので、これは要望といたします。これは昨年の決算特別委員会以来私も度々拡大をご要望させていただいている中で、さらに広げてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問","question":"そうすると、社員の紙の量というのはこれぐらいで、イトーキの場合は紙が９分の１に減ったと説明を受けたわけではないですか。空いたところをどう活用していくかとか、庁舎はどんどん建っていくわけだから、どうしていくのか尋ねました。","respondent":"山下新庁舎整備課長","answer":"新庁舎ができたときに供用が開始される時点でそれがうまく活用できるように取り組んでいかなければならないと考えております。そういったところはデジタル推進課と連携しながら、日々新庁舎の整備の内部の検討において取組を進めているところです。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問・要望","question":"ＤＸですけれども、東京都との連携事業ということで確認させていただきたいのですが、共通化ということもやっていると思います。いま一度、現在東京都と連携している内容をお知らせください。","respondent":"横田デジタル推進課長","answer":"システム標準化の関係でどのように進めたらよいかという相談をしていたりとか、あとはデジタル人材をどう確保していくかという相談をしています。先ほどのスマホ教室の関係で、高齢者スマホ教室ですとか、障害者の関係のスマホ教室ということで連携をしています。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"といいますと、今、教えていただいた内容以外は、基本的に品川区、あとはもう独自でＤＸ、区でしっかり基本方針とか計画を立てられて、区のお考えや努力でしながわＤＸを進めていかれるということでよろしいか尋ねました。","respondent":"西澤ＤＸ戦略担当課長","answer":"先ほどご質問いただいた件ですが、ＤＸ基本方針は区や他の自治体といったところも踏まえながら検討を進めていくところになりますので、品川区としての考えと他区の状況も見ながら検討していくものになります。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ進めていってほしいと求めました。もう１点、１３ページで、今回のシステムダウン対策訓練はどのような内容なのか尋ねました。","respondent":"横田デジタル推進課長","answer":"システムが使えなくなったときにどのように対応するのかのシミュレーションというか、窓口で対応するとか、そういったことを一連の流れとして訓練しているものです。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。住民の情報を扱うということなのですけれども、あと、もっと踏み込んで、サイバー攻撃を受けた場合の想定とかもされているのか尋ねました。","respondent":"横田デジタル推進課長","answer":"この日とは別にまたサイバーセキュリティ訓練も実施しておりまして、例えば情報セキュリティ担当が外部の研修を受けていたりですとか、それを持ち寄って、区内一斉防災訓練の日に内部で訓練をやっていたりとかということはやっております。","id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問","question":"この前、議会改革推進会議の広報部会ですか、二元代表制の下で品川区役所の電子申請システムを議会事務局が使ってよいのですかという話をしたら。この２点を説明を求めました。","respondent":"西澤ＤＸ戦略担当課長、横田デジタル推進課長","answer":"はデータベースとのリアルタイムでの連携が必要だったりとか、まず要件を整理した上で提供できるかの判断が必要になります。１.５か月でできたというものになりますので… こちらですが、このシステムは職員用というか、ＬＧＷＡＮのルール上は職員しか利用できないとなっているところです。詳細については、また後ほど我々と区議会事務局で話合いをさせていただければと思います。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"確認","question":"当然やっているものもあると思うのですが、そういうことを考えると、オンラインで確認が必要だというのはどういうものをおっしゃっているのか。そういう精査が必要なもの、慎重であるべきだという、それはどういったものを指すのか逆に説明を求めました。","respondent":"横田デジタル推進課長","answer":"内製開発で重要なのは、あとは結構要件の厳しい災害対応システムとか、そういったものとのリアルタイムのデータ連携はかなり厳しいと感じております。もちろんセキュリティ面とかに考慮する必要はありますが、やれるポテンシャルはあると考えております。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"提案","question":"今回も１０ページを見ると、その中で配布状況をリアルタイムに確認できたりとか、そういったことも自由に設定ができているようです。何かこういうことはできないのですかということを私たちのほうからも提案をさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"つる委員","kind":"質問","question":"１７ページと１４ページに関連してなのですが、これのやり方、区で今いろいろな所管でアプリを活用した取組がありますよね。そこを教えてもらえますか。","respondent":"西澤ＤＸ戦略担当課長","answer":"ご質問いただいた電子申請の件に関しては、年に２回、勉強会というかセミナーを開いて、所管に対して構築方法や操作方法を教育しています。所管とその所管が契約した事業者と一緒にやっているものになっております。","id":"exchange-026"},{"speaker":"つる委員","kind":"確認","question":"スマホ教室はスマホの使い方になるのですか。各所管についてどういう連携しているのかなという確認がしたかったのですが、そういうすみ分けでこれからもやる、そこだけ確認させてください。","respondent":"西澤ＤＸ戦略担当課長","answer":"委員ご認識のとおりでございまして、電子申請とかは我々のほうで導入しているので我々のほうで研修とかできるのですけれども、ベンダーが独自に入れているアプリケーションについてはベンダーと所管でやるというのが一般的というか、一番効率的なやり方だと考えております。","id":"exchange-027"},{"speaker":"こしば委員","kind":"質問","question":"これからお聞きしたいのは、必ずしも区民の利便性の向上、または区からすると決して効率化とは言えないようなことなのかもしれません。そういった方々への何かアプローチはあったのか尋ねました。","respondent":"西澤ＤＸ戦略担当課長","answer":"今回Kintoneのほうで受付対象外のリストの作成を、クエリを使用してリストアップすることに成功しました。はおじいちゃん、いずれかのほうだけ送るというのをきちんとメールでも回答するような方法にしたので、そこら辺は問題ないと考えております。","id":"exchange-028"},{"speaker":"西村委員","kind":"質問・要望","question":"私も２点お伺いをさせてください。その辺りで見えてきたものを伺いたいのと、６０件ある要件の中で職員の皆様からどんな相談が来ているのかという相談内容も伺えればと思います。","respondent":"西澤ＤＸ戦略担当課長","answer":"それをし終わった後に、実際使う児童センターに対しても説明会を設けて、そこでデモすることによって混乱なくできたと考えております。そういった内容を盛り込んで、今年度中にデジタル人材育成の方針を設立したいと考えております。","id":"exchange-029"},{"speaker":"西村委員","kind":"質問","question":"１点だけ伺いたいのですけれども、１７ページで、電子申請サービスのトップ５の中がほとんど子育てで、１つだけ帯状疱疹ワクチンが入っています。この辺りはどのように分析されているかお伺いさせてください。","respondent":"西澤ＤＸ戦略担当課長","answer":"４０代、５０代というところで、デジタル的にリテラシーの割と高い方々が多いので申請件数が伸びているのかなと考えています。帯状疱疹ワクチンのところはあまり把握していないのですが、やはり子育て世代が数を伸ばしているのはそういった理由があるのかなと考えております。","id":"exchange-030"}]},{"id":"topic-03","title":"ウェルルビーイング・ＳＤＧｓ推進ファンド事業実施状況","agenda":"ウェルルビーイング・ＳＤＧｓ推進ファンド事業実施状況","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"甲乙つけ難いものがたくさん出てきた場合に、しかも最低基準を全部突破してしまうようなものが出てきた場合は、どういった観点から判断をされるのか説明を求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"応募事業者が今後多く出てきた場合の対応についてというご質問と捉えております。今回実行委員会の中で二次審査を行ってまいりますが、今後、事業者数の上限を設けるということは今後検討していきたいと考えております。","id":"exchange-031"},{"speaker":"あくつ委員","kind":"確認","question":"今回に関しては、特に初回ということでそういったものは設けていないということでよかったですか。そこだけ確認させてください。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今回の応募につきましては、先ほど答弁させていただきましたように、上限額でしたり、あとは事業者数、助成対象事業者の数というものをあらかじめ決定しているものではございません。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"確認","question":"では、最後にもう１点だけ確認させください。そこについては当然プレゼンというか、今回は書類段階においては予算の規模というものは一次審査では確認していないということでよろしいか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"５００万円を上限とする範囲で、予算が５分の５だと、この上限５００万円を申請してくるところもございました。その事業の実施規模に応じて１００万円以下の申請額で応募してくる事業者も複数ございました。","id":"exchange-033"},{"speaker":"山本委員","kind":"提案","question":"もともと示された要件を満たしてない企業が５つ、結構多いなと思いましたので、ご確認をさせていただきたいというところと。２年目もどうするのかなというのが気になっていたところだったのですけれども、来年度に向けたお取組の中でのお考えがさらにあれば説明を求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"２年目以降、継続していくのかというご質問ですが、次年度以降も継続していきたいと考えているところです。それに当たっては、今年度の反省点を活かしながら改善についても検討していきたいと思っているところです。","id":"exchange-034"},{"speaker":"山本委員","kind":"質問・要望","question":"それぞれご回答どうもありがとうあります。１点、連携していただいて、次年度以降より参加していただけるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/118715?Template=document&Id=6873#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":34285,"voices":89}},{"id":"r06-20241108-19","meetingId":"r06-cm11","date":"2024年11月8日","dateIso":"2024-11-08","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ４時１１分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/949666?Template=document&Id=6875#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":876,"voices":5}},{"id":"r06-20241111-10","meetingId":"r06-cm11","date":"2024年11月11日","dateIso":"2024-11-11","committee":"議会運営委員会","time":"午後 １時００分～午後 １時０４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759442?Template=document&Id=6877#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":2017,"voices":14}},{"id":"r06-20241120-10","meetingId":"r06-cm11","date":"2024年11月20日","dateIso":"2024-11-20","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"特別研修ですけれども、場所はどこなのかというのと、議会のほうでやるということで、そこに区もどうぞということなのか、それとも逆なのか、その辺が分かれば説明を求めました。","respondent":"渡辺議長","answer":"第三庁舎６階の講堂で予定しております。１２月２６日木曜日、午前１０時から正午、第三庁舎６階ということで予定しております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"確認","question":"本意見交換会を通じて、本会議における討論をめぐる申し合わせ確認事項、今後どう検討を進めていこうと考えているのか伺いたいと思います。それも伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"西村委員","kind":"質問・要望","question":"午後に意見交換会をさせていただきたいという趣旨でご案内を送らせていただきましたので、意見交換会で皆様のご意見をいただきたいと思っています。もう１点、こしば委員が９月１８日に、ご提示させていただきたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"進め方についての意見も出させてほしいと求めましたし、前回こしば委員が口頭で訂正したものということで、よろしいということですね。分かりました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759442?Template=document&Id=6879#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":6197,"voices":31}},{"id":"r06-20241125-6","meetingId":"r06-cm11","date":"2024年11月25日","dateIso":"2024-11-25","committee":"区民委員会","time":"午前１０時００分～午後 ０時３２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件整理しています。","topics":[{"id":"topic-01","title":"第９６号議案、指定管理者の指定","agenda":"第９６号議案、指定管理者の指定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"報告書についてまず１点お伺いするのが、改めて本委員会のメンバーの方が採点するということでよろしいのか、伺いたいと思います。改めてこの施設の目的についても伺いたいのですけれども、改めて、この事業を行っている目的とか理由について改めて伺いたいと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"２点目、創業支援の目的・理由についてです。地域に雇用が生み出されるですとか区民が増える、そういったことを期待して、この創業支援をやっているところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"確認","question":"３階のホールの運営実績について伺いたいのですが、稼働率等、どのような規模の会社がどのような目的で使用する感じなのでしょうか。３階のホール運営にかかる経費で、区に収入として入るのか、それともその一部ということかを確認させてください。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"令和５年度につきましては７５％弱の稼働率です。こちらにつきましては、運営経費を除いた、差し引いた分の粗利が区のほうに歳入として入ってくるところです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。指定管理でそれを請け負う企業のメリットは何なのかというのが分からないので、そこら辺はどう考えればいいのでしょうかということを伺います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"指定管理事業者とは年度初めに年度協定を結んでおりまして、そこでインセンティブについての考え方の協定を結んでいるところです。３階につきましては、指定管理者にとってもメリットがある、そういった協定となっているところです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"この事業者の概要について伺いたいのですが、ＳＨＩＰに事務所があるので、ＳＨＩＰ以外で行っている事業は何かあるのでしたか。ＳＨＩＰ以外で行っている事業は何かあるのですかということと、現在、事務局長は区の元部長だということで間違いないか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"品川区としましてはモンゴルの人材活用などを行っていますので、そういった方たちの定着支援などを行っている、そういった事業を実施しています。〔「従業員数は何人いるのですか」と呼ぶ者あり〕 従業員数は、今、アルバイトを含めて２０名弱といったところです。それから、事務局長の元所属部は、文化スポーツ振興部です。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"現在、いわゆる元部長級あるいは副区長だった方がいるというところで、なおかつ事務所はＳＨＩＰの中にあるということのようです。３階がマグネットスタジオで、４階はビジネスクラブということですけれども、もしつかんでいるとしたら私たちに説明を求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"品川ビジネスクラブとマグネットスタジオにつきましては、共同事業体で実施するという協定書を結んでいることは区でも認識しておりまして。それから４階につきましては、創業を希望する人向けの伴走支援ですとかセミナー、区としてもそういったところを把握しています。","id":"exchange-005"},{"speaker":"安藤委員","kind":"提案","question":"４階と３階、でも同じ施設なわけですから、どっちもお願いしますというようなことを品川区としては提案しないのでしょうか。伺いますとの意見を述べました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"それから、これは事業者のほうが考えることですので、これは応募する側が共同事業体を選択してきたと。そういったところとして考えているところです。","id":"exchange-006"},{"speaker":"おぎの委員","kind":"提案","question":"８ページの下のところの委員の意見で、自主事業などについての提案が具体的であり、今後の展開に関して、質疑でも明確に回答があったため高評価と書いてあるのですけれども、どういった自主事業等についての提案があったのか、お聞かせほしいと求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"ビジネスクラブからは、スタートアップの成長していく企業への伴走支援も新たに実施していくという提案ですとか、そういったご提案がございました。それからＯＢの方に交流会に参加していただく、そういった交流会を実施していく、そのような提案がございました。","id":"exchange-007"},{"speaker":"おぎの委員","kind":"提案","question":"様々な提案がなされたようで。品川区としても、こうやりたいという方向性に沿った形で、いろいろお互いに助け合ってできるような形になっているということなのか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"委員のおっしゃるとおりと考えております。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"一方で、労務環境についてはどうかというところをお聞きできればと思います。別紙２の６ページで、もし課題があれば、お聞きできればと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"５年に１回行っているところですけれども、そちらについても特段ご指摘はなく、十分大丈夫だという評価はいただいているところです。委員から、現行の体制と同等の体制で提案しているので、十分安定的に施設を運営できる体制とみなせるというような意見はあったところです。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。ここについては問題視され、より重要視していかなければいけない点だと思われますので、引き続きより一層適正な指定管理をお願いしたいと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問","question":"２点あって、まず１点目が、ビジネスクラブ、共同事業体の住所が指定管理の住所と一緒なわけですよね。これは４階の事務室をお借りして事業をずっとされているということでいいのかお聞きしたいのと、この不安を、説明を求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"こちらは、ビジネスクラブに事務室の１室を貸し付けているといったところでございまして、毎月賃料を支払っていただいているところです。２点目ですが、区としては十分認識しているところでございまして、これから区が求める改善内容ですとか対応していただきたい内容を。","id":"exchange-011"},{"speaker":"石田（し）委員","kind":"提案","question":"決まった後に、それは我々提案していないではないですかと言われてしまったら、それまでではないですか。だから、そこをどうやって皆さんの思いをきちんと指定管理者側と連携できるのかが必要だと思うのだけれども、その点は大丈夫なのか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"ただ、点数としましては７９％の得点率を得ているところで、委員の皆様からはおおむね任せて安心だというご意見はいただいているところです。時には区のほうも、そのような形で解決というか、対策としてはとっていきたいと考えているところです。","id":"exchange-012"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それはあってしようがないではないですか。そこは、例えば１０年が経過しているのにハード面での計画の記載がない、ちょっとクエスチョンではないか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"物価高騰があってもきちんと収支を合わせていきますという表明ですというご説明があったので、大幅な変更はなくてもまだ３期目はやっていけると。ただ、ご指摘のとおり、協議のほうは、そういった形できちんと進めてまいりたいと思いますので、よろしくお願いいたします。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問・要望","question":"そこを教えていただきたいのと、これは確認ですけれども、選定予備委員は４人とも役所の方ですよね。その辺も含めて、答弁しにくいとは思うのですけれども、いかがか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"合計点が３１６点と２５２点ということで、点数を合わせた合計を踏まえて、問題なく事業者Ａでという形で決まったところです。こちらは審査基準にのっとって公平に実施しているところでございまして、こちらは審査にのっとってそれぞれが実施しているといった回答とします。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"そこを伺ったので、平均以上というか、４００点満点中３１６点と２５２点で、差がついたからということですけれども、差がついたわけですからね。公平・公正にされているという答弁なので、公平・公正にされているのですからね、よく分かりました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"おぎの委員","kind":"意見","question":"いろいろな支援とか相談事業とかをやっているからどうしても、この４階の事業は、どちらかお聞かせいただけたらと思いますとの意見を述べました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"年間を通していろいろなセミナーをするですとか専門家を配置するとなると、やはりそれなりのコストはかかってしまうと認識しています。３Ｄプリンターの台数を増やして、いっぱい使っていただくといっぱいお金が入ってくるので、そういった努力などはしていただいているところで…","id":"exchange-016"},{"speaker":"おぎの委員","kind":"意見","question":"どうしても一番最初は一番いろいろな資金がかかるところですので、そこを助けるのだという意味合いというのはすごく理解しています。税金が区に入って戻ってくるわけですので、なるべく赤字ではないようにいろいろ知恵を出していただいて、運営していただいたらと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"吉田副委員長","kind":"提案","question":"それともう一つ、産業振興事業や自主事業についての提案が具体的でありの、伴走支援などが提案されていてということだったのですけれども。具体的な明確な回答があったということであれば、その辺がどのように明確に回答されたのかについてもお伺いしたいと思いますとの意見を述べました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"それから３点目、ビジネスクラブが具体的にどのような伴走支援を提案してきたのかといったところです。その事業をどのようにやっていくのかというものの詳細な説明があったところですことから、この具体的なという表記とさせていただいたところです。","id":"exchange-018"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ばかりかどうか、区民に対しての見え方とか、そういう点でもよくないのではないかなと思います。これは要望にとどめておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"せお委員","kind":"質問・要望","question":"何も言わないのもあれなので。そういった文言があるところを今後どうしていくのかなと思っていたので、協議のほうよろしくお願いしますという、それだけ要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"区民に対して明確な説明ができるような形にしていただきたいのと、ずっと求めてきましたので、今後はぜひ活かしてほしいと求めました。賛成です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"安藤委員","kind":"意見","question":"中小零細企業や個人事業主などに軸足を置くべきで、大ホールに象徴されるように、違うのではないかと。そこに利益を上げることを目的とする株式会社に指定管理をさせるというのは、さらにそれをゆがめるものであるため反対ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"}]},{"id":"topic-02","title":"令和６年陳情第５４号、品川区行政と事業者の懇談会を行う陳情","agenda":"令和６年陳情第５４号、品川区行政と事業者の懇談会を行う陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"区が分かるのかどうかというのはあるのですけれども、いわゆる大企業はこれぐらい、中小企業はこれぐらいみたいなものは分かるのですか。もし分かるのであれば、イメージしたいので、伺いたいと思います。","respondent":"小林地域産業振興課長","answer":"経済産業省と総務省が実施しているものを、事業所数でいうと１万９,８９７というのが最新の数字でございまして、約２万弱ぐらいです。その中で大体７割から８割ぐらいは従業員が１０人から１９人以下、２０人以下といった事業者が多いというふうに区としては認識しています。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"それとはまた別に、事業者の生の声を聞くことについて、効果みたいな大事な点を書いておられます。必要だと思うのですけれども、有益がゆえに必要だと思うのですが、いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"１対１ということで、説明会ということであれば、そういうものがあります。令和７年度・８年度という中で経済状況が変わってくれば、次にどういう対応策を打っていくべきかというのをしっかり考えていきたいと考えています。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"あるいは求められているものを区として立てていく上で、様々、課長がおっしゃったような相談窓口は確かにあります。最初に課長がおっしゃったような窓口では不十分だと私は思うのですけれども、そういった点で必要だと思うのですが、いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"相談をどういう対応でやっていくかですが、例えば８割ぐらいは資金繰り、課内も全部含めて把握しているものです。もちろん１件１件全部私が把握するというのは難しいのですけれども、統計的なデータも見ながら、しっかり対応していきたいと考えております。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"それとも、ないという立場なのですか。そこら辺、伺いたいです。","respondent":"小林地域産業振興課長","answer":"２,４９２件、１件１件、２,４９２通りの相談があるわけです。先ほど申し上げた説明会というような形で、創業支援センターなども活用しながら、いろいろ幅広く意見を聞いていきたいと考えております。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"質問したことにお答えいただいていないので、お答えいただきたいのですけれども、ない。少しはあるとお考えなのですよね。","respondent":"小林地域産業振興課長","answer":"今申し上げたような第一、第二、第三という形で取組をやっております。先ほど２万事業者というお話をしましたが、次の政策に活かしていくような、そういう取組をしっかりやっていきたいと考えております。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"少しどころか、ぜひ議会としても区に求めていく必要があると思うので、皆さんもぜひそういう立場に立っていただきたいなと私は思っています。把握しているのか、おられないのか、お伺いしたいと思います。","respondent":"小林地域産業振興課長","answer":"私もよく説明で申し上げるのですけれども、恐らく２割程度、個人事業主の方もいらっしゃいます。フリーランスと言われる方あるいは個人事業主の方の対応というか、いろいろそういう相談対応というのはしっかりやっていきたいと考えています。","id":"exchange-028"},{"speaker":"安藤委員","kind":"提案","question":"これはすばらしい提案だと私は思っておりますので、求めがあれば、そうした懇談会をぜひ積極的に考えていただきたいなと思います。意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"おぎの委員","kind":"質問","question":"やはり暮らしに直結してきますので、現状の把握はすごく大事だと思います。そういった情報というのは今持たれているのでしょうかというのが１点と、以上２点、お願いします。","respondent":"小林地域産業振興課長","answer":"２点目ですけれども、こういったお知らせとかこういう補助金を受け付けていますよというようなご案内とか、そういうものは発信しております。先ほど区内に２万事業者ある中で、発信の回数ということも含めてですけれども、十分対応していきたいと考えています。","id":"exchange-030"},{"speaker":"おぎの委員","kind":"質問・要望","question":"区内も２０人以下の事業者が多いということで、いろいろ工夫して、さらに広めていただきたいなと思います。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"ゆきた委員","kind":"確認","question":"その中でも１５％から２０％、年間では恐らく６００件ぐらい、個人事業主とも個別で１件１件相談を受けているということを確認できました。その対策、そういった方はしかるべき所管のところに手間なくスムーズにつないでいってほしいと求めましたが、現状をお聞きできればと思います。","respondent":"小林地域産業振興課長","answer":"例えば創業支援センターの中で税金、その先、例えばこれは税務署のほうに直接ご相談できる窓口がありましてということもあるかと思います。いろいろなところとも連携しながら、より相談に、ニーズに応えられるようにということで対応していきたいと考えております。","id":"exchange-032"},{"speaker":"ゆきた委員","kind":"確認","question":"専門家につないだり、あと所管の異なるところとも柔軟な対応をされている姿勢を確認させていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"石田（し）委員","kind":"意見","question":"今いろいろご説明いただいて、いわゆる個別相談と、いろいろ補助金等の説明会などをやって、幅広く区民、区内企業の人たちの悩み相談、また、ご意見等は区でもしっかりと聞いているというのが前提なのかなと思うのですが、まずそこを説明を求めました。","respondent":"小林地域産業振興課長","answer":"やはり１対１の、その中でどう対応できるか、ご相談を聞くということだと考えています。１件１件、ご案内して説明するという場面も併せ持ちながら、併せてやっていくということを我々としては基本線でやっていくべきだと考えております。","id":"exchange-034"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それは、たしか相談すると、経営相談とかそういう枠組みでやっているではないですか。そこはチャネルを少し幅広く持ってもらって、今もやられているのかもしれないけれども、例えば何でも相談みたいなものがあるではないか尋ねました。","respondent":"小林地域産業振興課長","answer":"説明会という話はしましたけれども、セミナーとか創業支援センターでも、そこに講師をお呼びしてというようなやり方もやっております。いろいろ我々も考えながら、受信と発信といいますか、そういうところをしっかりやっていきたいと考えています。","id":"exchange-035"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望で終わりますけれども、１点目の、それはそうだと思うのです。だから、多くの方に相談してもらえるよというのを何らかの形で出してもらえるといいのかなと思うので、ぜひそこは工夫してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"今、質疑を伺っていて、第一の窓口になる方は、それこそ各委員からの求めをクリアする窓口の人はすごく大変なのではないかなと。今の質疑を伺うと、どういうことを課長として求めておられるのか、伺いたいと思います。","respondent":"小林地域産業振興課長","answer":"対応できるのですが、毎年毎年業務を変えていって、少しずつ対応できる範囲を増やしていってというようなことを特に意識してやっております。例えば３年、４年たってくるとほぼ一通り説明できるようにという形で…","id":"exchange-037"},{"speaker":"吉田副委員長","kind":"質問","question":"今のお話の中で、どうしてもやはり中小事業者は企業みたいな感じですけれども、この陳情を出されている方はフリーランスの方ですよね。研修などもされているのでしょうか、区の姿勢としてはそういうことも必要だと思うのですが、その点についてはいかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"創業支援センター、例えばＳＨＩＰも含めてですけれども、中小企業診断士の方というのは基本的にそういうところでの対応の経験というのもあります。区内の施設の中の連携もとりながら、できるだけいい相談対応ができるようにということで、心がけていきたいと考えています。","id":"exchange-038"},{"speaker":"吉田副委員長","kind":"質問","question":"１人でまずは事業を始めるという方と、直接会った人が難しくても、誰かほかの人がフォローできるような体制はできているということなのでしょうか。それとも、まだ課題はあるとお考えか尋ねました。","respondent":"小林地域産業振興課長","answer":"基本的にはそういう対応ができていると考えていますけれども、いろいろ新しい課題というのも出てきますので、それは中小企業診断士を持っているようなスタッフも含めて、レベルアップは引き続き図っていきたいと考えています。","id":"exchange-039"},{"speaker":"藤原委員","kind":"質問・要望","question":"個人事業主の方からお話を伺って、産業経済費、いろいろな方のご意見を伺って質問してきたつもりです。質問ではなく、切なくなってしまったので、すみません、思いを１人の議員として言わせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"せお委員","kind":"質問","question":"結論を出すで、不採択でお願いします。引き続き、そういうちょっとずれたお話でも丁寧に対応できるような体制を整えてほしいなと思って、今回の陳情は不採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"個人事業主、家族経営者の事業者等からも個別で、もちろん懇談で１件１件の相談を受けているということを確認できました。さらに進めていくという姿勢を確認できましたので、あと、これはこの中では難しいなという相談にも柔軟に対応していくということを要望して。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"吉田副委員長","kind":"確認","question":"今まで質疑もいたしましたけれども、いろいろな相談については既に実施されているということが確認できました。個別の聞きにくいことも聞きやすいだろうし、こちらのほうがいいのではないかということで、会派の結論は不採択ということになりました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"安藤委員","kind":"提案","question":"そしてさらにクリアな形で策定していく上で、すごく有効だと私は思いますので、しかも様々具体的な提案をされています。応募と公正な抽選による、ああいうタウンミーティングのような形でもいいのではないかという提案もされていますし、私は採択ということで主張しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"藤原委員","kind":"意見","question":"ただ、私はこの文章を受け止めました。どうしたらいいのかなという思いで、個人事業主の方たちをという思いで、議員としてやっていきたいなと改めて思いましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"なぜ私が不採択にしたかというと、今回は見送るという意味でも、不採択にします。結局政策決定となると、やり方も含めていろいろ考えていく必要があるのではないかなと思うので、今回の陳情に関しては不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"おぎの委員","kind":"意見","question":"ただ、実際に今、品川区としてはしっかりと様々な相談に一生懸命対応されているというのは、今お話を聞いて、思います。それは分かりましたので、様々な区民とつながる方法で、窓口をこの先も広く開けていってほしいなという部分はありますので、趣旨採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"できれば採択にしてほしいのですが、それが難しいのであれば。採択は難しいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"３点ぐらい提案と質問をしたいのですけれども、そのバッジ」という感じで、話のきっかけになると思うのです。もう少しこれは広げてもいいのではないかなと思うのですけれども、いかがか尋ねました。","respondent":"三井スポーツ推進課長","answer":"補正予算を組んで仮囲いアートを実施したということで、東五反田に今設置しておりますが、庁舎は今のところ考えていないところです。東京都もなかなか予算的に難しい面もあるのかもしれないですが…","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"日常的にどんな連携をとっているのかというのを伺いたいというのが１つと、きこえにくい人のためのオリンピック』なのです」と書いてあるのですよね。さらにデフリンピック啓発についても協力してもらうとか、そういうふうにしてはいかがでしょうかと思うのですが、この点も伺いたいと思います。","respondent":"三井スポーツ推進課長","answer":"基本的に障害者支援課とは情報共有しておりまして、特にイベントを実施するに当たっては、どうしても手話通訳を配置する必要があります。高齢者地域支援課との連携というのもあるのですが、高齢者地域支援課と連携していただくというのが第一義的なところかと思いますが。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"よろしくお願いしたいと思います。３つある中で、どういう点に力を入れる、そこら辺を伺えればと思います。","respondent":"三井スポーツ推進課長","answer":"耳が聞こえないことで、競技をする上で、聞こえる方より情報が圧倒的に少ないということがあります。実際、デフスポーツを啓発する中で、そういった違いとかを啓発のパネルとかで説明できればなというのは考えているのですが。","id":"exchange-051"},{"speaker":"安藤委員","kind":"提案","question":"ありがとうございました。今、幾つか提案もさせていただいたのですが、目的を達成できるような大会の成功に向けてよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"せお委員","kind":"質問","question":"認知度が今の状況では低いということで、本当に様々取り組んでいただいていて、ありがたいなと思うところです。どういう関わり、何か考えていることがあれば、教育委員会との連携を説明を求めました。","respondent":"三井スポーツ推進課長","answer":"５００日前イベントを東京都が実施しまして、それを今回、台場小学校で実施することができました。校長先生とも調整して、品川区のほうで手を挙げて、デフ陸上のスタートランプの体験等も台場小学校のお子さんたちに実施していただいたところです。","id":"exchange-053"},{"speaker":"せお委員","kind":"意見","question":"パラスポーツは今現在も幅広く取り組んでくださっていることも理解していますので、またそういったところでも、大会後の周知啓発といったところも継続してぜひとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"ゆきた委員","kind":"質問","question":"１２０％というふうに進められているので、全小学校とか、１つでも多くの小学校に進められていくような取組を進めていただければという思いです。この辺について、改めてお聞きできればと思います。","respondent":"三井スポーツ推進課長","answer":"やはりデフリンピック認知度１２０％ということで、区内の小学生・中学生にそういったことを伝えるというのは重要だと考えています。そういうことで認知度がさらに上がっていくのではないかと思いますので、引き続き教育委員会とは連携していきたいと考えております。","id":"exchange-055"},{"speaker":"石田（し）委員","kind":"質問","question":"先ほどから教育委員会との話が出ているのだけれども、先月、９月から１０月の間に、デフリンピックのメダルのデザインの投票が全国の学校でやられたというのがあるのだけれども、品川区はどういう取組をされたのか、また、所管としてどういう連携をとったのか、説明を求めました。","respondent":"三井スポーツ推進課長","answer":"それは東京都が実施しているもので、品川区のほうに連絡が来るのが直前だったというのもありまして、なかなか周りと、教育委員会のほうとは連携できていない状況になっています。","id":"exchange-056"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"その点どのように考えているのか教えていただきたいのと、いわゆる競技キャラクターというのですか、各イベントで周知をしていく。これをやはりどんどん皆さんで発掘して、つくっていっていただきたいなと思うけれども、その辺も含めて、説明を求めました。","respondent":"三井スポーツ推進課長","answer":"まだ検討しているところですが、来年の予算編成を考えながら、どうしていくかというのは検討しているところです。もちろん地域活動課とも今連携していまして、一応大きな例として他部署の連携を入れていますが、できるところとは進めていきたいと考えております。","id":"exchange-057"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"南大井の人たちは歩いて行けるし、例えばしながわ水族館だって、しながわ水族館と会場で何かやろうと思ったらできるではないですか。１６.３％ですからね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"今、テレビを見れば防犯とかいろいろある中で、山ほどグッズをつくっているではないですか。そういうときこそ、防犯という意味も含めて、グッズを配って、よく私が、何であんないっぱいの種類をつくるのですかと言ったら、啓発ですと。","respondent":"小林地域産業振興課長、河合生活安全担当課長","answer":"郵便局とかのマスコットキャラクターにも今回出ていただいてという形であります。そういうところにまた来年、より多くのキャラクターが集まって、にぎやかにできればと考えています。 それぞれのイベントで、こちらも防犯、生活安全、そこのカラーに応じてできるように、連携してやっていきたいと思います。","id":"exchange-059"},{"speaker":"藤原委員","kind":"質問・要望","question":"来年またありますので、同じ質問が出ないように、しっかりやっていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/332921?Template=document&Id=6911#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":47002,"voices":145}}]);
